function ic(name, size) {
  const s = size || 24;
  if (ICONS_SOLID[name]) {
    return `<svg viewBox="0 0 24 24" width="${s}" height="${s}" fill="currentColor" stroke="none"><path d="${ICONS_SOLID[name]}"/></svg>`;
  }
  const d = ICONS[name] || ICONS.info;
  return `<svg viewBox="0 0 24 24" width="${s}" height="${s}" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="${d}"/></svg>`;
}

/* ---------------------------------------------------------
   SECURITY HELPER — منع XSS
--------------------------------------------------------- */
function esc(s) {
  return String(s == null ? "" : s).replace(/[&<>"']/g, (c) => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"
  }[c]));
}

/* تهريب مزدوج لقيمة تُوضع داخل نصّ JS داخل سمة HTML:  onclick="fn('...')"
   esc() وحدها لا تكفي هنا: المتصفح يفكّ ترميز السمة قبل أن يقرأها محرّك JS،
   فتعود ' كما هي ويخرج المهاجم من النصّ. لذا نهرّب لـ JS أولاً ثم لـ HTML. */
function jsAttr(s) {
  return esc(String(s == null ? "" : s).replace(/\\/g, "\\\\").replace(/'/g, "\\'"));
}
function val(sel, def) {
  const el = document.querySelector(sel);
  return el && el.value != null && el.value.trim() !== "" ? el.value.trim() : (def || "");
}

