function adminPrograms() {
  if (!cur("programs").length) {
    return `<div class="page">
      ${pageHead("البرامج والمستويات القرآنية", "بناء برامج مرنة بمستويات واتجاهات وقواعد انتقال", addBtn("إضافة برنامج جديد", "modal-program"))}
      <div class="card">${emptyState("لا توجد برامج بعد", "ابدأ ببناء أول برنامج قرآني مرن.")}</div>
    </div>`;
  }
  const cards = cur("programs").map(p => `<div class="card">
    <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:12px">
      <div style="display:flex;gap:11px;align-items:center">
        <div class="kpi-ico t-gold" style="margin:0">${ic("layers", 21)}</div>
        <div><strong style="font-size:15px">${esc(p.name)}</strong><div class="muted" style="font-size:12px">${p.levels} مستوى — ${p.assigned} طالب</div></div>
      </div>
      ${statusBadge(p.status)}
    </div>
    <div style="display:flex;gap:7px;flex-wrap:wrap;margin-bottom:6px">
      ${badge("اتجاه: " + p.direction, "b-teal")}
      ${badge(p.type, p.type === "مفتوحة" ? "b-blue" : "b-gray")}
      ${badge("انتقال: " + p.transition, p.transition === "تلقائي" ? "b-green" : "b-amber")}
    </div>
    <div class="muted" data-action="panel-program" data-id="${p.id}" style="font-size:12px;margin-top:8px;display:flex;align-items:center;gap:5px;cursor:pointer">${ic("eye", 14)} اضغط لعرض المستويات</div>
    <div class="row-actions" style="margin-top:12px">
      <button class="btn btn-ghost btn-sm" data-action="edit-program" data-id="${p.id}">${ic("edit", 15)} تعديل</button>
      <button class="btn btn-danger btn-sm" data-action="delete-program" data-id="${p.id}">${ic("x", 15)} حذف</button>
    </div>
  </div>`).join("");

  return `<div class="page">
    ${pageHead("البرامج والمستويات القرآنية", "بناء برامج مرنة بمستويات واتجاهات وقواعد انتقال", addBtn("إضافة برنامج جديد", "modal-program"))}
    ${noteCard("هذا النظام يدعم بناء <strong>برامج مرنة</strong> بمستويات متعددة، واتجاهات مختلفة (تصاعدي / تنازلي)، وانتقال تلقائي أو مشروط حسب سياسة الإدارة.")}
    <div style="height:16px"></div>
    <div class="grid g-3 stagger">${cards}</div>
  </div>`;
}

