function selField(label, opts, req) {
  return `<div class="field"><label>${esc(label)}${req ? ' <span class="req">*</span>' : ""}</label><select>${opts.map(o => `<option>${esc(o)}</option>`).join("")}</select></div>`;
}


const DOW = ["السبت", "الأحد", "الإثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة"];
const DUTY_META = {
  "حفظ جديد": { cls: "d-memorize", color: "var(--danger)", short: "حفظ" },
  "مراجعة":   { cls: "d-review",   color: "var(--brand-main)", short: "مراجعة" },
  "تثبيت":    { cls: "d-fix",      color: "var(--gold)", short: "تثبيت" },
  "تلاوة":    { cls: "d-recite",   color: "var(--info)", short: "تلاوة" },
  "تعويض":    { cls: "d-comp",     color: "var(--purple)", short: "تعويض" }
};
const HEALTH = {
  healthy: { label: "صحية", cls: "b-green", tint: "t-green", ic: "checkCircle" },
  review:  { label: "تحتاج مراجعة", cls: "b-amber", tint: "t-amber", ic: "alert" },
  blocked: { label: "محظورة", cls: "b-red", tint: "t-red", ic: "lock" },
  frozen:  { label: "مجمدة", cls: "b-gray", tint: "t-purple", ic: "freeze" }
};

let PLAN_EXTRA = {};
const SAMPLE_PLAN_EXTRA = {};

function planAttType(p) {
  const s = DB.students.find(x => x.name === p.student);
  return s ? s.attType : "دوام كامل";
}

function getPlan(id) {
  const p = DB.plans.find(x => x.id == id);
  if (!p) return null;
  let ext = PLAN_EXTRA[id];
  if (!ext) ext = defaultExtra(p);
  return Object.assign({}, p, { ext });
}
function defaultExtra(p) {
  const partial = planAttType(p) === "دوام جزئي";
  const days = partial ? ["الأحد", "الثلاثاء"] : ["السبت", "الأحد", "الإثنين", "الثلاثاء", "الأربعاء", "الخميس"];
  const sched = {};
  DOW.forEach(d => { sched[d] = days.includes(d) ? ["حفظ جديد", "مراجعة", "تثبيت"] : []; });
  const map = { "نشطة": "healthy", "تحتاج مراجعة": "review", "متوقفة": "frozen" };
  const health = p.delays > 0 ? "blocked" : (map[p.status] || "healthy");
  return {
    health,
    healthReason: "خطة جديدة تم إنشاؤها للتو من باني الخطط.",
    healthAction: "تابع أول جلسة تسميع لتقييم سير الخطة.",
    sched,
    rules: { tilawah: true, fixation: true, lowEval: true, absence: true, partial: true, openBlocks: true },
    transition: { mode: "supervisor", test: false, noDelays: true, minScore: 7 },
    history: [{ by: USER_NAME[STATE.iface] || "مدير النظام", role: "مدير النظام", dt: "الآن", field: "إنشاء الخطة", before: "—", after: "خطة نشطة", reason: "إنشاء عبر باني الخطط" }],
    requests: [],
    today: [
      { type: "حفظ جديد", range: p.current, why: "اليوم من أيام الحفظ المجدولة.", status: "لم يبدأ" },
      { type: "مراجعة", range: "المقطع السابق", why: "مراجعة دورية مجدولة.", status: "لم يبدأ" }
    ],
    tomorrow: [{ type: "حفظ جديد", range: "المقطع التالي", why: "تقدم متوقع بعد اجتياز تسميع اليوم." }]
  };
}

function adminPlans() {
  if (STATE.planId != null) return planDetailPage(STATE.planId);
  const tabs = [
    { id: "active", label: "الخطط النشطة" },
    { id: "new", label: "باني الخطة" },
    { id: "comp", label: "المتأخرات والتعويض" },
    { id: "review", label: "مراجعة الخطط" }
  ];
  const cur = STATE.tab.plans || "active";
  const tabBar = `<div class="tabs">${tabs.map(t => `<button class="tab ${t.id === cur ? "active" : ""}" data-action="tab" data-group="plans" data-tab="${t.id}">${esc(t.label)}</button>`).join("")}</div>`;
  return `<div class="page">
    ${pageHead("خطط الطلاب القرآنية", "قلب النظام: خطط مرنة بمسارات وقواعد ومراحل قابلة للتخصيص بالكامل")}
    ${(cur === "active" && (DB.plans || []).length)
      ? `<div style="margin-bottom:14px"><button class="btn btn-primary btn-sm"
          onclick="window.bulkAssign()">${ic("users", 15)} إسناد خطة لعدّة طلاب</button></div>`
      : ""}
    ${tabBar}
    <div id="plansPanel">${plansTab(cur)}</div>
  </div>`;
}
function plansTab(id) {
  if (id === "new") return planBuilder();
  if (id === "comp") return planCompTab();
  if (id === "review") return planReviewTab();
  return planActiveTab();
}
function rerenderPlansPanel() {
  const panel = document.querySelector("#plansPanel");
  if (panel) { panel.innerHTML = plansTab(STATE.tab.plans || "active"); runAnimations(panel); }
}

function planActiveTab() {
  if (!DB.plans.length) {
    return `<div class="tab-panel"><div class="card">${emptyState("لا توجد خطط بعد", "أنشئ أول خطة من تبويب «باني الخطة». يلزم وجود طالب واحد وبرنامج واحد على الأقل.")}</div></div>`;
  }
  const rows = DB.plans.map(p => {
    const pl = getPlan(p.id);
    const h = HEALTH[pl.ext.health];
    return `<tr>
    <td><div class="td-name"><div class="mini-avatar">${initials(p.student)}</div><div><div class="td-strong">${esc(p.student)}</div><div class="muted" style="font-size:11.5px">${esc(p.circle)}</div></div></div></td>
    <td style="font-size:12.5px">${esc(p.program)}<div class="muted" style="font-size:11.5px">${esc(p.level)}</div></td>
    <td style="font-size:12px">${esc(p.start)} ← <strong>${esc(p.current)}</strong> ← ${esc(p.end)}</td>
    <td style="min-width:115px">${progressRow(p.progress)}</td>
    <td class="center">${p.delays > 0 ? badge(p.delays, "b-red") : badge("0", "b-gray")}</td>
    <td>${badge(h.label, h.cls)}</td>
    <td><div class="row-actions">
      <button class="btn btn-soft btn-sm" data-action="plan-open" data-id="${p.id}">${ic("eye", 15)} عرض الخطة</button>
    </div></td>
  </tr>`;
  }).join("");
  return `<div class="tab-panel">
    <div class="table-wrap"><div class="table-scroll"><table class="data">
      <thead><tr><th>الطالب</th><th>البرنامج والمستوى</th><th>مسار الخطة</th><th>التقدم</th><th>متأخرات</th><th>صحة الخطة</th><th></th></tr></thead>
      <tbody>${rows}</tbody>
    </table></div></div>
  </div>`;
}

function planDetailPage(id) {
  const pl = getPlan(id);
  if (!pl) { STATE.planId = null; return adminPlans(); }
  const h = HEALTH[pl.ext.health];
  const frozen = planIsFrozen(pl);
  const blocked = pl.ext.health === "blocked";

  return `<div class="page">
    <div style="margin-bottom:16px"><button class="btn btn-ghost btn-sm" data-action="plan-back">${ic("arrowLeft", 15)} رجوع لقائمة الخطط</button></div>

    <div class="plan-hero">
      <div class="plan-hero-main">
        <div style="display:flex;gap:13px;align-items:center">
          <div class="avatar" style="width:52px;height:52px;font-size:18px">${initials(pl.student)}</div>
          <div>
            <h2 style="font-size:21px;font-weight:800">${esc(pl.student)}</h2>
            <div class="muted" style="font-size:13px">${esc(pl.circle)} · ${esc(pl.program)} — ${esc(pl.level)}</div>
          </div>
        </div>
        <div class="plan-path">
          <div class="pp-node"><small>البداية</small><strong>${esc(pl.start)}</strong></div>
          <div class="pp-line">${ic("arrowLeft", 16)}</div>
          <div class="pp-node cur"><small>الموضع الحالي</small><strong>${esc(pl.current)}</strong></div>
          <div class="pp-line">${ic("arrowLeft", 16)}</div>
          <div class="pp-node"><small>النهاية</small><strong>${esc(pl.end)}</strong></div>
        </div>
        <div style="margin-top:14px;max-width:420px">
          <div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:5px"><span class="muted">نسبة الإنجاز</span><strong style="color:var(--brand-dark)">${pl.progress}%</strong></div>
          ${progressRow(pl.progress, "gold")}
        </div>
      </div>
      <div class="plan-health ${h.tint}">
        <div class="ph-badge">${ic(h.ic, 18)} ${h.label}</div>
        <div class="ph-row"><span>المقدار اليومي</span><strong>${esc(pl.amount)} (${esc(pl.unit)})</strong></div>
        <div class="ph-row"><span>المتأخرات</span><strong>${pl.delays > 0 ? pl.delays + " مفتوحة" : "لا يوجد"}</strong></div>
        <div class="ph-reason"><strong>السبب:</strong> ${esc(pl.ext.healthReason)}</div>
        <div class="ph-reason action"><strong>الإجراء الموصى به:</strong> ${esc(pl.ext.healthAction)}</div>
      </div>
    </div>

    <div class="plan-actions">
      <button class="btn btn-primary btn-sm" data-action="modal-edit-path" data-id="${id}">${ic("edit", 15)} تعديل المسار</button>
      <button class="btn ${frozen ? "btn-soft" : "btn-ghost"} btn-sm" data-action="modal-freeze" data-id="${id}">${ic("freeze", 15)} ${frozen ? "إعادة التفعيل" : "تجميد الخطة"}</button>
      <button class="btn btn-ghost btn-sm" data-action="modal-add-comp" data-id="${id}">${ic("plus", 15)} إضافة تعويض</button>
      <button class="btn btn-gold btn-sm" data-action="modal-promote" data-id="${id}">${ic("trophy", 15)} اعتماد ترقية</button>
      <button class="btn btn-ghost btn-sm" data-action="modal-daily-duties" data-id="${id}">${ic("book", 15)} معاينة واجبات اليوم</button>
    </div>

    ${blocked ? `<div class="block-banner">${ic("lock", 18)} <div><strong>الخطة محظورة من التقدم.</strong> يوجد تعويض مفتوح يمنع توليد واجبات جديدة حتى إغلاقه أو تأجيله.</div></div>` : ""}

    <div class="grid g-2" style="align-items:start;margin-bottom:6px">
      <div class="section"><div class="section-head"><h3>قواعد الخطة</h3></div>${planRulesCard(pl)}</div>
      <div class="section"><div class="section-head"><h3>قواعد الانتقال للمستوى</h3></div>${transitionCard(pl)}</div>
      <div class="section"><div class="section-head"><h3>تكرار السورة والمستوى</h3></div>${planRepeatCard(pl)}</div>
    </div>

    <div class="section"><div class="section-head"><h3>معاينة الجدول الأسبوعي</h3>
      <span class="muted" style="font-size:12px">${planAttType(pl) === "دوام جزئي" ? "طالب دوام جزئي — الأيام غير المجدولة محايدة" : "دوام كامل"}</span></div>
      ${planTimeline(pl)}
    </div>

    <div class="section"><div class="section-head"><h3>الواجبات المولّدة من الخطة</h3></div>
      ${dailyDutiesContent(pl)}
    </div>

    <div class="section"><div class="section-head"><h3>طلبات تعديل الخطة</h3>
      <span class="badge ${pl.ext.requests.filter(r => r.status === "pending").length ? "b-amber" : "b-gray"} no-dot">${pl.ext.requests.filter(r => r.status === "pending").length} قيد الانتظار</span></div>
      ${planRequests(pl)}
    </div>

    <div class="section"><div class="section-head"><h3>سجل تغييرات الخطة</h3></div>
      ${planHistory(pl)}
    </div>
  </div>`;
}

/* =========================================================================
   قواعد الخطة — من قاعدة البيانات لا من الذاكرة
   -------------------------------------------------------------------------
   كانت تُقرأ من PLAN_EXTRA: كائنٍ في الذاكرة بقيمٍ ثابتة مكتوبة في الكود.
   تُعرض «مفعّلة» أبداً ولا سبيل لتعطيلها، وتضيع مع كل إعادة تحميل.
   ========================================================================= */
/* =========================================================================
   التجميد: مصدر واحد
   -------------------------------------------------------------------------
   نظامان تجمَّدت بهما الخطة: القديم ext.health="frozen" في الذاكرة يكتبه
   زر «تجميد» في بطاقة الصحة، والجديد p.frozen في قاعدة البيانات يقرؤه
   محرّك الواجبات. فيُجمَّد بأحدهما ويظلّ المحرّك يولّد الواجبات.

   الحقل المحفوظ هو الحكم — والذاكرة تتبعه. */
/* =========================================================================
   إسناد خطة واحدة لعدّة طلاب
   -------------------------------------------------------------------------
   كانت الخطة واحداً لواحد: studentId مفرد، فمن أراد خطةً لعشرين طالباً
   أنشأها عشرين مرة، وأيّ تعديل عليها يُعاد عشرين مرة.

   الحلّ: الخطة تصير قالباً يُنسخ. لكلّ طالبٍ نسخته — لأن موضعه يتقدّم
   وحده وتقييمه يخصّه — وتبقى مربوطةً بالقالب عبر templateId، فتعديل
   القالب يسري على من لم يبدأ بعد، ومن بدأ يبقى على موضعه.

   نسخةٌ لكلٍّ لا سجلٌّ مشترك: المشترك يعني أن تقدّم طالبٍ يزحزح البقية.
   ========================================================================= */

const BULK = { plan: "", picked: {}, filterCircle: "", q: "" };

window.bulkPick = function (id, on) { BULK.picked[String(id)] = !!on; };
window.bulkSet = function (k, v) { BULK[k] = String(v || ""); bulkRender(); };

window.bulkAll = function (on) {
  bulkCandidates().forEach(s => { BULK.picked[String(s.id)] = !!on; });
  bulkRender();
};

/* من يصلح للإسناد: النشطون بلا خطة، أو بخطةٍ من قالبٍ آخر */
function bulkCandidates() {
  let list = (cur("students") || []).filter(s => s && s.status !== "متوقف");

  if (BULK.filterCircle) {
    list = list.filter(s => String(s.circleId) === String(BULK.filterCircle) ||
                            String(s.circle) === String(BULK.filterCircle));
  }
  if (BULK.q) list = list.filter(s => String(s.name || "").indexOf(BULK.q) > -1);

  return list;
}

function bulkPlanOf(st) {
  return (cur("plans") || []).find(p =>
    String(p.studentId) === String(st.id) ||
    (p.student && nameKey(p.student) === nameKey(st.name))) || null;
}

/* الفتح من زر في صفحة الخطط */
window.bulkAssign = function (planId) {
  const plans = (cur("plans") || []).filter(p => p);
  if (!plans.length) { showToast("أنشئ خطةً أولاً لتُسند لغيره", "warn"); return; }

  BULK.plan = String(planId || (plans[0] && plans[0].id) || "");
  BULK.picked = {};
  bulkRender();
};

function bulkRender() {
  const plans = (cur("plans") || []).filter(p => p);
  const src = plans.find(p => String(p.id) === String(BULK.plan));
  const cands = bulkCandidates();
  const circles = cur("circles") || [];

  const n = cands.filter(s => BULK.picked[String(s.id)]).length;

  const rows = cands.map(s => {
    const has = bulkPlanOf(s);
    const same = has && src && String(has.templateId || has.id) === String(src.templateId || src.id);
    return `<tr>
      <td class="pt-check"><label class="switch">
        <input type="checkbox"${BULK.picked[String(s.id)] ? " checked" : ""}
          onchange="window.bulkPick('${jsAttr(s.id)}',this.checked)">
        <span class="slider"></span></label></td>
      <td><strong>${esc(s.name || "—")}</strong></td>
      <td class="muted">${esc(s.circle || "—")}</td>
      <td>${same ? '<span class="pt-badge on">عليها بالفعل</span>'
        : has ? `<span class="pt-badge off">له خطة: ${esc(has.program || has.level || "—")}</span>`
        : (x.attOnly ? '<span class="chip t-blue">تحضير فقط</span>'
                     : '<span class="muted">بلا خطة</span>')}</td>
    </tr>`;
  }).join("");

  openModal("إسناد خطة لعدّة طلاب",
    "نسخةٌ لكلّ طالب — يتقدّم كلٌّ بموضعه",
    `<div class="form-grid">
       <div class="field full"><label>الخطة المصدر</label>
         <select onchange="window.bulkSet('plan',this.value)">
           ${plans.map(p => `<option value="${esc(p.id)}"${
             String(BULK.plan) === String(p.id) ? " selected" : ""}>${
             esc(p.student || "—")} — ${esc(p.program || "")}${
             p.level ? " · " + esc(p.level) : ""}</option>`).join("")}
         </select></div>

       <div class="field"><label>تصفية بالحلقة</label>
         <select onchange="window.bulkSet('filterCircle',this.value)">
           <option value="">كل الحلقات</option>
           ${circles.map(c => `<option value="${esc(c.id)}"${
             BULK.filterCircle === String(c.id) ? " selected" : ""}>${esc(c.name)}</option>`).join("")}
         </select></div>

       <div class="field"><label>بحث</label>
         <input value="${esc(BULK.q)}" placeholder="اسم الطالب"
           oninput="window.bulkSet('q',this.value)"></div>
     </div>

     ${src ? noteCard(`تُنسخ إعدادات خطة <strong>${esc(src.student || "")}</strong>:
       البرنامج والمستوى والمقدار والوحدة وموضع البداية.
       <br>من له خطة سابقة تُستبدل — وتقدّمه المرصود لا يُحذف.`) : ""}

     <div style="display:flex;gap:8px;margin:10px 0">
       <button class="btn btn-ghost btn-sm" onclick="window.bulkAll(true)">تحديد الكل</button>
       <button class="btn btn-ghost btn-sm" onclick="window.bulkAll(false)">إلغاء الكل</button>
       <span class="muted" style="margin-inline-start:auto;font-size:12.5px;align-self:center">
         ${toArabicDigits(n)} محدَّد من ${toArabicDigits(cands.length)}</span>
     </div>

     <div class="pt-wrap" style="max-height:320px;overflow:auto">
       <table class="ptable"><thead><tr><th></th><th>الطالب</th>
         <th>الحلقة</th><th>الحالة</th></tr></thead>
         <tbody>${rows || '<tr><td colspan="5" class="muted" style="text-align:center;padding:20px">لا طلاب</td></tr>'}</tbody>
       </table></div>`,

    `<button class="btn btn-primary" onclick="window.bulkAssignDo()">
       إسناد لـ${toArabicDigits(n)} طالباً</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
}

window.bulkAssignDo = function () {
  const src = (cur("plans") || []).find(p => String(p.id) === String(BULK.plan));
  if (!src) { showToast("اختر الخطة المصدر", "warn"); return; }

  const ids = Object.keys(BULK.picked).filter(k => BULK.picked[k]);
  if (!ids.length) { showToast("لم تحدّد طلاباً", "warn"); return; }

  /* القالب: الخطة المصدر نفسها إن لم تكن نسخةً من قالبٍ آخر */
  const tid = String(src.templateId || src.id);
  if (!src.templateId) { src.templateId = tid; persistSet("plans", src); }

  let made = 0, replaced = 0;

  ids.forEach((sid, i) => {
    const st = (cur("students") || []).find(x => String(x.id) === String(sid));
    if (!st) return;

    const old = bulkPlanOf(st);
    /* عليها بالفعل: لا يُنسخ فوق نفسه فيضيع تقدّمه */
    if (old && String(old.templateId || old.id) === tid) return;

    const rec = {
      id: old ? old.id : ("pl" + Date.now() + "-" + i),
      templateId: tid,
      complexId: st.complexId || STATE.complexId || "",
      studentId: String(st.id), student: st.name || "",
      circle: st.circle || "", circleId: st.circleId || "",

      /* المنسوخ من القالب */
      program: src.program || "", programId: src.programId || "",
      level: src.level || "", levelId: src.levelId || "",
      amount: src.amount, unit: src.unit,
      direction: src.direction || "forward",
      weeks: src.weeks || 0,
      fixLessons: src.fixLessons,
      hifzFromS: src.hifzFromS, hifzFromA: src.hifzFromA,
      start: src.start, current: src.start, end: src.end,

      /* لكلٍّ تقدّمه: لا يُنسخ من المصدر */
      progress: 0, delays: 0, status: "نشطة",
      frozen: false,
      ts: Date.now(),
      termId: typeof activeTermId === "function" ? activeTermId() : ""
    };

    if (old) {
      /* الاستبدال يحفظ ما أُنجز: التقدّم المرصود في assignments لا يُمسّ */
      rec.progress = old.progress || 0;
      rec.delays = old.delays || 0;
      replaced++;
    } else made++;

    if (!Array.isArray(DB.plans)) DB.plans = [];
    const k = DB.plans.findIndex(x => String(x.id) === String(rec.id));
    if (k > -1) DB.plans[k] = rec; else DB.plans.unshift(rec);
    persistSet("plans", rec);

    /* قواعد القالب تُنسخ كما هي */
    try {
      const srcRules = (cur("planRules") || []).find(r => String(r.planId) === String(src.id));
      if (srcRules) {
        const pr = { id: "pr_" + rec.id, planId: String(rec.id),
                     rules: Object.assign({}, srcRules.rules || {}), ts: Date.now() };
        if (!Array.isArray(DB.planRules)) DB.planRules = [];
        const q = DB.planRules.findIndex(x => String(x.planId) === String(rec.id));
        if (q > -1) DB.planRules[q] = pr; else DB.planRules.push(pr);
        persistSet("planRules", pr);
      }
    } catch (e) {}

    /* سجل الطالب يتبع خطته */
    if (rec.levelId) {
      st.levelId = rec.levelId; st.level = rec.level;
      st.program = rec.program;
      persistSet("students", st);
    }
  });

  closeModal();
  showToast("أُسندت الخطة: " + toArabicDigits(made) + " جديد" +
            (replaced ? " · " + toArabicDigits(replaced) + " مُستبدَل" : ""), "success");
  mount();
};

/* =========================================================================
   تعديل القالب يسري على نسخه
   ------------------------------------------------------------------------- */
function planSiblings(pl) {
  if (!pl) return [];
  const tid = String(pl.templateId || pl.id);
  return (cur("plans") || []).filter(p =>
    p && String(p.templateId || "") === tid && String(p.id) !== String(pl.id));
}

window.planSyncTemplate = function (planId) {
  const src = (cur("plans") || []).find(p => String(p.id) === String(planId));
  if (!src) return;

  const sibs = planSiblings(src);
  if (!sibs.length) { showToast("لا نسخ أخرى من هذه الخطة", "info"); return; }

  openModal("تعميم التعديل", src.student || "",
    noteCard(`تُنسخ إعدادات هذه الخطة إلى <strong>${toArabicDigits(sibs.length)}</strong>
      خطةً أخرى من القالب نفسه: البرنامج والمستوى والمقدار والوحدة والاتجاه.
      <br><strong>لا يُنسخ</strong> موضع كلّ طالب ولا تقدّمه — يبقى كلٌّ حيث وقف.`),
    `<button class="btn btn-primary" onclick="window.planSyncDo('${jsAttr(planId)}')">
       تعميم على ${toArabicDigits(sibs.length)}</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
};

window.planSyncDo = function (planId) {
  const src = (cur("plans") || []).find(p => String(p.id) === String(planId));
  if (!src) return;

  const keys = ["program", "programId", "level", "levelId", "amount", "unit",
                "direction", "weeks", "fixLessons"];
  let n = 0;

  planSiblings(src).forEach(p => {
    keys.forEach(k => { if (src[k] !== undefined) p[k] = src[k]; });
    persistSet("plans", p);
    n++;
  });

  closeModal();
  showToast("عُمّم التعديل على " + toArabicDigits(n) + " خطة", "success");
  mount();
};

/* =========================================================================
   مكتبة الخطط والمناهج
   -------------------------------------------------------------------------
   المواصفات: «الخطط قوالبٌ ثابتة في النظام، يجب أن تكون مستقلّةً عن
   الدورات. يُنشأ مكتبةٌ عامة تسمى مكتبة الخطط والمناهج، وفي الدورة الجديدة
   كلّ ما على الإدارة فعله الدخول على الطالب واختيار قالب الخطة المناسب من
   المكتبة مباشرة».

   والوظيفة كاملةٌ في النظام — templateId و bulkAssign و planSiblings —
   لكنها موزّعة بلا شاشةٍ تجمعها، فتُبحث القوالب في قائمة الخطط بين مئات
   خطط الطلاب. المكتبة تجمعها في موضعٍ واحد يُقصد.
   ========================================================================= */
function planTemplates() {
  const plans = cur("plans") || [];
  const seen = {};

  plans.forEach(p => {
    if (!p) return;
    const tid = String(p.templateId || "");
    if (!tid) return;
    if (!seen[tid]) {
      /* الأصل: الخطة التي معرّفها هو معرّف القالب، وإلا أقدم نسخة */
      const src = plans.find(x => String(x.id) === tid) || p;
      seen[tid] = { id: tid, src, uses: 0, students: [] };
    }
    seen[tid].uses++;
    if (p.student) seen[tid].students.push(p.student);
  });

  return Object.keys(seen).map(k => seen[k])
    .sort((a, b) => b.uses - a.uses);
}

/* خططٌ مفردة لم تُجعل قوالب بعد — يُعرض للإدارة أن تجعلها */
function soloPlans() {
  return (cur("plans") || []).filter(p => p && !p.templateId);
}

window.tplMake = function (planId) {
  const p = (cur("plans") || []).find(x => String(x.id) === String(planId));
  if (!p) return;

  openModal("جعلها قالباً", p.student || "",
    noteCard(`ستصير خطة <strong>${esc(p.student || "")}</strong> قالباً في المكتبة،
      فتُسند لغيره بضغطة دون إعادة كتابة تفاصيلها.
      <br>خطة الطالب نفسه لا تتغيّر.`),
    `<button class="btn btn-primary" onclick="window.tplMakeDo('${jsAttr(planId)}')">جعلها قالباً</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
};

window.tplMakeDo = function (planId) {
  const p = (cur("plans") || []).find(x => String(x.id) === String(planId));
  if (!p) return;
  p.templateId = String(p.id);
  p.templateName = p.program || p.level || p.student || "قالب";
  persistSet("plans", p);
  closeModal();
  showToast("صارت قالباً — أسندها من المكتبة", "success");
  mount();
};

window.tplRename = function (tid) {
  const t = planTemplates().find(x => x.id === tid);
  if (!t) return;

  openModal("تسمية القالب", "",
    `<input type="hidden" id="tp_id" value="${esc(tid)}">
     <div class="form-grid"><div class="field full"><label>اسم القالب</label>
       <input id="tp_name" value="${esc(t.src.templateName || t.src.program || "")}"
         placeholder="مثال: خطة حفظ جزء عمّ"></div></div>
     ${noteCard("الاسم يظهر في المكتبة وعند الإسناد — يُختار به القالب.")}`,
    `<button class="btn btn-primary" onclick="window.tplRenameDo()">حفظ</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
};

window.tplRenameDo = function () {
  const tid = val("#tp_id");
  const name = (val("#tp_name") || "").trim();
  if (!name) { showToast("الاسم مطلوب", "warn"); return; }

  /* الاسم يُكتب في كلّ نسخ القالب: البحث عنه يجري بها جميعاً */
  (DB.plans || []).forEach(p => {
    if (String(p.templateId || "") !== String(tid)) return;
    p.templateName = name;
    persistSet("plans", p);
  });

  closeModal();
  showToast("سُمّي القالب", "success");
  mount();
};

/* شاشة المكتبة */
function planLibrary() {
  const tpls = planTemplates();
  const solo = soloPlans();

  const card = t => {
    const p = t.src;
    return `<div class="tpl-card">
      <div class="tpl-head">
        <div>
          <strong>${esc(p.templateName || p.program || "قالب")}</strong>
          <div class="muted" style="font-size:11.5px">${
            [p.program, p.level].filter(Boolean).map(esc).join(" — ") || "—"}</div>
        </div>
        <span class="tpl-uses">${toArabicDigits(t.uses)} طالباً</span>
      </div>

      <div class="tpl-meta">
        ${p.amount ? `<span>${toArabicDigits(p.amount)} ${esc(p.unit || "وجه")} يومياً</span>` : ""}
        ${p.direction ? `<span>${dirOf(p.direction) === "backward" ? "تنازلي" : "تصاعدي"}</span>` : ""}
        ${p.fixLessons ? `<span>تثبيت ${toArabicDigits(p.fixLessons)} دروس</span>` : ""}
        ${p.weeks ? `<span>${toArabicDigits(p.weeks)} أسبوعاً</span>` : ""}
      </div>

      ${t.students.length ? `<div class="tpl-studs">${
        t.students.slice(0, 5).map(x => `<span>${esc(x)}</span>`).join("")}${
        t.students.length > 5 ? `<span class="more">+${toArabicDigits(t.students.length - 5)}</span>` : ""}
      </div>` : ""}

      <div class="tpl-acts">
        <button class="btn btn-primary btn-sm"
          onclick="window.bulkAssign('${jsAttr(p.id)}')">إسناده لطلاب</button>
        <button class="btn btn-ghost btn-sm"
          onclick="window.tplRename('${jsAttr(t.id)}')">تسميته</button>
      </div>
    </div>`;
  };

  return `<div class="page">
    ${pageHead("مكتبة الخطط والمناهج",
      "قوالبُ ثابتة مستقلّة عن الدورات — تُسند للطلاب بضغطة")}

    ${tpls.length
      ? `<div class="tpl-grid">${tpls.map(card).join("")}</div>`
      : `<div class="card">${emptyState("لا قوالب بعد",
          "اجعل خطةً قالباً من القائمة أدناه، فتُسند لغير صاحبها دون إعادة كتابتها.")}</div>`}

    ${solo.length ? `<div class="card" style="margin-top:18px">
      <div class="fac-toolbar">
        <div><strong style="font-size:15px">خطط مفردة</strong>
          <div class="muted" style="font-size:11.5px;margin-top:2px">
            ${toArabicDigits(solo.length)} خطةً لم تُجعل قوالب — كلٌّ لصاحبها وحده</div></div>
      </div>
      <div class="pt-wrap"><div class="pt-scroll"><table class="ptable">
        <thead><tr><th>الطالب</th><th>البرنامج</th><th>المستوى</th><th></th></tr></thead>
        <tbody>${solo.slice(0, 40).map(p => `<tr>
          <td><strong>${esc(p.student || "—")}</strong></td>
          <td class="muted">${esc(p.program || "—")}</td>
          <td class="muted">${esc(p.level || "—")}</td>
          <td class="pt-actions"><button class="btn btn-ghost btn-sm"
            onclick="window.tplMake('${jsAttr(p.id)}')">جعلها قالباً</button></td>
        </tr>`).join("")}</tbody>
      </table></div></div>
    </div>` : ""}
  </div>`;
}

function planIsFrozen(pl) {
  if (!pl) return false;
  if (pl.frozen === true) return true;
  return !!(pl.ext && pl.ext.health === "frozen");
}

/* =========================================================================
   تخصيصُ التكرار لخطةٍ بعينها
   -------------------------------------------------------------------------
   repeatCfg تقرأ plan.repeatMode و plan.repeatTimes و plan.repeatOff وتقدّمها
   على إعداد البرنامج — ولا شيء في النظام كلِّه يكتبها: التخصيصُ مذكورٌ في
   التعليق ولا سبيل إليه. هذه بطاقتُه.
   ========================================================================= */
window.planRepeatSet = function (planId, field, value) {
  const p = (cur("plans") || []).find(x => String(x.id) === String(planId));
  if (!p) return;

  const r = ((STATE && STATE.user) || {}).role || "";
  if (!(r === "admin" || r === "owner" || isMgrRole(r))) {
    showToast("تعديل التكرار من صلاحية الإدارة", "warn"); return;
  }

  if (field === "off") {
    p.repeatOff = !!value;
  } else if (field === "mode") {
    const v = String(value || "");
    if (v) { p.repeatMode = v; p.repeatOff = false; }
    else delete p.repeatMode;      /* الفراغُ رجوعٌ إلى إعداد البرنامج */
  } else if (field === "times") {
    p.repeatTimes = Math.max(1, Math.min(10, Number(value) || 1));
  }

  persistSet("plans", p);
  mount();
};

function planRepeatCard(pl) {
  const cfg = repeatCfg(pl);
  const own = !!pl.repeatMode;
  const src = pl.repeatOff ? "معفاةٌ من التكرار"
            : own ? "خاصٌّ بهذه الخطة"
            : cfg.mode ? "موروثٌ من البرنامج" : "لا تكرار";

  return `<div class="card"><div style="padding:14px 16px;display:grid;gap:10px">
    <div class="uv-row"><span>الحالة</span><strong>${esc(src)}</strong></div>
    <div class="pl-fields">
      <div class="pl-f"><label>نمط التكرار</label>
        <select onchange="window.planRepeatSet('${jsAttr(pl.id)}','mode',this.value)">
          <option value=""${own ? "" : " selected"}>— كما في البرنامج —</option>
          ${REPEAT_MODES.filter(m => m.k).map(m =>
            `<option value="${esc(m.k)}"${pl.repeatMode === m.k ? " selected" : ""}>${esc(m.h)}</option>`).join("")}
        </select></div>
      <div class="pl-f"><label>عدد المرات</label>
        <input type="number" min="1" max="10" dir="ltr"
          value="${esc(Number(pl.repeatTimes) || cfg.times || 1)}"
          onchange="window.planRepeatSet('${jsAttr(pl.id)}','times',this.value)"></div>
    </div>
    <label class="manu-same">
      <input type="checkbox"${pl.repeatOff ? " checked" : ""}
        onchange="window.planRepeatSet('${jsAttr(pl.id)}','off',this.checked)">
      <span>إعفاء هذا الطالب من التكرار</span>
      <small>يتجاوز السورة أو المستوى دون إعادة ولو أوجبها برنامجُه</small>
    </label>
    ${noteCard(cfg.mode
      ? "يُعاد " + (cfg.mode === "surah" ? "كلُّ سورةٍ" : "المستوى كاملاً") +
        " " + toArabicDigits(cfg.times) + " مرّة بعد بلوغ آخرها، ثمّ يمضي."
      : "لا إعادة: يمضي إلى ما بعد السورة فور بلوغ آخرها.")}
  </div></div>`;
}

function planRulesCard(pl) {
  const on = planRulesOf(pl.id);
  const canEdit = (() => {
    const r = ((STATE && STATE.user) || {}).role || "";
    return r === "admin" || r === "owner" || isMgrRole(r);
  })();

  return `<div class="card"><div class="rule-list">
    ${PLAN_RULE_DEFS.map(x => `<div class="rule-row ${on[x.k] ? "" : "off"}">
      <span class="rule-ico">${ic("check", 15)}</span>
      <div class="rule-text"><strong>${esc(x.h)}</strong><small>${esc(x.d)}</small></div>
      ${canEdit
        ? `<label class="switch"><input type="checkbox"${on[x.k] ? " checked" : ""}
            onchange="window.planRuleToggle('${jsAttr(pl.id)}','${esc(x.k)}',this.checked)">
           <span class="slider"></span></label>`
        : `<span class="badge ${on[x.k] ? "b-green" : "b-gray"} no-dot">${
            on[x.k] ? "مفعّلة" : "معطّلة"}</span>`}
    </div>`).join("")}
  </div></div>`;
}

function transitionCard(pl) {
  const prog = levelProgress(pl);
  const next = nextLevelOf(pl);
  const canEdit = (() => {
    const r = ((STATE && STATE.user) || {}).role || "";
    return r === "admin" || r === "owner" || isMgrRole(r);
  })();

  /* كانت البطاقة تعرض شروطاً ثابتة وتقول «لن يُرقّى» بلا زرٍّ يرقّي */
  return `<div class="card">
    ${prog
      ? `<div class="lvp">
          <div class="lvp-head">
            <strong>${esc(prog.level.name)}</strong>
            <span>${toArabicDigits(prog.done)} / ${toArabicDigits(prog.need)} ${
              esc(prog.level.unit || "وجه")}</span>
          </div>
          <div class="lvp-bar"><i style="width:${prog.pct}%"></i></div>
          <div class="lvp-pct">${toArabicDigits(prog.pct)}٪${
            prog.complete ? " · اكتمل المستوى" : ""}</div>
        </div>`
      : `<div class="muted" style="font-size:12.5px;padding:4px 0">
          لا مقدار محدَّد لهذا المستوى، فلا تُقاس نسبة إنجازه.
          حدّده من الإعدادات ← البرامج والمستويات.</div>`}

    <div class="divider"></div>

    ${(() => {
      const rp = typeof repeatState === "function" ? repeatState(pl) : null;
      if (!rp) return "";
      return `<div class="rep-state">
        <strong>${esc(rp.modeAr)}</strong>
        <span>${toArabicDigits(rp.done)} من ${toArabicDigits(rp.times)}${
          rp.surah ? " — " + esc(rp.surah) : ""}</span>
        ${rp.done >= rp.times
          ? `<em class="ok">أتمّ التكرار — يتجاوز</em>`
          : `<em>يعيد ${toArabicDigits(rp.times - rp.done)} مرة قبل التجاوز</em>`}
      </div>`;
    })()}

    ${planSchedulePanel(pl)}

    ${gateCard(pl)}

    <div class="trans-grid">
      <div class="trans-item"><span class="muted">المستوى التالي</span>
        ${next ? badge(next.name, "b-teal") : badge("لا يوجد", "b-gray")}</div>
      <div class="trans-item"><span class="muted">حالة الخطة</span>
        ${planIsFrozen(pl) ? badge("مجمَّدة", "b-red") : badge("سارية", "b-green")}</div>
    </div>

    ${canEdit ? `<div class="divider"></div>
      <div style="display:flex;gap:8px;flex-wrap:wrap">
        ${next ? `<button class="btn btn-primary btn-sm"
          onclick="window.planPromote('${jsAttr(pl.id)}')">ترقية المستوى</button>` : ""}
        <button class="btn btn-ghost btn-sm"
          onclick="window.planFreeze('${jsAttr(pl.id)}')">${
          planIsFrozen(pl) ? "فكّ التجميد" : "تجميد الخطة"}</button>
        ${planSiblings(pl).length ? `<button class="btn btn-ghost btn-sm"
          onclick="window.planSyncTemplate('${jsAttr(pl.id)}')">
          تعميم على ${toArabicDigits(planSiblings(pl).length)} نسخة</button>` : ""}
      </div>` : ""}
  </div>`;
}

function planTimeline(pl) {
  const partial = planAttType(pl) === "دوام جزئي";
  const cols = DOW.map(d => {
    const duties = (pl.ext.sched && pl.ext.sched[d]) || [];
    const off = duties.length === 0;
    const isToday = d === "الأحد";
    return `<div class="tl-col ${off ? "off" : ""} ${isToday ? "today" : ""}">
      <div class="tl-dow">${d}${isToday ? ' <span class="tl-now">اليوم</span>' : ""}</div>
      <div class="tl-body">
        ${off ? `<div class="tl-empty">${partial ? "غير مجدول" : "راحة"}</div>`
              : duties.map(x => DUTY_META[x] ? `<div class="tl-duty ${DUTY_META[x].cls}"><span></span>${DUTY_META[x].short}</div>` : "").join("")}
      </div>
    </div>`;
  }).join("");
  return `<div class="card" style="padding:14px">
    <div class="tl-week">${cols}</div>
    <div class="split-legend" style="margin-top:14px">
      ${Object.keys(DUTY_META).map(k => `<span><i style="background:${DUTY_META[k].color}"></i> ${k}</span>`).join("")}
      <span><i style="background:#dfe4e4"></i> ${partial ? "يوم غير مجدول" : "راحة"}</span>
    </div>
  </div>`;
}

function dailyDutiesContent(pl) {
  const dutyCard = (x) => `<div class="duty-card ${DUTY_META[x.type] ? DUTY_META[x.type].cls : ""}">
    <div class="dh"><strong>${esc(x.type)}</strong>${x.status ? badge(x.status, x.status === "تم" ? "b-green" : x.status === "متأخر" || x.status === "محظور" ? "b-red" : x.status === "مجمد" ? "b-gray" : "b-amber") : ""}</div>
    <div class="duty-range">${esc(x.range)}</div>
    <div class="dnote">${ic("info", 13)} ${esc(x.why)}</div>
    ${x.blocks ? `<div class="duty-block">${ic("lock", 13)} هذا التعويض يمنع تقدم الخطة</div>` : ""}
  </div>`;
  const compOpen = pl.ext.today.some(d => d.blocks);
  return `
    ${compOpen ? `<div class="block-banner soft">${ic("alert", 17)} <div>يوجد <strong>تعويض مفتوح</strong> ضمن واجبات اليوم.</div></div>` : ""}
    <div class="grid g-2" style="align-items:start">
      <div>
        <div class="duties-col-head">${ic("book", 15)} واجب اليوم — الأحد</div>
        <div class="grid" style="gap:11px">${pl.ext.today.length ? pl.ext.today.map(dutyCard).join("") : `<div class="muted">لا توجد واجبات اليوم.</div>`}</div>
      </div>
      <div>
        <div class="duties-col-head next">${ic("calendar", 15)} واجب الغد — الإثنين <span class="muted" style="font-weight:400;font-size:11.5px">(متوقع)</span></div>
        <div class="grid" style="gap:11px">${pl.ext.tomorrow.length ? pl.ext.tomorrow.map(dutyCard).join("") : `<div class="muted" style="font-size:13px">لا واجبات متوقعة.</div>`}</div>
      </div>
    </div>`;
}

function planRequests(pl) {
  if (!pl.ext.requests.length) return `<div class="card">${emptyState("لا توجد طلبات", "لم يتقدّم المعلم بأي طلب لتعديل هذه الخطة.")}</div>`;
  const sb = { pending: ["قيد الانتظار", "b-amber"], approved: ["مقبول", "b-green"], rejected: ["مرفوض", "b-red"] };
  return `<div class="grid" style="gap:11px">${pl.ext.requests.map((r, i) => `<div class="req-card ${r.status}">
    <div class="req-top">
      <div style="display:flex;gap:10px;align-items:center"><div class="mini-avatar">${initials(r.by)}</div>
        <div><strong style="font-size:13.5px">${esc(r.by)}</strong><div class="muted" style="font-size:11.5px">${esc(r.role)} · ${esc(r.dt)}</div></div></div>
      ${badge(sb[r.status][0], sb[r.status][1])}
    </div>
    <div class="req-change">${ic("edit", 14)} <strong>التعديل المطلوب:</strong> ${esc(r.change)}</div>
    <div class="muted" style="font-size:12.5px;margin-top:5px">السبب: ${esc(r.reason)}</div>
    ${r.status === "pending" ? `<div class="req-actions">
      <button class="btn btn-primary btn-sm" data-action="req-approve" data-id="${pl.id}" data-i="${i}">${ic("check", 14)} موافقة</button>
      <button class="btn btn-danger btn-sm" data-action="req-reject" data-id="${pl.id}" data-i="${i}">${ic("x", 14)} رفض</button>
    </div>` : ""}
  </div>`).join("")}</div>`;
}

function planHistory(pl) {
  if (!pl.ext.history.length) return `<div class="card"><div class="muted">لا يوجد سجل تغييرات بعد.</div></div>`;
  return `<div class="card"><div class="timeline" style="padding-right:24px">${pl.ext.history.map((h, i) => `<div class="tl-item ${i === 0 ? "current" : "done"}" style="padding-bottom:20px">
    <div class="tl-dot"></div>
    <div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px">
      <strong>${esc(h.field)}</strong>
      <span class="muted" style="font-size:11.5px">${esc(h.by)} · ${esc(h.role)} · ${esc(h.dt)}</span>
    </div>
    <div class="hist-change"><span class="hist-before">${esc(h.before)}</span>${ic("arrowLeft", 13)}<span class="hist-after">${esc(h.after)}</span></div>
    <small class="muted">السبب: ${esc(h.reason)}</small>
  </div>`).join("")}</div></div>`;
}

/* =========================================================
   PLAN BUILDER
   ========================================================= */
const builderState = {
  /* scope: نطاقُ الخطة — طالبٌ واحد أو مسجدٌ كامل أو مجمّع.
     كانت الخطةُ لطالبٍ واحدٍ لا غير، فمن أراد خطّةً لمسجدٍ فيه أربعون
     طالباً أعادها أربعين مرّة. */
  scope: "student", scopeId: "", scopeKind: "",
  step: 0, student: "", program: "", level: "", levelId: "", planType: "مغلقة",
  startS: "الناس", startA: "1", endS: "الضحى", endA: "11", direction: "تنازلي",
  amount: "نصف وجه", unit: "أوجه",
  /* التثبيتُ بالدروس لا بالأوجه، وقاعدتُه آخرُ خمسة دروسٍ ناجحة */
  fixLessons: 5,
  sched: { "حفظ جديد": ["الأحد", "الثلاثاء", "الخميس"], "مراجعة": ["السبت", "الإثنين"], "تثبيت": ["الأحد", "الخميس"], "تلاوة": ["الأحد"] },
  rules: { tilawah: true, fixation: true, lowEval: true, absence: true, partial: true, openBlocks: true },
  lowEval: "إعادة نفس الواجب", absence: "ترحيل الواجب", transition: "باعتماد المشرف"
};
/* =========================================================================
   طلاب المنشأة
   -------------------------------------------------------------------------
   الطالبُ يُنسب إلى المسجد بحقله، أو بحلقته إن لم يُنسب. وإلى المجمّع
   بمساجده. دالّةٌ واحدةٌ تعرف ذلك، فلا تفترق الشاشاتُ في الحساب.
   ========================================================================= */
function facilityStudents(kind, id) {
  if (!id) return [];
  const all = (cur("students") || []).filter(x => x && x.status !== "متوقف");

  if (kind === "mosque") {
    const cids = new Set((cur("circles") || [])
      .filter(c => c && String(c.mosqueId || "") === String(id))
      .map(c => String(c.id)));
    return all.filter(x =>
      String(x.mosqueId || "") === String(id) || cids.has(String(x.circleId)));
  }

  if (kind === "complex") {
    const mids = new Set((cur("mosques") || [])
      .filter(m => m && String(m.complexId || "") === String(id))
      .map(m => String(m.id)));
    const cids = new Set((cur("circles") || [])
      .filter(c => c && (mids.has(String(c.mosqueId || "")) ||
                         String(c.complexId || "") === String(id)))
      .map(c => String(c.id)));
    return all.filter(x =>
      String(x.complexId || "") === String(id) ||
      mids.has(String(x.mosqueId || "")) ||
      cids.has(String(x.circleId)));
  }

  return [];
}

const BUILDER_STEPS = ["الطالب", "البرنامج", "النطاق القرآني", "المقدار اليومي", "جدول الواجبات", "قواعد التعويض", "المعاينة والاعتماد"];

function planBuilder() {
  if (!cur("students").length || !cur("programs").length) {
    return `<div class="tab-panel"><div class="card">${emptyState("لا يمكن بناء خطة بعد", "يلزم وجود طالب واحد وبرنامج واحد على الأقل. أضِف طلاباً وبرامج أولاً.")}</div></div>`;
  }
  const s = builderState.step;
  const dots = BUILDER_STEPS.map((label, i) => `<div class="step-node ${i === s ? "active" : i < s ? "done" : ""}" data-action="builder-goto" data-step="${i}">
    <span class="step-num">${i < s ? ic("check", 14) : i + 1}</span><span class="step-label">${esc(label)}</span>
  </div>${i < BUILDER_STEPS.length - 1 ? '<div class="step-bar ' + (i < s ? "done" : "") + '"></div>' : ""}`).join("");
  return `<div class="tab-panel">
    <div class="stepper">${dots}</div>
    <div class="card builder-card" id="builderBody">${builderStep(s)}</div>
    <div class="builder-nav">
      ${s > 0 ? `<button class="btn btn-ghost" data-action="builder-prev">${ic("arrowLeft", 15)} السابق</button>` : `<button class="btn btn-ghost" data-action="tab" data-group="plans" data-tab="active">إلغاء</button>`}
      ${s < BUILDER_STEPS.length - 1
        ? `<button class="btn btn-primary" data-action="builder-next">التالي ${ic("arrowDown", 15)}</button>`
        : `<button class="btn btn-gold" data-action="builder-create">${ic("checkCircle", 16)} اعتماد وإنشاء الخطة</button>`}
    </div>
  </div>`;
}

function builderStep(s) {
  const B = builderState;
  if (s === 0) {
    /* =====================================================================
       نطاق الخطة: طالبٌ أو مسجدٌ أو مجمّع
       ---------------------------------------------------------------------
       الخطةُ الواحدةُ تُنسَخ لكلّ طالبٍ في النطاق عند الاعتماد، فيبقى لكلٍّ
       تقدّمُه ومتأخّراتُه على حدة — ولا تُبنى أربعين مرّة.
       ===================================================================== */
    const SC = [["student", "طالب واحد", "person"],
                ["mosque",  "مسجد كامل", "mosque"],
                ["complex", "مجمّع كامل", "building"]];

    const scopeTabs = `<div class="fac-tabs" style="margin-bottom:16px">
      ${SC.map(([k, h, i2]) => `<button type="button" class="fac-tab${
        B.scope === k ? " on" : ""}" data-action="b-scope" data-scope="${k}">
        ${ic(i2, 16)}<span>${esc(h)}</span></button>`).join("")}
    </div>`;

    if (B.scope === "student") {
      /* =====================================================================
         قائمةُ الطلاب تتبع النطاق
         ---------------------------------------------------------------------
         كانت تعرض طلابَ النظام كلَّهم، فمن فتح البانيَ من مجمّعٍ ليبني خطّةً
         لطالبٍ فيه بحث عنه بين مئاتٍ من مجمّعاتٍ أخرى.

         تتبع الآن ما اختاره في تبويبَي المسجد والمجمّع، أو ما فُتح منه
         الباني — فمن اختار مسجداً ثمّ رجع إلى «طالب واحد» يجد طلابه.
         ===================================================================== */
      let pool, poolFrom = null;

      if (B.scopeKind === "mosque" && B.scopeId) {
        pool = facilityStudents("mosque", B.scopeId);
        poolFrom = (cur("mosques") || []).find(x => String(x.id) === String(B.scopeId));
      } else if (B.scopeKind === "complex" && B.scopeId) {
        pool = facilityStudents("complex", B.scopeId);
        poolFrom = (cur("complexes") || []).find(x => String(x.id) === String(B.scopeId));
      } else if (STATE.planMosque) {
        pool = facilityStudents("mosque", STATE.planMosque);
        poolFrom = (cur("mosques") || []).find(x => String(x.id) === String(STATE.planMosque));
      } else if (STATE.planComplex) {
        pool = facilityStudents("complex", STATE.planComplex);
        poolFrom = (cur("complexes") || []).find(x => String(x.id) === String(STATE.planComplex));
      } else {
        pool = cur("students");
      }

      return `<h3 class="bstep-title">نطاق الخطة</h3>
        <p class="bstep-sub">اختر طالباً بعينه، أو ابنِها لمسجدٍ أو مجمّعٍ كامل.${
          poolFrom ? " الطلاب المعروضون من <strong>" + esc(poolFrom.name) + "</strong>" : ""}</p>
        ${scopeTabs}
        <div class="grid g-3 stagger">${pool.map(st => `<label class="pick-card ${
          B.student === st.name ? "sel" : ""}">
          <input type="radio" name="bstudent" value="${esc(st.name)}" ${
            B.student === st.name ? "checked" : ""} hidden>
          <div class="mini-avatar" style="width:40px;height:40px">${initials(st.name)}</div>
          <div><strong>${esc(st.name)}</strong>
            <div class="muted" style="font-size:11.5px">${esc(st.circle || "—")}</div>
            <div style="margin-top:4px">${st.attType === "دوام جزئي"
              ? badge("دوام جزئي", "b-amber") : badge("دوام كامل", "b-green")}</div></div>
        </label>`).join("") || `<div class="muted" style="padding:18px">لا طلاب في هذا النطاق</div>`}</div>`;
    }

    /* مسجدٌ أو مجمّع */
    const isMq = B.scope === "mosque";
    const list = isMq ? cur("mosques") : cur("complexes");

    const cards = list.map(f => {
      const n = facilityStudents(isMq ? "mosque" : "complex", f.id).length;
      const withPlan = facilityStudents(isMq ? "mosque" : "complex", f.id)
        .filter(x => (cur("plans") || []).some(p => String(p.studentId) === String(x.id))).length;

      return `<label class="pick-card ${String(B.scopeId) === String(f.id) ? "sel" : ""}"
          data-action="b-scope-pick" data-id="${esc(f.id)}">
        <div class="mini-avatar" style="width:40px;height:40px">${ic(isMq ? "mosque" : "building", 20)}</div>
        <div><strong>${esc(f.name || "—")}</strong>
          <div class="muted" style="font-size:11.5px">
            ${toArabicDigits(n)} طالباً${withPlan ? " · " + toArabicDigits(withPlan) + " له خطة" : ""}</div>
          ${!n ? `<div style="margin-top:4px">${badge("بلا طلاب", "b-gray")}</div>` : ""}</div>
      </label>`;
    }).join("");

    const picked = B.scopeId
      ? facilityStudents(isMq ? "mosque" : "complex", B.scopeId) : [];
    const already = picked.filter(x =>
      (cur("plans") || []).some(p => String(p.studentId) === String(x.id)));

    return `<h3 class="bstep-title">نطاق الخطة</h3>
      <p class="bstep-sub">تُنشأ نسخةٌ من الخطة لكلّ طالبٍ في النطاق، ولكلٍّ تقدّمُه على حدة.</p>
      ${scopeTabs}
      <div class="grid g-3 stagger">${cards ||
        `<div class="muted" style="padding:18px">لا ${isMq ? "مساجد" : "مجمّعات"} بعد</div>`}</div>

      ${B.scopeId ? `<div style="margin-top:16px">${noteCard(
        "ستُنشأ الخطةُ لـ<strong>" + toArabicDigits(picked.length) + "</strong> طالباً." +
        (already.length ? "<br>ومن له خطّةٌ قائمة — وعددُهم " +
          toArabicDigits(already.length) + " — تُترك خطّتُه ولا تُستبدل." : "")
      )}</div>` : ""}`;
  }

  if (s === 1) {
    return `<h3 class="bstep-title">اختر البرنامج والمستوى</h3><p class="bstep-sub">يحدّد البرنامج اتجاه الخطة الافتراضي وقواعد الانتقال.</p>
      <div class="grid g-2 stagger" style="margin-bottom:16px">${cur("programs").map(p => `<label class="pick-card wide ${B.program === p.name ? "sel" : ""}">
        <input type="radio" name="bprogram" value="${esc(p.name)}" ${B.program === p.name ? "checked" : ""} hidden>
        <div class="kpi-ico t-gold" style="margin:0">${ic("layers", 20)}</div>
        <div><strong>${esc(p.name)}</strong><div class="muted" style="font-size:11.5px">${p.levels} مستوى · اتجاه ${esc(p.direction)} · انتقال ${esc(p.transition)}</div></div>
      </label>`).join("")}</div>
      <div class="form-grid">
        ${(() => {
          /* كانت أربعة نصوص ثابتة لا صلة لها بمستويات البرنامج المسجّلة،
             فتُحفظ الخطة باسم مستوى قد لا يكون له وجود. */
          const pg = (cur("programs") || []).find(x => String(x.name) === String(B.program));
          const lv = pg ? (cur("levels") || [])
            .filter(x => String(x.programId) === String(pg.id) && x.status !== "موقوف")
            .sort((a, b) => (Number(a.order) || 0) - (Number(b.order) || 0)) : [];

          if (!lv.length) {
            return `<div class="field full"><label>المستوى</label>
              <select id="blevel"><option value="">— لا مستويات لهذا البرنامج —</option></select>
              <div class="muted" style="font-size:11.5px;margin-top:5px">
                عرّف مستويات البرنامج من الإعدادات ← البرامج والمستويات، لترتبط الخطة بسجلٍ لا باسم.</div>
            </div>`;
          }

          return `<div class="field"><label>المستوى <span class="req">*</span></label>
            <select id="blevel">${lv.map(x =>
              `<option value="${esc(x.id)}"${String(B.levelId) === String(x.id) ? " selected" : ""}>
                ${esc(x.name)}${x.qty ? " — " + toArabicDigits(x.qty) + " " + esc(x.unit || "وجه") : ""}
              </option>`).join("")}</select></div>`;
        })()}
        ${selField("نوع الخطة", ["مغلقة", "مفتوحة", "سرد المحفوظ"]).replace("<select", `<select id="bplanType"`)}
      </div>`;
  }
  if (s === 2) {
    return `<h3 class="bstep-title">حدّد النطاق القرآني والاتجاه</h3><p class="bstep-sub">بداية ونهاية الحفظ، واتجاه التقدّم في المصحف.</p>
      <div class="form-grid">
        <div class="field"><label>سورة البداية</label><input id="bstartS" value="${esc(B.startS)}"></div>
        <div class="field"><label>آية البداية</label><input id="bstartA" value="${esc(B.startA)}"></div>
        <div class="field"><label>سورة النهاية</label><input id="bendS" value="${esc(B.endS)}"></div>
        <div class="field"><label>آية النهاية</label><input id="bendA" value="${esc(B.endA)}"></div>
      </div>
      <div style="margin-top:14px"><label style="font-size:12.5px;font-weight:700">اتجاه الخطة</label>
        <div class="segx" style="margin-top:7px">
          <button class="seg-btn ${B.direction === "تصاعدي" ? "on" : ""}" data-action="builder-pick" data-key="direction" data-val="تصاعدي">تصاعدي (البقرة ← الناس)</button>
          <button class="seg-btn ${B.direction === "تنازلي" ? "on" : ""}" data-action="builder-pick" data-key="direction" data-val="تنازلي">تنازلي (الناس ← البقرة)</button>
        </div>
      </div>`;
  }
  if (s === 3) {
    const units = ["أسطر", "أوجه", "صفحات", "أثمان", "أجزاء"];
    return `<h3 class="bstep-title">المقدار اليومي ووحدته</h3><p class="bstep-sub">كم يحفظ الطالب يومياً؟ قابل للتعديل لاحقاً حسب أدائه.</p>
      <div class="form-grid">
        <div class="field"><label>مقدار الحفظ اليومي</label><input id="bamount" value="${esc(B.amount)}"></div>
        <div class="field"><label>وحدة المقدار</label><select id="bunit">${units.map(u => `<option ${u === B.unit ? "selected" : ""}>${u}</option>`).join("")}</select></div>
        <div class="field"><label>دروس التثبيت</label>
          <input id="bfixlessons" type="number" min="1" max="30" value="${esc(B.fixLessons)}">
          <small class="muted" style="font-size:11.5px">التثبيت من آخر هذا العدد من دروس الحفظ الناجحة — لا بمقدارٍ من الأوجه</small></div>
      </div>
      <div class="amount-preview">${["3 أسطر", "نصف وجه", "وجه كامل", "صفحة"].map(a => `<button class="chip ${B.amount === a ? "day-on" : ""}" data-action="builder-pick" data-key="amount" data-val="${a}" style="border:none">${a}</button>`).join("")}</div>`;
  }
  if (s === 4) {
    const duties = ["حفظ جديد", "مراجعة", "تثبيت", "تلاوة"];
    return `<h3 class="bstep-title">جدول الواجبات الأسبوعي</h3><p class="bstep-sub">حدّد أي الواجبات تظهر في كل يوم.</p>
      <div class="sched-builder">
        <div class="sched-row head"><div class="sched-duty"></div>${DOW.map(d => `<div class="sched-day-h">${d}</div>`).join("")}</div>
        ${duties.map(dt => `<div class="sched-row">
          <div class="sched-duty"><span class="tl-duty ${DUTY_META[dt].cls}" style="margin:0"><span></span>${DUTY_META[dt].short}</span></div>
          ${DOW.map(d => { const on = B.sched[dt] && B.sched[dt].includes(d); return `<button class="sched-cell ${on ? "on " + DUTY_META[dt].cls : ""}" data-action="builder-sched" data-duty="${dt}" data-day="${d}">${on ? ic("check", 13) : ""}</button>`; }).join("")}
        </div>`).join("")}
      </div>`;
  }
  if (s === 5) {
    const r = B.rules;
    return `<h3 class="bstep-title">قواعد التعويض والمتأخرات</h3><p class="bstep-sub">القواعد التي يطبّقها النظام آلياً على واجبات الطالب.</p>
      <div class="grid g-2" style="margin-bottom:16px">
        ${toggleRow("التلاوة قبل الحفظ", "تلاوة تمهيدية قبل الحفظ الجديد", r.tilawah, "b-tilawah")}
        ${toggleRow("التثبيت يتبع الحفظ", "تتبّع آخر الدروس المتقنة", r.fixation, "b-fixation")}
        ${toggleRow("التقييم الضعيف يعيد الواجب", "إعادة الواجب عند تقييم منخفض", r.lowEval, "b-lowEval")}
        ${toggleRow("الغياب ينشئ تعويضاً", "توليد واجب تعويض للفائت", r.absence, "b-absence")}
        ${toggleRow("التسميع الناقص يُرحَّل", "الفارق يُضاف إلى واجب الغد", r.partial, "b-partial")}
        ${toggleRow("التعويض المفتوح يمنع التقدم", "قفل الواجبات حتى الإغلاق", r.openBlocks, "b-openBlocks")}
      </div>
      <div class="form-grid">
        ${selField("عند التقييم الضعيف", ["إعادة نفس الواجب", "السماح بالتقدم", "يحتاج قرار مشرف"]).replace("<select", `<select id="blowEvalSel"`)}
        ${selField("عند الغياب", ["ترحيل الواجب", "إعفاء", "قرار يدوي"]).replace("<select", `<select id="babsenceSel"`)}
        ${selField("قاعدة الانتقال للمستوى", ["تلقائي", "باعتماد المشرف"]).replace("<select", `<select id="btransition"`)}
      </div>`;
  }
  const preview = builderToPlan();
  return `<h3 class="bstep-title">معاينة الخطة قبل الاعتماد</h3><p class="bstep-sub">راجع الخطة المولّدة. لا شيء يُحفظ حتى تضغط «اعتماد وإنشاء الخطة».</p>
    <div class="preview-grid">
      <div class="prev-item"><span>الطالب</span><strong>${esc(preview.student) || "—"}</strong></div>
      <div class="prev-item"><span>البرنامج</span><strong>${esc(preview.program) || "—"}</strong></div>
      <div class="prev-item"><span>المستوى</span><strong>${esc(preview.level)}</strong></div>
      <div class="prev-item"><span>نوع الخطة</span><strong>${esc(preview.planType)}</strong></div>
      <div class="prev-item"><span>النطاق</span><strong>${esc(preview.start)} ← ${esc(preview.end)}</strong></div>
      <div class="prev-item"><span>الاتجاه</span><strong>${esc(preview.direction)}</strong></div>
      <div class="prev-item"><span>المقدار اليومي</span><strong>${esc(preview.amount)} (${esc(preview.unit)})</strong></div>
      <div class="prev-item"><span>الانتقال</span><strong>${esc(builderState.transition)}</strong></div>
    </div>
    <div style="margin-top:18px"><div class="section-head"><h3 style="font-size:14px">الجدول الأسبوعي المولّد</h3></div>${planTimeline(preview)}</div>`;
}

function builderToPlan(forStudent) {
  const B = builderState;
  const sched = {};
  DOW.forEach(d => { sched[d] = []; });
  Object.keys(B.sched).forEach(dt => (B.sched[dt] || []).forEach(d => { if (sched[d]) sched[d].push(dt); }));
  const order = ["تلاوة", "حفظ جديد", "مراجعة", "تثبيت", "تعويض"];
  DOW.forEach(d => sched[d].sort((a, b) => order.indexOf(a) - order.indexOf(b)));
  /* الطالبُ المُمرَّر يغلب: النطاقُ الجماعيّ ينسخ الخطةَ لكلٍّ على حدة */
  const stObj = forStudent || DB.students.find(x => x.name === B.student);
  const ext = {
    health: "healthy", openBlocks: B.rules.openBlocks,
    sched, rules: B.rules,
    transition: { mode: B.transition === "تلقائي" ? "automatic" : "supervisor", test: false, noDelays: true, minScore: 7 },
    today: sched["الأحد"].length ? sched["الأحد"].map(t => ({
      type: t, range: t === "حفظ جديد" ? `${B.startS} ${B.startA} إلى التالي` : t === "مراجعة" ? "المقطع السابق" : t === "تثبيت" ? ("آخر " + toArabicDigits(Number(B.fixLessons) || 5) + " دروس") : "تمهيد قبل الحفظ",
      why: t === "حفظ جديد" ? "اليوم من أيام الحفظ المجدولة." : "واجب مجدول.",
      status: "لم يبدأ"
    })) : [],
    tomorrow: sched["الإثنين"].length ? [{ type: sched["الإثنين"][0], range: "المقطع التالي", why: "متوقع حسب جدول الإثنين." }] : []
  };
  return { id: 0, student: B.student, circle: stObj ? stObj.circle : "—", program: B.program, level: B.level, levelId: B.levelId || "", planType: B.planType, start: `${B.startS} ${B.startA}`, current: `${B.startS} ${B.startA}`, end: `${B.endS} ${B.endA}`, direction: B.direction, amount: B.amount, unit: B.unit, progress: 0, delays: 0, ext };
}

function readBuilderStep(s) {
  const B = builderState, q = (sel) => document.querySelector(sel);
  if (s === 0 && B.scope === "student") {
    const r = q('input[name="bstudent"]:checked'); if (r) B.student = r.value;
  }
  if (s === 1) { const r = q('input[name="bprogram"]:checked'); if (r) B.program = r.value; if (q("#blevel")) {
      /* يُحفظ المعرّف والاسم معاً: المعرّف للربط، والاسم ليبقى مقروءاً
         في التقارير إن حُذف سجل المستوى. */
      B.levelId = q("#blevel").value;
      const lvRec = (cur("levels") || []).find(x => String(x.id) === String(B.levelId));
      B.level = lvRec ? lvRec.name : "";
    } if (q("#bplanType")) B.planType = q("#bplanType").value; }
  if (s === 2) { ["startS", "startA", "endS", "endA"].forEach(k => { const el = q("#b" + k); if (el) B[k] = el.value; }); }
  if (s === 3) { if (q("#bamount")) B.amount = q("#bamount").value; if (q("#bunit")) B.unit = q("#bunit").value;
                 if (q("#bfixlessons")) B.fixLessons = Math.max(1, Number(q("#bfixlessons").value) || 5); }
  if (s === 5) {
    document.querySelectorAll("#builderBody [data-toggle]").forEach(t => { const key = t.dataset.toggle.replace("b-", ""); if (key in B.rules) B.rules[key] = t.checked; });
    if (q("#blowEvalSel")) B.lowEval = q("#blowEvalSel").value;
    if (q("#babsenceSel")) B.absence = q("#babsenceSel").value;
    if (q("#btransition")) B.transition = q("#btransition").value;
  }
}

/* =========================================================
   PLANS — compensation & review tabs
   ========================================================= */
function planCompTab() {
  if (!DB.delays.length) {
    return `<div class="tab-panel"><div class="card">${emptyState("لا توجد متأخرات", "لا يوجد أي تعويض مفتوح حالياً.")}</div></div>`;
  }
  const rows = DB.delays.map(d => `<tr>
    <td><div class="td-name"><div class="mini-avatar">${initials(d.student)}</div><div><div class="td-strong">${esc(d.student)}</div><div class="muted" style="font-size:11.5px">${esc(d.circle)}</div></div></div></td>
    <td>${badge(d.reason, d.reason === "غياب" ? "b-red" : "b-amber")}</td>
    <td style="font-size:12.5px">${esc(d.duty)}</td>
    <td class="muted" style="font-size:12px">${esc(d.date)}</td>
    <td class="center">${d.blocks ? badge("يمنع التقدم", "b-red") : badge("لا يمنع", "b-gray")}</td>
    <td>${statusBadge(d.status)}</td>
    <td><div class="row-actions">
      <button class="row-btn" data-action="toast" data-msg="تم إغلاق التعويض" title="إغلاق">${ic("check", 16)}</button>
      <button class="row-btn" data-action="toast" data-msg="تم تأجيل التعويض" title="تأجيل">${ic("clock", 16)}</button>
    </div></td>
  </tr>`).join("");
  return `<div class="tab-panel"><div class="table-wrap"><div class="table-scroll"><table class="data">
    <thead><tr><th>الطالب</th><th>سبب التأخر</th><th>الواجب المطلوب تعويضه</th><th>التاريخ</th><th>أثر على الخطة</th><th>الحالة</th><th></th></tr></thead>
    <tbody>${rows}</tbody>
  </table></div></div></div>`;
}

/* =========================================================================
   خطط بانتظار قرار الإدارة
   -------------------------------------------------------------------------
   كان التبويب يقرأ مجموعة reviews — وهي معرَّفة في COLLECTIONS ولا يكتبها
   شيء في المشروع كلّه. فيظهر «لا توجد خطط للمراجعة» أبداً مهما أنهى الطلاب
   مستوياتهم، وتُهدر قراءتها في كل تحميل.

   المواصفات: «عند إنهاء الطالب لكافة متطلبات المستوى، يتوقّف تقدّمه ويظهر
   طلب في لوحة الإدارة يفيد بأن الطالب أنهى المستوى ويحتاج تقييماً».

   فالحقيقة عند المحرّك: من بلغ مقدار مستواه. تُشتقّ منه لا من قِدرٍ فارغة.
   ========================================================================= */
function reviewPlans() {
  const out = [];

  (cur("plans") || []).forEach(p => {
    if (!p || planIsFrozen(p)) return;
    let prog = null;
    try { prog = levelProgress(p); } catch (e) {}
    if (!prog || !prog.complete) return;

    let next = null;
    try { next = nextLevelOf(p); } catch (e) {}

    out.push({
      plan: p, prog, next,
      student: p.student || "",
      program: p.program || "",
      level: (prog.level && prog.level.name) || p.level || ""
    });
  });

  /* المُدرجة يدوياً في reviews تبقى — لا تُهمل بيانات قائمة */
  (cur("reviews") || []).forEach(r => {
    if (out.some(x => String(x.student) === String(r.student))) return;
    const p = (cur("plans") || []).find(x => String(x.student) === String(r.student));
    out.push({ plan: p, prog: null, next: null,
      student: r.student || "", program: r.program || "", level: r.level || "" });
  });

  return out;
}

function planReviewTab() {
  const list = reviewPlans();

  if (!list.length) {
    return `<div class="tab-panel"><div class="card">${emptyState(
      "لا خطط تنتظر قراراً",
      "يظهر هنا من أنهى مقدار مستواه — يتوقّف تقدّمه حتى تُعتمد ترقيته.")}</div></div>`;
  }

  const cards = list.map(r => {
    const p = r.plan;
    return `<div class="card rev-card">
      <div class="rev-head">
        <div class="td-name"><div class="mini-avatar">${initials(r.student)}</div>
          <div><strong>${esc(r.student)}</strong>
            <div class="muted" style="font-size:12px">${esc(r.program)}${
              r.level ? " — " + esc(r.level) : ""}</div></div></div>
        ${r.prog ? badge("أنهى المستوى", "b-green") : badge("بانتظار المراجعة", "b-amber")}
      </div>

      ${r.prog ? `<div class="lvp" style="padding-top:10px">
        <div class="lvp-head"><span class="muted">المنجز</span>
          <span>${toArabicDigits(r.prog.done)} / ${toArabicDigits(r.prog.need)} ${
            esc(r.prog.level.unit || "وجه")}</span></div>
        <div class="lvp-bar"><i style="width:${r.prog.pct}%"></i></div>
      </div>` : ""}

      <div class="rev-acts">
        ${p ? `<button class="btn btn-ghost btn-sm" data-action="plan-open"
          data-id="${esc(p.id)}">${ic("eye", 14)} فتح الخطة</button>` : ""}
        ${p && r.next ? `<button class="btn btn-primary btn-sm"
          onclick="window.planPromote('${jsAttr(p.id)}')">
          ترقية إلى ${esc(r.next.name)}</button>`
          : r.prog ? `<span class="muted" style="font-size:12px">
              لا مستوى تالٍ — أضِفه من الإعدادات</span>` : ""}
      </div>
    </div>`;
  }).join("");

  return `<div class="tab-panel">
    ${noteCard(`<strong>${toArabicDigits(list.length)}</strong> طالباً بلغ مقدار مستواه.
      تقدّمه متوقّف حتى تُعتمد ترقيته.`)}
    <div class="rev-grid">${cards}</div>
  </div>`;
}

/* =========================================================
   ADMIN — 8. ATTENDANCE OVERVIEW
   ========================================================= */
/* =========================================================================
   متابعة الحضور — الطلاب والمعلّمون
   -------------------------------------------------------------------------
   كانت الصفحة أصفاراً ثابتة مكتوبة في الكود:  num: 0
   ومعها ملاحظة تقول «تسجيل الحضور الفعلي لم يُبنَ بعد» — وقد بُني، فصار
   النصّ يكذّب النظام والأرقام تُخفي حقيقةً موجودة.

   وحضور المعلّمين مرصود في سجل الدوام ولا يظهر هنا، فتُتابَع غيبة الطالب
   ولا تُتابَع غيبة معلّمه.
   ========================================================================= */

const ATTV = { who: "students", date: "" };

window.attvSet = function (k, v) { ATTV[k] = String(v || ""); mount(); };

function attvDate() { return ATTV.date || (typeof attDate === "function" ? attDate() : todayISO()); }

/* حضور الطلاب في يوم: من سجلات الحضور لا من حقلٍ مخزَّن */
function attvStudents(dateISO) {
  const recs = (cur("attendance") || []).filter(a =>
    a && !a.staffId && String(a.date) === String(dateISO));

  const by = {};
  recs.forEach(r => { by[String(r.studentId)] = r; });

  const all = (cur("students") || []).filter(s => s && s.status !== "متوقف");
  /* من ليس اليوم يوم دوامه لا يُحسب غائباً — قاعدة الدوام الجزئي */
  const due = all.filter(s => {
    try { return typeof isDutyDay === "function" ? isDutyDay(s, dateISO) : true; }
    catch (e) { return true; }
  });

  const cnt = st => due.filter(s => (by[String(s.id)] || {}).status === st).length;
  const recited = due.filter(s =>
    (cur("recitations") || []).some(r =>
      String(r.studentId) === String(s.id) && String(r.date) === String(dateISO))).length;

  const present = cnt("حاضر") + cnt("متأخر");

  return {
    due: due.length, off: all.length - due.length,
    marked: due.filter(s => by[String(s.id)]).length,
    present: cnt("حاضر"), late: cnt("متأخر"),
    absent: cnt("غائب"), excused: cnt("مستأذن"),
    /* «حاضر ولم يسمّع»: حضر فعلاً ولا تسميع له — عجزٌ يترتّب على خطته */
    noRecite: Math.max(0, present - recited),
    recited, by
  };
}

/* حضور الموظفين: سجلات الدوام — a.staffId هو الفارق */
function attvStaff(dateISO) {
  const recs = (cur("attendance") || []).filter(a =>
    a && a.staffId && String(a.date) === String(dateISO));

  const by = {};
  recs.forEach(r => { by[String(r.staffId)] = r; });

  const staff = (cur("teachers") || []).filter(t => t && t.active !== false);
  const cnt = st => staff.filter(t => (by[String(t.id)] || {}).status === st).length;
  const lateMin = recs.reduce((n, r) => n + (Number(r.lateMin) || 0), 0);

  return {
    total: staff.length,
    marked: staff.filter(t => by[String(t.id)]).length,
    present: cnt("حاضر"), late: cnt("متأخر"),
    absent: cnt("غائب"), excused: cnt("مستأذن"),
    /* لم يسجّل حضوره أصلاً — غير الغائب المرصود */
    silent: staff.filter(t => !by[String(t.id)]).length,
    lateMin, staff, by
  };
}

/* =========================================================================
   الشاشة
   ========================================================================= */
function adminAttendance() {
  const d = attvDate();
  const isStu = ATTV.who !== "staff";

  const head = `<div class="attv-bar">
    <div class="attv-switch">
      <button class="attv-btn${isStu ? " on" : ""}"
        onclick="window.attvSet('who','students')">${ic("users", 15)} الطلاب</button>
      <button class="attv-btn${!isStu ? " on" : ""}"
        onclick="window.attvSet('who','staff')">${ic("teacher", 15)} المعلّمون</button>
    </div>
    <input type="date" class="filter-date" value="${esc(d)}"
      onchange="window.attvSet('date',this.value)" style="margin-inline-start:auto">
  </div>`;

  return `<div class="page">
    ${pageHead("متابعة الحضور",
      isStu ? "حضور الطلاب اليوم عبر المساجد والحلقات"
            : "حضور المعلّمين ودقائق تأخّرهم")}
    ${head}
    ${isStu ? attvStudentsView(d) : attvStaffView(d)}
  </div>`;
}

function attvStudentsView(d) {
  const s = attvStudents(d);
  const pct = s.due ? Math.round((s.present + s.late) * 100 / s.due) : 0;

  const kpis = [
    { tint: "t-green",  icon: "check", num: s.present,  label: "حاضر" },
    { tint: "t-amber",  icon: "clock", num: s.late,     label: "متأخر" },
    { tint: "t-red",    icon: "x",     num: s.absent,   label: "غائب" },
    { tint: "t-blue",   icon: "info",  num: s.excused,  label: "مستأذن" },
    { tint: "t-purple", icon: "pen",   num: s.noRecite, label: "حاضر ولم يسمّع" },
    { tint: "t-gold",   icon: "users", num: s.due - s.marked, label: "لم يُحضَّر بعد" }
  ].map(k => Object.assign(k, { dir: "flat", trend: "" }));

  /* الحضور حسب المسجد — محسوباً لا من حقلٍ جامد */
  const byMosque = (cur("mosques") || []).filter(m => m.status !== "متوقف").map(m => {
    const cids = (cur("circles") || [])
      .filter(c => String(c.mosqueId) === String(m.id) || c.mosque === m.name)
      .map(c => String(c.id));

    const mine = (cur("students") || []).filter(x =>
      x.status !== "متوقف" &&
      (String(x.mosqueId) === String(m.id) || cids.indexOf(String(x.circleId)) > -1));

    const here = mine.filter(x => {
      const r = s.by[String(x.id)];
      return r && (r.status === "حاضر" || r.status === "متأخر");
    }).length;

    const p = mine.length ? Math.round(here * 100 / mine.length) : 0;
    return `<div class="list-row">
      <div class="mini-avatar">${ic("mosque", 15)}</div>
      <div style="flex:1"><strong style="font-size:13.5px">${esc(m.name)}</strong>
        <div class="muted" style="font-size:11.5px">${toArabicDigits(here)} من ${
          toArabicDigits(mine.length)}</div></div>
      <div style="width:160px">${progressRow(p, p >= 80 ? "green" : p >= 50 ? "amber" : "red")}</div>
    </div>`;
  }).join("") || `<div class="muted" style="padding:14px">لا مساجد نشطة.</div>`;

  /* حلقات لم تُعتمد جلستها اليوم */
  const pending = (cur("circles") || []).filter(c => {
    try { return !sessionOf(d, c.id); } catch (e) { return c.status !== "معتمدة"; }
  });

  return `
    <div class="section"><div class="grid g-3 stagger">${kpis.map(kpiCard).join("")}</div></div>

    <div class="attv-sum">
      <div><b>${toArabicDigits(pct)}٪</b><span>نسبة الحضور</span></div>
      <div><b>${toArabicDigits(s.recited)}</b><span>سُمِّع لهم</span></div>
      <div><b>${toArabicDigits(s.due)}</b><span>مطلوب حضورهم</span></div>
      ${s.off ? `<div><b>${toArabicDigits(s.off)}</b><span>خارج جدول اليوم</span></div>` : ""}
    </div>

    <div class="section"><div class="section-head"><h3>الحضور حسب المسجد</h3></div>
      <div class="list-card">${byMosque}</div></div>

    <div class="section">
      <div class="section-head"><h3>حلقات لم تُعتمد جلستها اليوم</h3>
        <span class="badge ${pending.length ? "b-amber" : "b-green"}">${
          toArabicDigits(pending.length)}</span></div>
      <div class="list-card">
        ${pending.length ? pending.slice(0, 12).map(c => `<div class="list-row">
          <div class="alert-ico t-red">${ic("alert", 17)}</div>
          <div style="flex:1"><strong style="font-size:13.5px">${esc(c.name)}</strong>
            <div class="muted" style="font-size:12px">${esc(c.mosque || "—")} — ${
              esc(c.teacher || "بلا معلّم")}</div></div>
          ${statusBadge(c.status)}
        </div>`).join("") : `<div class="muted" style="padding:14px">كل الحلقات اعتُمدت.</div>`}
      </div>
    </div>`;
}

function attvStaffView(d) {
  const s = attvStaff(d);
  const pct = s.total ? Math.round((s.present + s.late) * 100 / s.total) : 0;

  const kpis = [
    { tint: "t-green", icon: "check",   num: s.present, label: "حاضر" },
    { tint: "t-amber", icon: "clock",   num: s.late,    label: "متأخر" },
    { tint: "t-red",   icon: "x",       num: s.absent,  label: "غائب" },
    { tint: "t-blue",  icon: "info",    num: s.excused, label: "مستأذن" },
    { tint: "t-gold",  icon: "alert",   num: s.silent,  label: "لم يسجّل حضوره" },
    { tint: "t-purple", icon: "clock",  num: s.lateMin, label: "مجموع دقائق التأخّر" }
  ].map(k => Object.assign(k, { dir: "flat", trend: "" }));

  const STAT = { "حاضر": "on", "متأخر": "warn", "غائب": "off", "مستأذن": "info" };

  const rows = s.staff.length ? s.staff.map(t => {
    const r = s.by[String(t.id)];
    let cir = (cur("circles") || []).find(c =>
      String(c.teacherId) === String(t.id) || c.teacher === t.name);
    /* المساعد لا حلقة له باسمه — تُعرض التي يساعد فيها لئلّا يبدو بلا حلقة */
    let asstOf = "";
    if (!cir) {
      const a = (typeof assistIn === "function" ? assistIn(t.id) : [])[0];
      if (a) { cir = a; asstOf = a.name || ""; }
    }
    return `<tr>
      <td><div class="td-name"><div class="mini-avatar">${initials(t.name)}</div>
        <div><div class="td-strong">${esc(t.name || "—")}</div>
        <div class="muted" style="font-size:11.5px">${esc(t.mosque || "—")}</div></div></div></td>
      <td class="muted">${esc(cir ? cir.name : "—")}${asstOf
        ? ` <span class="asst-tag">مساعد</span>` : ""}</td>
      <td class="muted" style="font-size:12px">${esc(cir
        ? (typeof circleStartAt === "function" ? (circleStartAt(cir, d) || cir.start || "—")
           : (cir.start || "—")) : "—")}</td>
      <td dir="ltr" class="pt-num">${esc(r && r.inTime ? r.inTime : "—")}</td>
      <td class="pt-num${r && r.lateMin ? " pay-warn" : ""}">${
        r && r.lateMin ? toArabicDigits(r.lateMin) + " د" : "—"}</td>
      <td>${r
        ? `<span class="pt-badge ${STAT[r.status] || "off"}">${esc(r.status)}</span>`
        : `<span class="pt-badge off">لم يسجّل</span>`}</td>
    </tr>`;
  }).join("")
    : `<tr><td colspan="6" style="text-align:center;padding:26px" class="muted">
        لا معلّمون نشطون.</td></tr>`;

  return `
    <div class="section"><div class="grid g-3 stagger">${kpis.map(kpiCard).join("")}</div></div>

    <div class="attv-sum">
      <div><b>${toArabicDigits(pct)}٪</b><span>نسبة الحضور</span></div>
      <div><b>${toArabicDigits(s.marked)}</b><span>سُجّل حضورهم</span></div>
      <div><b>${toArabicDigits(s.total)}</b><span>مجموع المعلّمين</span></div>
    </div>

    ${s.silent ? noteCard(`<strong>${toArabicDigits(s.silent)}</strong> معلّماً لم يسجّل
      حضوره اليوم. غير المسجَّل ليس غائباً بالضرورة — قد يكون يوم إجازة الحلقة.`) : ""}

    <div class="card">
      <div class="pt-wrap"><div class="pt-scroll"><table class="ptable">
        <thead><tr><th>المعلّم</th><th>الحلقة</th><th>موعد الحلقة</th>
          <th>وقت الحضور</th><th>التأخّر</th><th>الحالة</th></tr></thead>
        <tbody>${rows}</tbody>
      </table></div></div>
    </div>`;
}

/* =========================================================
   ADMIN — 9. REPORTS
   ========================================================= */

/* =========================================================
   صفحات جديدة: المشرفون · الإحصائيات · فروع التقارير
   ========================================================= */
function subParam(k) {
  const m = (typeof location !== "undefined" ? location.search : "").match(new RegExp("[?&]" + k + "=([\\w-]+)"));
  return m ? m[1] : "";
}


/* =========================================================
   بطاقات الأشخاص (مدراء المنشآت · المشرفون) — بنفس ستايل
   بطاقات المنشآت: رأس تيل، مربّعات أرقام، صفوف بيانات، زرّان.
   ========================================================= */
function personAvatar(p) {
  return p.photo ? `<img src="${esc(p.photo)}" alt="">`
    : `<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="8" r="3.6"/><path d="M4.6 20c.6-3.8 3.7-6 7.4-6s6.8 2.2 7.4 6"/></svg>`;
}



/* تحديد صف في الجدول */
window.ptToggle = function (btn) {
  btn.classList.toggle("on");
  const tr = btn.closest("tr");
  if (tr) tr.classList.toggle("sel");
};
window.ptToggleAll = function (btn) {
  const on = btn.classList.toggle("on");
  document.querySelectorAll("#ptBody .pt-box").forEach(b => {
    b.classList.toggle("on", on);
    const tr = b.closest("tr"); if (tr) tr.classList.toggle("sel", on);
  });
};

/* فتحُ ملفّ الشخص من الصفّ. يُتجاهل النقرُ على الأزرار والمدخلات داخله
   حتى لا يُفتح الملفُّ عند التحديد أو التعديل. */
window.ptRowOpen = function (ev, action, id) {
  var t = ev && ev.target;
  if (t && t.closest && t.closest("button, a, input, label, select")) return;
  if (action === "edit-teacher")  { modalEditTeacher(id); return; }
  if (action === "edit-circle")   { modalEditCircle(id);  return; }
  if (action === "panel-teacher") { panelTeacher(id); return; }
  panelStudent(id);
};

function personTable(opt) {
  const list = opt.list || [];
  if (!list.length) {
    return `<div class="page">${pageHead(opt.title, "", opt.addAction ? addBtn(opt.addLabel || "إضافة", opt.addAction) : "")}
      ${opt.overview || ""}
      <div class="card">${emptyState("لا توجد بيانات بعد", opt.empty || "")}</div></div>`;
  }
  const activeCount = list.filter(x => x.active !== false && x.status !== "متوقف").length;
  const cols = opt.cols;
  const CHK = '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="3.4" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6L9 17l-5-5"/></svg>';

  const head = `<tr><th class="pt-check"><button class="pt-box" onclick="window.ptToggleAll(this)" aria-label="تحديد الكل">${CHK}</button></th>` +
    cols.map(c => `<th>${esc(c.h)}</th>`).join("") + `</tr>`;

  /* النقرُ على الصفّ يفتح ملفّ صاحبه: كان لا بدَّ من إصابة زرّ العين
     الصغير في آخر السطر. والزرُّ باقٍ لمن اعتاده.
     opt.rowPanel هو الفعلُ المسجَّل (panel-student / panel-teacher)،
     ويُتجاهل النقرُ إن وقع على زرٍّ أو مربّع تحديد داخل الصفّ. */
  const rowPanel = opt.rowPanel || "";
  const rows = list.map(p2 => {
    const active = p2.active !== false && p2.status !== "متوقف";
    return `<tr data-id="${p2.id}" data-name="${esc(p2.name || "")}" data-active="${active ? 1 : 0}"${
      rowPanel ? ` class="pt-clickable" onclick="window.ptRowOpen(event,'${rowPanel}','${jsAttr(p2.id)}')"` : ""}>
      <td class="pt-check"><button class="pt-box" onclick="window.ptToggle(this)" aria-label="تحديد">${CHK}</button></td>` +
      cols.map(c => c.cell(p2, active)).join("") + `</tr>`;
  }).join("");

  return `<div class="page">
    ${pageHead(opt.title + (opt.showCount ? ` (${list.length})` : ""), "", backArrow())}
    ${opt.overview || ""}
    ${opt.toolbar === "add" ? personToolbarAdd(opt, activeCount)
      : facToolbar("teachers", activeCount, { search: false, addAction: opt.addAction, addLabel: opt.addLabel })}
    <div class="pt-holder">
      ${opt.actionsPanel ? personActionsPanel() : ""}
      <div class="pt-wrap"><div class="pt-scroll"><table class="ptable">
        <thead>${head}</thead><tbody id="ptBody">${rows}</tbody>
      </table></div></div>
    </div>
  </div>`;
}

/* شريط أدوات بزر إضافة نصّي + بحث + فلتر */
function personToolbarAdd(opt, activeCount) {
  const SR = '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="8"/><path d="M21 21l-4.3-4.3"/></svg>';
  const CH = '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M6 9l6 6 6-6"/></svg>';
  const PL = '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"><circle cx="12" cy="12" r="9"/><path d="M12 8.2v7.6M8.2 12h7.6"/></svg>';
  /* الفرزُ أزرارٌ ظاهرةٌ بأعدادها بدل قائمةٍ منسدلة: الحالةُ أوّلُ ما
     يُنظر إليه في قائمة الأشخاص، وإخفاؤها خلف نقرةٍ يخفي العددَ معها.
     الأعدادُ تُحسب من السجلّات لا من صفوف الجدول، فلا تتأثّر بالبحث. */
  const L = opt.list || [];
  const isOn = x => x.active !== false && x.status !== "متوقف";
  const nAll = L.length, nOn = L.filter(isOn).length, nOff = nAll - nOn;
  const tab = (k, h, n) => `<button type="button" class="pt-tab${k === "on" ? " on" : ""}"
      data-ptfilter="${k}" onclick="window.ptFilter('${k}')">
      ${esc(h)} <b>(${n})</b></button>`;

  return `<div class="fac-toolbar">
    <div class="pt-tabs">
      ${tab("on", "فعال", nOn)}
      ${tab("off", "متوقف مؤقتاً", nOff)}
      ${tab("all", "الكل", nAll)}
    </div>
    <div class="fac-searchbox">${SR}<input placeholder="${esc(opt.searchHint || "ابحث..")}" oninput="window.ptSearch(this.value)"></div>
    <button class="pt-add" data-action="${opt.addAction || ""}">${esc(opt.addLabel || "إضافة")}${PL}</button>
  </div>`;
}

/* لوحة الإجراءات الجانبية */
function personActionsPanel() {
  const I = {
    msg:   '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3.5 6.5l8.5 6 8.5-6"/></svg>',
    bell:  '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 8a6 6 0 10-12 0c0 6-2 7-2 7h16s-2-1-2-7M10.5 20a2 2 0 003 0"/></svg>',
    stop:  '<svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor"><circle cx="12" cy="12" r="9"/><rect x="8.8" y="8.8" width="6.4" height="6.4" rx="1.2" fill="#fff"/></svg>',
    play:  '<svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor"><circle cx="12" cy="12" r="9"/><path d="M10.2 8.3l6 3.7-6 3.7z" fill="#fff"/></svg>',
    trash: '<svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor"><path d="M9.4 3h5.2c.5 0 .9.4.9.9V5h4.1c.5 0 .9.4.9.9s-.4.9-.9.9h-.9v12.4c0 1-.8 1.8-1.8 1.8H7.1c-1 0-1.8-.8-1.8-1.8V6.8h-.9c-.5 0-.9-.4-.9-.9S3.9 5 4.4 5h4.1V3.9c0-.5.4-.9.9-.9z"/></svg>',
    edit:  '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 013 3L7 19l-4 1 1-4z"/></svg>',
    move:  '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 9l-3 3 3 3M2 12h9M19 15l3-3-3-3M22 12h-9"/></svg>'
  };
  return `<aside class="pt-panel${ptPanelCollapsed() ? " collapsed" : ""}" id="ptPanel">
    <button class="pt-panel-toggle" onclick="window.ptPanelToggle()" aria-label="طيّ">&laquo;</button>
    <button class="pt-act a-msg"   onclick="window.ptAct('msg')">إرسال رسالة${I.msg}</button>
    <button class="pt-act a-bell"  onclick="window.ptAct('bell')">إرسال إشعار${I.bell}</button>
    <button class="pt-act a-stop"  onclick="window.ptAct('stop')">إيقاف مؤقت${I.stop}</button>
    <button class="pt-act a-play"  onclick="window.ptAct('play')">تفعيل${I.play}</button>
    ${String((STATE && STATE.page) || "") === "students"
      ? `<button class="pt-act a-move" onclick="window.ptAct('move')">نقل طالب${I.move}</button>` : ""}
    <button class="pt-act a-edit"  onclick="window.ptAct('edit')">تعديل${I.edit}</button>
    <button class="pt-act a-del"   onclick="window.ptAct('delete')">حذف${I.trash}</button>
  </aside>`;
}

/* حالةُ اللوحة تُحفظ: كانت تُطوى ولا تُذكر، فمن طواها مرّةً وجدها مطويّةً
   أبداً ومن فتحها عادت تُطوى مع كلّ إعادة رسم. والافتراضُ مفتوحةٌ لأن
   إجراءاتِها هي عملُ الصفحة لا زينةً فيها. */
window.ptPanelToggle = function () {
  const el = document.getElementById("ptPanel");
  if (!el) return;
  const col = el.classList.toggle("collapsed");
  try { localStorage.setItem("ptPanelCollapsed", col ? "1" : "0"); } catch (e) {}
};

function ptPanelCollapsed() {
  try { return localStorage.getItem("ptPanelCollapsed") === "1"; } catch (e) { return false; }
}
window.ptSearch = function (q) {
  const t = String(q || "").trim();
  document.querySelectorAll("#ptBody tr").forEach(tr => {
    tr.style.display = !t || (tr.dataset.name || "").indexOf(t) > -1 ? "" : "none";
  });
};
/* زر السهم بجوار عنوان الصفحة */
function backArrow() {
  return `<button class="pt-arrow" onclick="history.back()" title="رجوع">
    <svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 12h15M13 6l6 6-6 6"/></svg></button>`;
}

/* الصفوف المحدَّدة */
function ptSelected() {
  return [...document.querySelectorAll("#ptBody tr.sel")].map(tr => tr.dataset.id);
}

/* تصفية حسب الحالة */
window.ptFilter = function (mode) {
  document.querySelectorAll("#ptBody tr").forEach(tr => {
    const on = tr.dataset.active === "1";
    tr.style.display = mode === "all" ? "" : (mode === "on" ? (on ? "" : "none") : (on ? "none" : ""));
  });
  /* الزرُّ المختار يُبرَز، والبحثُ يبقى مطبَّقاً فوق الفرز */
  document.querySelectorAll(".pt-tab").forEach(b => {
    b.classList.toggle("on", b.dataset.ptfilter === mode);
  });
};
/* فرزُ بطاقات المنشآت بالحالة — نظيرُ ptFilter في الجداول */
window.facFilter = function (mode) {
  document.querySelectorAll("#facGrid .fac-card").forEach(function (c) {
    var on = c.getAttribute("data-active") !== "0";
    c.style.display = mode === "all" ? "" : (mode === "on" ? (on ? "" : "none") : (on ? "none" : ""));
  });
  document.querySelectorAll(".pt-tab").forEach(function (b) {
    b.classList.toggle("on", b.dataset.ptfilter === mode);
  });
};

window.ptFilterOpen = function (btn) {
  const pan = document.getElementById("ptFilterPanel");
  if (pan) pan.style.display = pan.style.display === "block" ? "none" : "block";
};

/* تحديث حالة مجموعة مستخدمين */
function ptSetActive(ids, val) {
  let n = 0;
  ids.forEach(id => {
    const u = DB.users && DB.users.find(x => String(x.id) === String(id));
    if (u) { u.active = val; persistSet("users", u); n++; }
  });
  return n;
}

/* إجراءات لوحة الجانب — كلها تعمل فعلياً */
window.ptAct = function (kind) {
  const ids = ptSelected();
  if (!ids.length) { showToast("حدّد صفاً واحداً على الأقل", "warn"); return; }
  const people = (DB.users || []).filter(u => ids.indexOf(String(u.id)) > -1);
  const names = people.map(u => u.name || u.email).join("، ");

  if (kind === "msg" || kind === "bell") {
    const isMsg = kind === "msg";
    openModal(
      isMsg ? "إرسال رسالة" : "إرسال إشعار",
      `إلى ${ids.length} مستخدم: ${names}`,
      `<div class="form-grid">
        <div class="field full"><label>العنوان <span class="req">*</span></label>
          <input id="ptMsgTitle" placeholder="${isMsg ? "عنوان الرسالة" : "عنوان الإشعار"}"></div>
        <div class="field full"><label>النص <span class="req">*</span></label>
          <textarea id="ptMsgBody" rows="4" placeholder="اكتب النص هنا"></textarea></div>
      </div>`,
      `<button class="btn btn-primary" data-action="pt-send-${kind}">إرسال</button>
       <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`
    );
    return;
  }

  /* التعديلُ من اللوحة: صفٌّ واحدٌ لا غير — تعديلُ عشرةٍ معاً لا معنى له */
  /* النقلُ يفتح شاشةَ نقل الطلاب المبنيّة أصلاً، محمّلاً المحدَّدين */
  if (kind === "move") {
    try { sessionStorage.setItem("__moveIds", JSON.stringify(ids)); } catch (e) {}
    go("move-students");
    return;
  }

  if (kind === "edit") {
    if (ids.length !== 1) { showToast("حدّد صفاً واحداً للتعديل", "warn"); return; }
    const pg = String((STATE && STATE.page) || "");
    if (pg === "circles")      { modalEditCircle(ids[0]);  return; }
    if (pg === "teachers")     { modalEditTeacher(ids[0]); return; }
    if (pg === "students")     { modalEditStudent(ids[0]); return; }
    showToast("التعديل غير متاح في هذه الشاشة", "warn");
    return;
  }

  if (kind === "stop" || kind === "play") {
    const val2 = kind === "play";
    const n = ptSetActive(ids, val2);
    showToast(`${val2 ? "تم تفعيل" : "تم إيقاف"} ${n} مستخدم`, "success");
    mount();
    return;
  }

  if (kind === "delete") {
    openModal("تأكيد الحذف", "",
      noteCard(`سيتم حذف <strong>${ids.length}</strong> مستخدم نهائياً: ${esc(names)}. لا يمكن التراجع.`),
      `<button class="btn btn-danger" data-action="pt-delete">حذف نهائي</button>
       <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`
    );
  }
};

/* تنفيذ الإرسال والحذف بعد التأكيد */
window.ptSend = function (kind) {
  const title = (val("#ptMsgTitle") || "").trim();
  const text  = (val("#ptMsgBody") || "").trim();
  if (!title || !text) { showToast("العنوان والنص مطلوبان", "warn"); return; }
  const ids = ptSelected();
  const people = (DB.users || []).filter(u => ids.indexOf(String(u.id)) > -1);
  const coll = kind === "msg" ? "site_messages" : "notifications";
  if (!Array.isArray(DB[coll])) DB[coll] = [];
  people.forEach(u => {
    const rec = { id: Date.now() + "-" + u.id, title, text, ts: Date.now(),
                  toEmail: (u.email || "").toLowerCase(), toId: u.id, read: false,
                  type: kind === "msg" ? "info" : "warn" };
    DB[coll].push(rec);
    persistSet(coll, rec);
  });
  closeModal();
  showToast(`تم الإرسال إلى ${people.length} مستخدم`, "success");
};

window.ptDelete = function () {
  const ids = ptSelected();
  ids.forEach(id => {
    const i = (DB.users || []).findIndex(x => String(x.id) === String(id));
    if (i > -1) { DB.users.splice(i, 1); persistDelete("users", id); }
  });
  closeModal();
  showToast(`تم حذف ${ids.length} مستخدم`, "success");
  mount();
};


/* ---- أعمدة الجداول ---- */
function colPhoto() { return { h: "الصورة", cell: p2 => `<td class="pt-photo"><span class="pt-avatar">${personAvatar(p2)}</span></td>` }; }
function colName()  { return { h: "الاسم",  cell: p2 => `<td class="pt-name">${esc(p2.name || "—")}</td>` }; }
function colState() { return { h: "الحالة", cell: (p2, a) => `<td><span class="pt-badge ${a ? "on" : "off"}">${a ? "فعال" : "متوقف"}</span></td>` }; }
function colPhone() { return { h: "رقم الواتس", cell: p2 => `<td dir="ltr" class="pt-num">${esc(p2.phone || p2.whatsapp || "—")}</td>` }; }
function colNat()   { return { h: "الجنسية", cell: p2 => `<td>${esc(p2.nationality || "المملكة العربية السعودية")}</td>` }; }

/* تبويبا صفحة الكادر: المعلّمون والمدراء في مجموعةٍ واحدة، وقد صار
   بينهما فارقٌ مخزَّن (staffRole) — فيُفصلان في العرض أيضاً، وإلا فما
   فائدةُ التمييز. الافتراضُ المعلّمون: هم غالبُ المجموعة. */
/* مشرفو النطاق الحالي: حساباتُ الإدارة في users داخل ما يراه المستخدم.

   المعلّمون سجلّاتٌ في teachers، والمشرفون حساباتُ دخولٍ في users —

   مجموعتان مختلفتان، فيُجمعان هنا ليُعرضا في جدولٍ واحدٍ بتبويبين. */

function scopeSupervisors() {

  var u = (typeof STATE !== "undefined" && STATE.user) || {};

  var mq = facLockedMosqueId();

  if (mq) return facilitySupervisors("mosque", mq);

  var cx = facCtxComplexId() || u.complexId || (typeof STATE !== "undefined" ? STATE.complexId : "");

  if (cx) return facilitySupervisors("complex", cx);

  return (Array.isArray(DB.users) ? DB.users : []).filter(function (x) {

    return x && isMgrRole(x.role);

  });

}



function staffTabCur() {
  var v = String(STATE.staffTab || "");
  return (v === "managers" || v === "sups") ? v : "teachers";
}

window.staffTabSet = function (k) {
  const v = (k === "managers" || k === "sups") ? k : "teachers";
  if (staffTabCur() === v) return;
  STATE.staffTab = v;
  mount();
};

function staffTabsBar(nTeach, nMgr, nSup) {
  const t = staffTabCur();
  const items = [["teachers", "المعلمين", nTeach, "teacher"]];
  if (nSup != null) items.push(["sups", "المشرفين", nSup, "person"]);
  if (nMgr != null) items.push(["managers", "المدراء", nMgr, "person"]);
  return `<div class="fac-tabs">
    ${items.map(([k, h, n, i]) =>
      `<button type="button" class="fac-tab${t === k ? " on" : ""}"
        onclick="window.staffTabSet('${k}')">
        ${ic(i, 17)}<span>${esc(h)}</span>
        <b>${n}</b>
      </button>`).join("")}
  </div>`;
}

function adminManagers() {
  /* الصفحةُ واحدةٌ واسمُها يتبع الناظر: مديرُ المسجد يرى فيها معلّميه
     ومشرفيه، ومديرُ النظام يرى مدراءَ المنشآت. والقائمةُ الجانبية تسمّيها
     بالاسم نفسه في shell.js، فلا يختلف البندُ عن العنوان. */
  const _r = ((STATE && STATE.user) || {}).role || "";
  const _all  = cur("teachers");
  /* سجلاتُ الكادر المعلَّمة «مدير» لم تعد تُعرض في تبويبٍ: المدراء
     حساباتٌ في users لا سجلاتُ كادر. والحقلُ باقٍ فلا يُفقد تمييز. */
  const _tchs = _all.filter(x => !isStaffManager(x));
  /* مديرُ النظام يرى المدراءَ وحدهم: الصفحةُ اسمُها «مدراء المنشآت»،
     والمعلّمون شأنُ مديري المساجد لا شأنُه. ولمن دونه يبقى التبويبان. */
  /* مديرُ النظام يرى المدراءَ وحدهم، ومديرُ المسجد يرى معلّميه وحدهم —
     المديرُ عنده واحدٌ لا يتغيّر فلا معنى لصفحةٍ له. والتبويبان يبقيان
     لمن يحتاج الاثنين. */
  /* المشرفون حساباتُ إدارةٍ في users لا سجلّاتٍ في teachers، فيُقرآن من
     مصدرهما ويُعرضان في تبويبٍ ثالث بالجدول نفسه. */
  /* الحساباتُ الإداريةُ في النطاق تُقسَم: تبويبُ «المشرفين» للمشرفين
     وحدهم، وتبويبُ «المدراء» لمديري المساجد والمجمّعات. كانت الدالّةُ
     تُرجعهم جميعاً فيظهر مديرُ المسجد في تبويب المشرفين. */
  const _acctMap = u => ({
    id: u.id, name: u.name || u.email || "—",
    photo: u.photo || "", phone: u.phone || u.whatsapp || "",
    nationality: u.nationality || "", status: u.active === false ? "متوقف" : "نشط",
    active: u.active !== false, _isSup: true,
    /* نطاقُ الحساب نصّاً: أيَّ منشأةٍ يدير — وإلا فالصفُّ اسمٌ بلا موضع */
    scopeName: (typeof facScopeLabel === "function" ? facScopeLabel(u) : ""),
    roleAr: u.role === "complexManager" ? "مدير مجمّع"
          : u.role === "mosqueManager"  ? "مدير مسجد" : "مشرف"
  });

  const _accts   = scopeSupervisors();
  const _sups    = _accts.filter(u => String(u.role) === "supervisor").map(_acctMap);
  const _mgrAcct = _accts.filter(u => String(u.role) !== "supervisor").map(_acctMap);

  /* «مدراء المنشآت» عند مدير النظام: حساباتُ المدراء في users، لا سجلّاتُ
     الكادر في teachers. مديرُ المسجد يُنشأ حسابُه من صفحة المستخدمين
     ويُربط بمسجده، ولا يُكتب له سجلٌّ في teachers — فكانت الصفحةُ تعدّ
     المجموعة الخطأ وتقول «صفر» وإن كان للمساجد مدراء. */
  /* داخل منشأةٍ بعينها يرى مديرُ النظام التبويبين: مدراؤها ومعلّموها.
     وخارجها تبقى الصفحةُ «مدراء المنشآت» فحسب — وهو معناها عنده. */
  const _inFac   = !!facCtx();
  /* التبويبان يظهران للجميع: مديرُ النظام يحتاج المعلّمين كما يحتاج
     المدراء، وإخفاؤهما عنه كان يجعل الصفحةَ نصفَ صفحة. */
  const _onlyMgr = false;
  const _tab  = staffTabCur();
  const _list = _tab === "managers" ? _mgrAcct
              : (_tab === "sups" ? _sups : _tchs);

  const _title = _tab === "managers" ? "المدراء"
    : (_tab === "sups" ? "المشرفين" : "المعلمين");

  return personTable({
    list: _list, title: _title, toolbar: "circles", actionsPanel: true,
    /* صفُّ المشرف لا يفتح نموذجَ المعلّم: هو حسابٌ لا سجلُّ كادر */
    rowPanel: _tab === "sups" ? "" : "edit-teacher",
    overview: _onlyMgr ? "" : staffTabsBar(_tchs.length, null, _sups.length),
    addAction: "modal-teacher",
    empty: _tab === "managers"
      ? "لا مدراء بعد — عيّن «النوع: مدير منشأة» في بيانات من هو مدير."
      : (_tab === "sups"
        ? "لا مشرفين في نطاقك — تُنشأ حساباتهم من صفحة المستخدمين والحسابات."
        : "أضف معلماً من زر الإضافة في شريط الأدوات."),
    /* عمودُ «المنشآت» حُذف: يُملأ من m.managerId وهو حقلٌ لا يُكتب في
       النظام، فيقول «لا يوجد منشآت» في كلّ سطرٍ أبداً — عمودٌ بلا خبر.
       وعمودُ «الإجراءات» حُذف: التعديلُ بالنقر على الصفّ، والباقي في
       لوحة الإجراءات جانباً، فلا يتكرّر الفعلُ في موضعين. */
    cols: (_tab === "teachers")
      ? [ colPhoto(), colName(), colState(), colPhone(), colNat() ]
      : [ colPhoto(), colName(), colState(),
          { h: "الدور",   cell: p2 => `<td>${esc(p2.roleAr || "—")}</td>` },
          { h: "المنشأة", cell: p2 => `<td class="${p2.scopeName ? "" : "pt-muted"}">${esc(p2.scopeName || "غير مربوط")}</td>` },
          colPhone() ]
  });
}


/* =========================================================================
   نافذة إضافة/تعديل مستخدم (مشرف · مدير · معلم)
   كانت data-action="modal-user" مشار إليها بلا معالج، فكان الزر لا يفعل شيئاً.
   ========================================================================= */
/* كان الطالب وولي الأمر غائبَين عن القائمة رغم أن النظام يتعامل بهما
   في كل مكان: الصلاحيات والواجهات والتنبيهات. فلا يُعتمد حسابُ طالبٍ
   سجّل دخوله لأن دوره غير معروض أصلاً. */
const USER_ROLES = [
  { k: "complexManager", h: "مدير مجمّع" },
  { k: "mosqueManager",  h: "مدير مسجد" },
  /* المشرف: يعمل في مسجدٍ واحد على الطلاب والحلقات والإجراءات والنقاط */
  { k: "supervisor",     h: "مشرف" },
  { k: "admin",      h: "مدير" },
  { k: "teacher",    h: "معلم / ة" },
  { k: "student",    h: "طالب / ة" },
  { k: "parent",     h: "ولي أمر" },
  /* داعم المسجد: قراءةٌ فقط — لوحة الشرف وتقارير مسجده */
  { k: "donor",      h: "داعم" },

  /* مالك النظام: صلاحيةٌ مطلقة بلا نطاق ولا قيد. لا يُمنح إلا من مالكٍ
     قائم — ولذلك يُرشَّح من القائمة بـ assignableRoles. */
  { k: "owner",      h: "مالك النظام" }
];

/* =========================================================================
   من يُمنح أيّ دور
   -------------------------------------------------------------------------
   منح owner يعني تجاوز كلّ حصرٍ في النظام: النطاق والمالي والهرمية معاً.
   فلو أتيح للمدير رقّى نفسه بنقرة. ولا يمنحه إلا مالكٌ قائم — وهذا ما
   تفرضه قواعد Firestore أيضاً، فالمنع في الواجهة تنبيهٌ لا حماية.
   ========================================================================= */
/* =========================================================================
   المالك والمدير العام سواء
   -------------------------------------------------------------------------
   كان المالك يتفرّد بستّ صلاحيات: رؤية كلّ المجمّعات، وفتح الدورات
   المؤرشفة، وتجاوز شرط الترقية، ومنح دور المالك، وتعديل حسابه، والمالية.
   والتفريق كان يعطّل المدير العام في نظامٍ لا مالك فيه غيره.

   وقد سُوِّي بينهما بطلب الإدارة. والأثر الرقابي يبقى: كلّ حركةٍ خطيرة
   تُرصد في سجل العمليات باسم فاعلها، فالتساوي في الصلاحية لا يعني
   التساوي في الغُفلان.

   ⚠ ما يترتّب على هذا: من ملك حساب مديرٍ ملك النظام كلّه — يمنح نفسه
   دور المالك ويعزل غيره. فحماية حسابات المديرين صارت حماية النظام.
   ========================================================================= */
function isTopAdmin(u) {
  const r = ((u || (STATE && STATE.user) || {}).role) || "";
  return r === "owner" || r === "admin";
}

function assignableRoles() {
  const r = ((STATE && STATE.user) || {}).role || "";
  if (isTopAdmin()) return USER_ROLES;          /* المالك والمدير سواء */
  return USER_ROLES.filter(x => x.k !== "owner");
}

/* المالك لا يُعدَّل ولا يُوقَف إلا من مالك — وإلا عُزل صاحب النظام بنقرة */
function canEditUser(u) {
  const me = ((STATE && STATE.user) || {}).role || "";
  if (isTopAdmin()) return true;                /* كلاهما يعدّل الآخر */
  return !u || u.role !== "owner";
}

/* =========================================================================
   إنشاء حساب دخول في Firebase Auth — دالة واحدة يستدعيها كل مسارات الإضافة
   -------------------------------------------------------------------------
   كان لدينا مساران متباعدان: صفحة «المستخدمون والحسابات» تُنشئ حساب دخول
   حقيقياً، وصفحة «المشرفين / ات» تكتب مستند Firestore فقط — فالمشرف المُضاف
   منها لا يستطيع الدخول إطلاقاً لأن لا حساب Auth له.

   التحصينات المطبَّقة هنا:
   • تطبيق Firebase ثانوي معزول، فجلسة المدير في التطبيق الأساسي لا تتأثر.
   • persistence = NONE فلا يلمس التطبيق الثانوي تخزين المتصفح أصلاً، ثم
     يُحذف بعد الاستخدام (كان يبقى قائماً ويشارك التخزين).
   • كلمة المرور تُولَّد عشوائياً بـ crypto لا يخترعها المدير.
   • البريد الحقيقي: يُرسَل رابط تعيين ولا تُكشف كلمة المرور إطلاقاً.
     بريد الهوية الاصطناعي {id}@mirath.id لا تصله رسائل، فتُعاد كلمة المرور
     مرة واحدة ليسلّمها المدير.
   • معرّف المستند = uid الحقيقي، فتعمل القواعد والدخول بالمطابقة المباشرة.
   ========================================================================= */
const AUTH_HELPER_APP = "userCreator";

function randomPassword(len) {
  /* بلا أحرف متشابهة (0/O · 1/l/I) لتسهيل التسليم اليدوي */
  const abc = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%*";
  const n = len || 20;
  let out = "";
  if (typeof crypto !== "undefined" && crypto.getRandomValues) {
    const buf = new Uint32Array(n);
    crypto.getRandomValues(buf);
    for (let i = 0; i < n; i++) out += abc[buf[i] % abc.length];
  } else {
    for (let i = 0; i < n; i++) out += abc[Math.floor(Math.random() * abc.length)];
  }
  return out;
}

function authErrMsg(err) {
  const c = String((err && err.code) || "");
  if (c.indexOf("email-already-in-use") > -1) return "لهذا البريد أو رقم الهوية حساب دخول بالفعل";
  if (c.indexOf("invalid-email") > -1)        return "صيغة البريد الإلكتروني غير صحيحة";
  if (c.indexOf("weak-password") > -1)        return "كلمة المرور ضعيفة";
  if (c.indexOf("operation-not-allowed") > -1)
    return "التسجيل بالبريد وكلمة المرور معطّل — فعّله من Firebase Console ← Authentication";
  if (c.indexOf("network") > -1)              return "تعذّر الاتصال بالشبكة";
  return "تعذّر إنشاء حساب الدخول" + (c ? " (" + c + ")" : "");
}

/* يُرجع { uid, loginEmail, resetSent, tempPassword } — أو يرمي خطأً واضحاً */
/* =========================================================================
   مزامنة حساب المستخدم مع سجل المعلم
   -------------------------------------------------------------------------
   المجموعتان منفصلتان في هذا المشروع: users فيها حسابات الدخول وأدوارها،
   و teachers فيها سجلات المعلمين التي تُربط بها الحلقات. وإنشاء حساب بدور
   «معلم» كان يكتب في users وحدها، فلا يظهر صاحبه في صفحة «مدراء المنشآت»
   ولا في قائمة «المعلم المسؤول» عند إضافة حلقة، وترجع myTeacherRecord()
   فارغة فلا تُعرف حلقاته. هذه الدالة تسدّ الفجوة عند الحفظ.
   ========================================================================= */
/* =========================================================================
   مزامنة حساب المستخدم مع ملف الطالب
   -------------------------------------------------------------------------
   نفس فجوة المعلمين: users فيها حسابات الدخول، و students فيها ملفات
   الطلاب التي تُربط بها الحلقات والحضور والتسميع. الموافقة على طالب كانت
   تفعّل حسابه فقط، فلا يظهر في صفحة الطلاب ولا تجد له myStudents ملفاً،
   فتبقى واجهته فارغة تماماً.

   وتُكتب studentId في حساب المستخدم ليصير الربط بالمعرّف لا بالاسم.
   ========================================================================= */
function syncStudentRecord(u) {
  if (!u || u.role !== "student") return null;
  if (!Array.isArray(DB.students)) DB.students = [];

  const key = x =>
       (u.studentId && String(x.id) === String(u.studentId))
    || (u.uid && String(x.uid || "") === String(u.uid))
    || (u.email && String(x.email || "").toLowerCase() === String(u.email).toLowerCase())
    || (u.name && String(x.name || "").trim() === String(u.name).trim());

  let st = DB.students.find(key);
  const mq = Array.isArray(DB.mosques) ? DB.mosques : [];
  const fields = {
    name: u.name || "—",
    uid: u.uid || "",
    email: u.email || "",
    phone: u.phone || "—",
    photo: u.photo || "",
    gender: u.gender || "ذكر",
    nationality: u.nationality || "",
    complexId: u.complexId || STATE.complexId,
    mosqueId: u.mosqueId || "",
    mosque: u.mosqueId ? ((mq.find(m => String(m.id) === String(u.mosqueId)) || {}).name || "—") : "—",
    status: u.active === false ? "متوقف" : "نشط"
  };

  if (st) {
    /* =====================================================================
       المزامنة تملأ ولا تدهس
       ---------------------------------------------------------------------
       كانت تنسخ حقولَ الحساب فوق ملفّ الطالب كلَّما اختلفا، وهي تجري بعد
       كلّ تحميلٍ للبيانات (syncAllTeachers). فمن عدّل اسم الطالب في بطاقته
       رآه محفوظاً، ثمّ أعاد التحميل فعاد الاسمُ القديم — لأن اسمَ الحساب
       لم يتغيّر، فدهس المُعدَّل وكُتب في قاعدة البيانات. وكذلك الجوّال
       والجنسية والحالة.

       الحسابُ يملك ما لا يُعدَّل في البطاقة: uid وحدَه. وما عداه يُملأ إن
       كان فارغاً في الملفّ — وهو مقصدُ المزامنة الأصليّ: ملفٌّ ناقصٌ
       يُكمَّل — ولا يُمَسّ إن كان مكتوباً.
       ===================================================================== */
    const BLANK = ["", "—", "-", "null", "undefined"];
    const empty = v => BLANK.indexOf(String(v == null ? "" : v).trim()) > -1;
    const OWNED = ["uid"];               /* للحساب وحدَه: ليس في أيّ نموذج */
    const patch = {};
    Object.keys(fields).forEach(k => {
      const nv = fields[k];
      if (OWNED.indexOf(k) > -1) { if (String(st[k] || "") !== String(nv || "")) patch[k] = nv; return; }
      if (empty(st[k]) && !empty(nv)) patch[k] = nv;
    });
    if (Object.keys(patch).length) { Object.assign(st, patch); persistSet("students", st); }
  } else {
    /* طالب جديد بلا حلقة — تُسنده الإدارة لاحقاً من صفحة الطلاب */
    st = Object.assign({
      id: Date.now(), circle: "—", circleId: "", teacher: "—", teacherId: "",
      age: "—", parent: "—", attType: "دوام كامل", days: "يومياً",
      program: "—", level: "—", progress: 0, delays: 0, points: 0
    }, fields);
    DB.students.push(st);
    persistSet("students", st);
  }

  /* الربط بالمعرّف في حساب المستخدم */
  if (String(u.studentId || "") !== String(st.id)) {
    u.studentId = String(st.id);
    persistSet("users", u);
  }
  return st;
}

function syncTeacherRecord(u) {
  if (!u || u.role !== "teacher") return null;
  if (!Array.isArray(DB.teachers)) DB.teachers = [];

  const key = x =>
       (u.uid && String(x.uid || "") === String(u.uid))
    || (u.username && String(x.username || "") === String(u.username))
    || (u.email && String(x.username || "").toLowerCase() === String(u.email).toLowerCase())
    || (u.name && String(x.name || "").trim() === String(u.name).trim());

  let t = DB.teachers.find(key);
  const mq = Array.isArray(DB.mosques) ? DB.mosques : [];
  const fields = {
    name: u.name || "—",
    uid: u.uid || "",
    username: u.username || u.email || u.loginEmail || "—",
    phone: u.phone || "—",
    complexId: u.complexId || STATE.complexId,
    mosqueId: u.mosqueId || "",
    mosque: u.mosqueId ? ((mq.find(m => String(m.id) === String(u.mosqueId)) || {}).name || "—") : "—",
    status: u.active === false ? "متوقف" : "نشط"
  };

  if (t) {
    /* الكتابة عند التغيّر فقط — وإلا صار كل تحميل للصفحة يكتب في قاعدة
       البيانات مرة لكل معلم بلا فائدة. */
    const same = Object.keys(fields).every(k => String(t[k] == null ? "" : t[k]) === String(fields[k] == null ? "" : fields[k]));
    if (same) return t;
    Object.assign(t, fields);
  } else {
    t = Object.assign({ id: Date.now(), circle: "—", circleId: "", students: 0,
                        session: "لم تعتمد", attDone: false, recite: 0, late: 0 }, fields);
    DB.teachers.push(t);
  }
  persistSet("teachers", t);
  return t;
}

/* مزامنة كل حسابات المعلمين دفعة واحدة — تُستدعى بعد تحميل البيانات،
   فتُنشئ سجلات المعلمين للحسابات التي أُضيفت قبل وجود هذه المزامنة. */
function syncAllTeachers() {
  const users = Array.isArray(DB.users) ? DB.users : [];
  let n = 0;
  users.filter(u => u && u.role === "teacher").forEach(u => {
    const before = (Array.isArray(DB.teachers) ? DB.teachers : []).length;
    const t = syncTeacherRecord(u);
    if (t && ((Array.isArray(DB.teachers) ? DB.teachers : []).length > before)) n++;
  });
  /* والطلاب كذلك — حسابات فُعّلت قبل وجود هذه المزامنة */
  users.filter(u => u && u.role === "student" && u.active !== false).forEach(u => {
    const before = (Array.isArray(DB.students) ? DB.students : []).length;
    syncStudentRecord(u);
    if ((Array.isArray(DB.students) ? DB.students : []).length > before) n++;
  });
  return n;
}

async function createAuthUser(opts) {
  opts = opts || {};
  if (typeof firebase === "undefined" || !firebase.initializeApp)
    throw new Error("Firebase SDK غير محمّل");

  const username   = String(opts.username || "").replace(/[^0-9]/g, "");
  const realEmail  = String(opts.email || "").trim();
  const loginEmail = realEmail || (username ? username + "@mirath.id" : "");
  if (!loginEmail) throw new Error("يلزم بريد إلكتروني أو رقم هوية");

  const password = opts.password || randomPassword();
  const cfg = firebase.app().options;

  let secondary = firebase.apps.find(a => a.name === AUTH_HELPER_APP);
  if (!secondary) secondary = firebase.initializeApp(cfg, AUTH_HELPER_APP);

  try {
    try {
      await secondary.auth().setPersistence(firebase.auth.Auth.Persistence.NONE);
    } catch (e) { console.warn("setPersistence:", e); }

    const cred = await secondary.auth().createUserWithEmailAndPassword(loginEmail, password);
    const uid = cred.user.uid;

    let resetSent = false;
    if (realEmail) {
      /* الإرسال من التطبيق الأساسي — عملية على مستوى المشروع لا الجلسة */
      try { await firebase.auth().sendPasswordResetEmail(realEmail); resetSent = true; }
      catch (e) { console.warn("sendPasswordResetEmail:", e); }
    }
    /* كانت تُطرح كلمة المرور متى أُرسل رابط التعيين، فإن لم تصل الرسالة
       (تأخير · مجلد مهملات · بريد خاطئ) بقي الحساب بلا أي طريقة دخول.
       تُعاد الآن دائماً كخطة بديلة تُعرض للمدير مرة واحدة. */
    return { uid, loginEmail, resetSent, tempPassword: password };
  } finally {
    try { await secondary.auth().signOut(); } catch (e) {}
    try { await secondary.delete(); } catch (e) {}
  }
}

/* تُعرض كلمة المرور المبدئية مرة واحدة فقط — لا تُخزَّن ولا تُسجَّل */
function showCredentials(res, name) {
  const creds = `<div class="form-grid" style="margin-top:12px">
        <div class="field"><label>بريد الدخول</label>
          <input dir="ltr" readonly value="${esc(res.loginEmail)}" onclick="this.select()"></div>
        <div class="field"><label>كلمة المرور المبدئية</label>
          <input dir="ltr" readonly value="${esc(res.tempPassword || "—")}" onclick="this.select()"></div>
      </div>`;
  const body = res.resetSent
    ? noteCard("أُنشئ حساب الدخول، وأُرسل <strong>رابط تعيين كلمة المرور</strong> إلى " +
               esc(res.loginEmail) + ". والأفضل أن يضبطها المستخدم بنفسه من الرابط.<br>" +
               "وإن لم تصل الرسالة، سلّمه البيانات التالية — <strong>لن تظهر مرة أخرى</strong>.") + creds
    : noteCard("أُنشئ حساب الدخول. بريد الهوية الاصطناعي <strong>لا تصله رسائل</strong>، " +
               "فسلّم هذه البيانات للمستخدم الآن — لن تظهر مرة أخرى.") + creds;
  openModal("حساب " + esc(name || "") + " جاهز", "", body,
    `<button class="btn btn-primary" data-action="close-modal">تم</button>`);
}

/* =========================================================================
   أماكن الإشراف — منشأة واحدة لم تعد تكفي
   -------------------------------------------------------------------------
   كان الحقل قائمة مفردة تكتب complexId أو mosqueId، فالمشرف على مسجدين
   يُسجَّل على أحدهما ولا يرى الآخر. صار الحقل متعدّد الاختيار يكتب
   scopeIds[]، مع إبقاء complexId/mosqueId للتوافق مع السجلات القديمة
   وللمرشد البصري في بقية الشاشات.

   scopeIds عناصرها بصيغة "نوع:معرّف" — مثل "mosque:17" و"complex:3" —
   لأن المعرّفات قد تتكرر بين المجموعتين ولا يصح الاعتماد على الرقم وحده.
   ========================================================================= */

function facKey(kind, id) { return kind + ":" + String(id); }

function userScopeIds(u) {
  if (!u) return [];
  if (Array.isArray(u.scopeIds) && u.scopeIds.length) return u.scopeIds.map(String);
  /* السجلات القديمة: حقل مفرد */
  if (u.mosqueId)  return [facKey("mosque", u.mosqueId)];
  if (u.complexId) return [facKey("complex", u.complexId)];

  /* =======================================================================
     الاشتقاق من السجل المرتبط
     -----------------------------------------------------------------------
     كان النظام يفرض إدخال المنشأة مرتين: في ملف الطالب/المعلم، وفي حساب
     المستخدم. ونسيان الثانية يترك الحساب بلا نطاق فيظهر «—» ولا يرى شيئاً
     رغم أن ملفه مسنَد لمسجد. تُشتقّ المنشأة الآن من السجل نفسه.
     ======================================================================= */
  const out = [];
  const push = r => {
    if (!r) return;
    if (r.mosqueId  && out.indexOf(facKey("mosque",  r.mosqueId))  < 0) out.push(facKey("mosque",  r.mosqueId));
    if (r.complexId && out.indexOf(facKey("complex", r.complexId)) < 0) out.push(facKey("complex", r.complexId));
  };

  const role = u.role || "";
  const students = Array.isArray(DB.students) ? DB.students : [];
  const teachers = Array.isArray(DB.teachers) ? DB.teachers : [];
  const mail = String(u.email || "").toLowerCase();

  if (role === "student" || role === "parent") {
    students.forEach(st => {
      const mine =
           (u.studentId && String(st.id) === String(u.studentId))
        || (Array.isArray(u.studentIds) && u.studentIds.map(String).indexOf(String(st.id)) > -1)
        || (u.uid && String(st.uid || "") === String(u.uid))
        || (mail && String(st.email || "").toLowerCase() === mail)
        || (mail && String(st.guardianEmail || "").toLowerCase() === mail)
        || (role === "parent"  && u.name && String(st.parent || "") === String(u.name))
        || (role === "student" && u.name && String(st.name   || "") === String(u.name));
      if (mine) push(st);
    });
  } else if (role === "teacher") {
    teachers.forEach(t => {
      const mine =
           (u.uid && String(t.uid || "") === String(u.uid))
        || (u.username && String(t.username || "") === String(u.username))
        || (mail && String(t.username || "").toLowerCase() === mail)
        || (u.name && String(t.name || "").trim() === String(u.name).trim());
      if (mine) push(t);
    });
  }

  return out;
}

function facPickField(id, u) {
  const sel = userScopeIds(u);
  const cx = cur("complexes"), mq = cur("mosques");
  const row = (kind, f) => {
    const k = facKey(kind, f.id);
    const on = sel.indexOf(k) > -1;
    return `<label class="fp-item ${on ? "on" : ""}">
      <input type="checkbox" value="${esc(k)}" ${on ? "checked" : ""}
        onchange="window.facPickToggle(this)">
      <span class="fp-ico">${ic(kind === "mosque" ? "mosque" : "building", 15)}</span>
      <span class="fp-name">${esc(f.name || "—")}</span>
      <span class="fp-kind">${kind === "mosque" ? "مسجد" : "مجمع"}</span>
    </label>`;
  };

  if (!cx.length && !mq.length) {
    return `<div class="muted" style="padding:10px">لا توجد منشآت بعد — أضف مجمعاً أو مسجداً أولاً.</div>`;
  }

  return `<div class="fp-box" id="${id}">
    ${cx.length ? `<div class="fp-group">المجمعات</div>${cx.map(f => row("complex", f)).join("")}` : ""}
    ${mq.length ? `<div class="fp-group">المساجد</div>${mq.map(f => row("mosque", f)).join("")}` : ""}
  </div>`;
}

window.facPickToggle = function (cb) {
  const lb = cb.closest(".fp-item");
  if (lb) lb.classList.toggle("on", cb.checked);
};

function facPickValue(id) {
  const box = document.getElementById(id);
  if (!box) return [];
  return Array.prototype.slice.call(box.querySelectorAll("input:checked")).map(x => x.value);
}

/* =========================================================================
   مصفوفة صلاحيات المعلم
   -------------------------------------------------------------------------
   تُضبط لكل معلّم على حدة كما تنص الوثيقة. تُخزَّن في users/{uid}.perms
   على هيئة { المفتاح: true/false }، ويقرأها teacherCan.

   الغياب يعني السماح: الحسابات القائمة قبل هذه الشاشة تبقى عاملة كما هي،
   ولا يُفاجأ معلّم بقفل صلاحية لم تُعطَّل صراحةً.
   ========================================================================= */

const TEACHER_PERMS = [
  { g: "التحضير والتعديل" },
  { k: "attLate",     h: "التحضير بعد انتهاء وقت الحلقة",
    d: "تعطيلها يمنع فتح شاشة التحضير بعد وقت الحلقة الرسمي" },
  { k: "attEdit",     h: "تعديل التحضير بعد اعتماد الحلقة",
    d: "تعطيلها يقفل حالة الحضور نهائياً بعد الاعتماد" },

  { g: "الخطة والواجبات" },
  { k: "editPlan",    h: "وضع الواجبات وتعديل مسار الخطة",
    d: "تحديد موضع الحفظ والمراجعة والمقدار لكل طالب" },
  /* المواصفات: «تغيير مسار خطة الطالب — وتشمل ثلاث صلاحيات فرعية» */
  { k: "planStart",   h: "تغيير موضع البداية للواجب", d: "فرعيّةٌ من تعديل المسار" },
  { k: "planQty",     h: "تغيير عدد الأوجه أو الأسطر المحددة", d: "فرعيّةٌ من تعديل المسار" },
  { k: "planEnd",     h: "تغيير موضع النهاية للواجب", d: "تعطيلُ الثلاث: المعلّم ملتزمٌ حرفياً بالخطة المبرمجة" },
  { k: "extraDuty",   h: "إضافة واجبات وتسميعات طارئة",
    d: "خارج نطاق الخطة الأساسية للطالب" },

  { g: "المصحف والتقييم" },
  { k: "editMarks",   h: "تعديل أخطاء المصحف السابقة",
    d: "تعطيلها يجعل تأشير الأيام الماضية غير قابل للتغيير" },

  { g: "إدارة الحلقة" },
  { k: "addStudent",  h: "ضمّ طالب جديد للحلقة",
    d: "دون الرجوع لقسم القبول والتسجيل" },
  { k: "freezeStudent", h: "إيقاف أو تجميد طالب",
    d: "لأسباب تأديبية أو انقطاع" },
  { k: "circleSettings", h: "تعديل إعدادات الحلقة",
    d: "الاسم ووقت البداية والنهاية" },

  { g: "التواصل" },
  { k: "room",        h: "إنشاء غرفة تسميع عن بُعد", d: "" },
  { k: "chat",        h: "إرسال إشعارات ومحادثات", d: "" }
];

function permsField(u, hidden) {
  const p = (u && u.perms) || {};
  const on = k => p[k] !== false;

  return `<div class="field full perm-wrap"${hidden ? ' style="display:none"' : ""}>
    <label>صلاحيات المعلم</label>
    <div class="perm-box">
      ${TEACHER_PERMS.map(item => {
        if (item.g) return `<div class="perm-group">${esc(item.g)}</div>`;
        return `<label class="perm-row ${on(item.k) ? "on" : ""}">
          <input type="checkbox" data-perm="${esc(item.k)}" ${on(item.k) ? "checked" : ""}
            onchange="window.permToggle(this)">
          <span class="perm-txt">
            <strong>${esc(item.h)}</strong>
            ${item.d ? `<span class="perm-d">${esc(item.d)}</span>` : ""}
          </span>
          <span class="perm-state">${on(item.k) ? "مفعّلة" : "معطّلة"}</span>
        </label>`;
      }).join("")}
    </div>
    <div class="hint">الصلاحيات المفعّلة افتراضياً — عطّل ما لا تريد إتاحته لهذا المعلم.</div>
  </div>`;
}

window.permToggle = function (cb) {
  const row = cb.closest(".perm-row");
  if (!row) return;
  row.classList.toggle("on", cb.checked);
  const st = row.querySelector(".perm-state");
  if (st) st.textContent = cb.checked ? "مفعّلة" : "معطّلة";
};

function permsValue() {
  const out = {};
  const box = document.querySelector(".perm-box");
  if (!box) return null;                 /* الحقل غير معروض: لا تُمسّ القيم */
  Array.prototype.forEach.call(box.querySelectorAll("input[data-perm]"), function (cb) {
    out[cb.dataset.perm] = !!cb.checked;
  });
  return out;
};

/* إظهار الحقل عند اختيار دور «معلم» وإخفاؤه لغيره */
window.roleChanged = function (selEl) {
  const wrap = document.querySelector(".perm-wrap");
  if (wrap) wrap.style.display = selEl.value === "teacher" ? "" : "none";

  /* حقلُ «الأبناء» يحلّ محلّ «أماكن الإشراف» لوليّ الأمر، وهما يُبنيان
     مع النموذج. فتبديلُ الدور يستلزم إعادةَ بنائه — وإلا بقي الحقلُ
     الأوّل ظاهراً ولم يجد المستخدمُ موضعاً يربط به الأبناء. */
  const wasParent = !!document.getElementById("usKidBox");
  const nowParent = selEl.value === "parent";
  if (wasParent === nowParent) return;

  const id = val("#usId");
  const keep = {
    name: val("#usName"), phone: val("#usPhone"),
    email: val("#usEmail"), nat: val("#usNat"), gender: val("#usGender")
  };

  window.userForm(id, selEl.value);

  /* ما كُتب لا يضيع بتبديل الدور */
  setTimeout(function () {
    const set = (k, v) => { const e = document.getElementById(k); if (e && v) e.value = v; };
    set("usName", keep.name); set("usPhone", keep.phone);
    set("usEmail", keep.email); set("usNat", keep.nat); set("usGender", keep.gender);
    const r = document.getElementById("usRole");
    if (r) r.value = selEl.value;
  }, 0);
};

window.userForm = function (id, presetRole) {
  const u = id ? (cur("users") || []).find(x => String(x.id) === String(id)) : null;
  const facs = cur("complexes").concat(cur("mosques"));
  const role = u ? u.role : (presetRole || "mosqueManager");

  /* حالة منتقي الأبناء تُهيّأ من الحساب: المفتوحُ بعد آخرَ لا يرث اختياره.
     ويُبدأ بما رُبط فعلاً، فإن لم يُربط بعدُ فبما رُجّح من طلب تسجيله. */
  USK.q = ""; USK.circle = "";
  USK.picked = (u && Array.isArray(u.studentIds) && u.studentIds.length)
    ? u.studentIds.map(String)
    : (u && u.studentId ? [String(u.studentId)] : []);

  if (!USK.picked.length && u && Array.isArray(u.kidsRequested)) {
    u.kidsRequested.forEach(k => {
      const g = typeof matchKid === "function" ? matchKid(k) : null;
      if (g) USK.picked.push(String(g.id));
    });
  }
  openModal(u ? "تعديل بيانات المستخدم" : "إضافة مشرف", "",
    `<input type="hidden" id="usId" value="${u ? esc(u.id) : ""}">
     <div class="form-grid">
      ${photoField("us_photo", u ? (u.photo || "") : "", "الصورة الشخصية")}
      <div class="field full"><label>الاسم <span class="req">*</span></label>
        <input id="usName" value="${u ? esc(u.name || "") : ""}" placeholder="الاسم الكامل"></div>
      <div class="field"><label>رقم الهوية <span class="req">*</span></label>
        <input id="usUser" inputmode="numeric" maxlength="10" dir="ltr" placeholder="1110071212"
          value="${u ? esc(u.username || "") : ""}"
          oninput="this.value = this.value.replace(/[^0-9]/g, '').slice(0,10)"></div>
      <div class="field"><label>البريد الإلكتروني</label>
        <div class="us-mail">
          <input id="usEmail" dir="ltr" placeholder="name@domain"
            value="${u ? esc(String(u.email || "").replace(/\.com$/i, "")) : ""}">
          <span class="us-suffix">.com</span>
        </div></div>
      <div class="field"><label>رقم الواتس</label>
        <input id="usPhone" inputmode="numeric" dir="ltr" placeholder="9665xxxxxxxx" maxlength="15"
          value="${u ? esc(u.phone || "") : ""}"
          oninput="this.value = this.value.replace(/[^0-9]/g, '').slice(0,15)"></div>
      <div class="field"><label>الجنسية</label>
        <input id="usNat" value="${u ? esc(u.nationality || "المملكة العربية السعودية") : "المملكة العربية السعودية"}"></div>
      <div class="field"><label>الجنس</label>
        <select id="usGender">
          <option value="ذكر"${!u || u.gender !== "أنثى" ? " selected" : ""}>ذكر</option>
          <option value="أنثى"${u && u.gender === "أنثى" ? " selected" : ""}>أنثى</option>
        </select></div>
      <div class="field"><label>الدور <span class="req">*</span></label>
        <select id="usRole" onchange="window.roleChanged(this)">${assignableRoles().map(r =>
          `<option value="${r.k}"${r.k === role ? " selected" : ""}>${esc(r.h)}</option>`).join("")}
        ${role === "supervisor" ? `<option value="supervisor" selected>مشرف / ة (دور قديم)</option>` : ""}</select></div>
      ${permsField(u, role !== "teacher")}
      <!-- أجر المشرف: المسيّرات تقرأ salary من ملفّه، ولم يكن له حقلٌ
           يكتبه — فيُحسب مسيّره صفراً وإن عمل الشهر كلّه. -->
      ${isMgrRole(role) || role === "admin" ? `
      <div class="field"><label>نوع الأجر</label>
        <select id="usPayType" onchange="window.teacherPayType('us')">
          ${[["monthly", "راتب شهري"], ["daily", "أجر يومي"],
             ["hourly", "أجر بالساعة"], ["volunteer", "متطوّع — بلا أجر"]]
            .map(x => `<option value="${x[0]}"${
              ((u && u.payType) || "monthly") === x[0] ? " selected" : ""}>${x[1]}</option>`).join("")}
        </select></div>
      <div class="field" id="us_payWrap"${
        u && u.payType === "volunteer" ? ' style="display:none"' : ""}>
        <label>المبلغ</label>
        <input id="usPay" type="number" min="0" step="50" dir="ltr"
          value="${u ? esc(u.salary || u.wage || u.hourRate || "") : ""}"></div>` : ""}

      ${role === "parent" ? `
      <!-- وليُّ الأمر لا يشرف على منشأة: يتابع أبناءه. وحقلُ «أماكن الإشراف»
           كان يظهر له بلا معنى، ولا يجد موضعاً يربط به أولاده. -->
      <div class="field full"><label>الأبناء المتابَعون <span class="req">*</span></label>
        <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px">
          <select class="mig-dest" onchange="window.usKidFilter(this.value)" style="max-width:170px">
            <option value="">كلّ الحلقات</option>
            ${(cur("circles") || []).filter(c => c.status !== "متوقف").map(c =>
              `<option value="${esc(c.id)}">${esc(c.name)}</option>`).join("")}
          </select>
          <input class="mig-dest" placeholder="ابحث بالاسم" style="max-width:150px"
            oninput="window.usKidSearch(this.value)">
          <span id="usKidCount" class="muted"
            style="font-size:12px;align-self:center;margin-inline-start:auto"></span>
        </div>
        <div class="pick-box" id="usKidBox"></div>
        <div class="hint">اختر ابناً أو أكثر. ومن لم تختره لن يظهر لوليّه.</div>
      </div>

      ${Array.isArray(u && u.kidsRequested) && u.kidsRequested.length ? `
      <div class="field full">
        ${noteCard("طلب عند التسجيل: " +
          u.kidsRequested.map(k => esc(k.name) + (k.idNo ? " · " + esc(k.idNo) : "")).join(" · "))}
      </div>` : ""}
      ` : `
      <div class="field full"><label>أماكن الإشراف</label>
        ${facPickField("usFacs", u)}
        <div class="hint">اختر منشأة أو أكثر. ترك الاختيار فارغاً يعني <strong>كل المنشآت</strong>.</div>
      </div>`}
      <div class="field full">
        <div class="toggle-row"><div class="tr-text"><strong>الحساب فعّال</strong>
          <small>عند الإيقاف لا يستطيع المستخدم تسجيل الدخول</small></div>
          <label class="switch"><input type="checkbox" id="usActive" ${!u || u.active !== false ? "checked" : ""}>
            <span class="slider"></span></label></div>
      </div>
     </div>`,
    `<button class="btn btn-primary" data-action="user-save">${u ? "حفظ" : "إضافة"}</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);

  /* المنتقي يُرسم بعد فتح النافذة: عناصره غير موجودةٍ قبلها */
  setTimeout(function () { if (typeof usKidRender === "function") usKidRender(); }, 0);
};

window.userSave = function () {
  /* منح owner من نموذج المستخدم يمرّ من هنا: يُحرس كما يُحرس الاعتماد */
  if (val("#usRole") === "owner" && !isTopAdmin()) {
    showToast("دور المالك لا يمنحه إلا مالكٌ قائم", "warn"); return;
  }

  const name = (val("#usName") || "").trim();
  if (!name) { showToast("الاسم مطلوب", "warn"); return; }
  const uid = (val("#usUser") || "").replace(/[^0-9]/g, "");
  if (!uid) { showToast("رقم الهوية مطلوب (أرقام فقط)", "warn"); return; }
  if (uid.length !== 10) { showToast("رقم الهوية يجب أن يكون 10 أرقام", "warn"); return; }
  let email = (val("#usEmail") || "").trim().replace(/\.com$/i, "");
  if (email && email.indexOf("@") < 1) { showToast("البريد الإلكتروني غير صحيح", "warn"); return; }
  if (email) email += ".com";

  if (!Array.isArray(DB.users)) DB.users = [];
  const id = val("#usId");
  const el = x => document.getElementById(x);
  const scopeIds = facPickValue("usFacs");
  /* أول مسجد وأول مجمع يُكتبان في الحقلين المفردين للتوافق الخلفي */
  const firstMq = scopeIds.filter(k => k.indexOf("mosque:") === 0)[0];
  const firstCx = scopeIds.filter(k => k.indexOf("complex:") === 0)[0];
  /* =======================================================================
     القائمتان الجمعيّتان: بهما وحدَهما يعرف الخادمُ نطاقَ الحساب كاملاً
     -----------------------------------------------------------------------
     كان يُكتب scopeIds (وهو ما يقرؤه المتصفّح) والحقلان المفردان وحدَهما.
     و firestore.rules لا تقرأ scopeIds أصلاً: نطاقُها
     mosqueIds + complexIds + الحقلان المفردان. فمن أُسنِد إلى مسجدين
     يرى الاثنين ولا يكتب إلا في الأوّل — يفتح الطالبَ ويحرّره ثمّ يُردّ
     عند الحفظ. تُكتب القائمتان الآن، فيتطابق ما يراه بما يكتبه.
     ولا توسيعَ في الصلاحية: هي عينُ ما أُسنِد في scopeIds لا غير.
     ======================================================================= */
  const mosqueIds  = scopeIds.filter(k => k.indexOf("mosque:")  === 0).map(k => k.split(":")[1]);
  const complexIds = scopeIds.filter(k => k.indexOf("complex:") === 0).map(k => k.split(":")[1]);
  const u0 = id ? DB.users.find(x => String(x.id) === String(id)) : null;

  /* لا يُمنح دورٌ أعلى من دور المانح — وإلّا أنشأ مديرُ المجمّع مديرَ
     نظامٍ ودخل به. حارسٌ في الواجهة، ومثلُه في قواعد Firestore. */
  const wantRole = val("#usRole") || "mosqueManager";
  if (!canGrantRole(wantRole)) {
    showToast("لا تملك منح هذا الدور", "warn"); return;
  }
  const data = {
    name, username: uid, email,
    loginEmail: email || (uid + "@mirath.id"),   /* الدخول برقم الهوية */
    phone: (val("#usPhone") || "").replace(/[^0-9]/g, ""), nationality: val("#usNat") || "المملكة العربية السعودية",
    gender: val("#usGender") || "ذكر", role: val("#usRole") || "mosqueManager",

    /* أبناءُ وليّ الأمر: يُكتبان معاً — المتعدّد للاستعمال، والمفرد
       للتوافق مع ما بُني قبل تعدّد الأبناء. */
    ...((val("#usRole") || "") === "parent" ? {
      studentIds: USK.picked.slice(),
      studentId: USK.picked.length === 1 ? USK.picked[0] : ""
    } : {}),
    /* أجر المشرف — payFields تكتبه في حقله وحده */
    ...(document.getElementById("usPayType")
      ? payFields(val("#usPayType", "monthly"), val("#usPay")) : {}),
    photo: photoVal("us_photo", u0 ? (u0.photo || "") : ""),
    perms: (function () {
      const pv = permsValue();
      /* الحقل يظهر للمعلم وحده، فلا تُمسّ صلاحيات غيره */
      return pv || (u0 && u0.perms) || {};
    })(),
    scopeIds: scopeIds,
    mosqueId:  firstMq ? firstMq.split(":")[1] : "",
    complexId: firstCx ? firstCx.split(":")[1] : "",
    mosqueIds: mosqueIds, complexIds: complexIds,
    active: !!(el("usActive") && el("usActive").checked)
  };

  /* ---- تعديل: لا مساس بحساب الدخول ---- */
  if (id) {
    const u = DB.users.find(x => String(x.id) === String(id));
    if (u) { Object.assign(u, data); persistSet("users", u); syncTeacherRecord(u); syncStudentRecord(u); }
    photoReset("us_photo");
    showToast("حُفظت البيانات", "success");
    closeModal(); mount();
    return;
  }

  /* ---- إضافة: يُنشأ حساب دخول حقيقي، ومعرّف المستند = uid ---- */
  if (DB.users.some(x => String(x.username) === uid)) { showToast("رقم الهوية مسجَّل بالفعل", "warn"); return; }
  const dup = DB.users.some(x => data.email && String(x.email).toLowerCase() === data.email.toLowerCase());
  if (dup) { showToast("البريد الإلكتروني مستخدم بالفعل", "warn"); return; }

  const btn = document.querySelector('[data-action="user-save"]');
  if (btn) { btn.disabled = true; btn.textContent = "جارٍ إنشاء الحساب…"; }

  createAuthUser({ email: data.email, username: uid })
    .then(res => {
      const u = Object.assign({ id: res.uid, uid: res.uid, loginEmail: res.loginEmail, createdAt: Date.now() }, data);
      DB.users.push(u); persistSet("users", u);
      syncTeacherRecord(u);   /* يظهر فوراً في صفحة المعلمين وقوائم الحلقات */
      syncStudentRecord(u);   /* وكذلك الطالب في صفحة الطلاب */
      closeModal(); mount();
      showToast("أُضيف " + (USER_ROLES.find(r => r.k === data.role) || {}).h, "success");
      showCredentials(res, data.name);
    })
    .catch(err => {
      console.warn("createAuthUser:", err);
      showToast(authErrMsg(err), "warn");
      if (btn) { btn.disabled = false; btn.textContent = "إضافة"; }
    });
};

/* =========================================================================
   المستخدمون والحسابات
   -------------------------------------------------------------------------
   الصفحة كانت بلا دالة أصلاً: admin/users.html موجودة، ولا مفتاح لها في
   PAGES ولا دالة تبنيها — فتُفتح فارغة. وكانت تُحمّل admin/users.js وهو
   نسخة قديمة كاملة من app.js (٦٣٥ كيلوبايت) تُحمَّل بعده فتلغي دواله.

   لا شيء جديد هنا: personTable و USER_ROLES و userForm و createAuthUser
   كلها قائمة وتعمل — ينقص الجدول الذي يجمعها.
   ========================================================================= */
/* =========================================================================
   بطاقة المستخدم — عرض كامل وتعديل
   -------------------------------------------------------------------------
   صفوف الجدول كانت بلا نقر: البيانات تُعرض مبتورة في أعمدة، ومن أراد
   البقية أو التعديل لم يجد له سبيلاً. userForm للتعديل موجودة أصلاً،
   وينقص عرضٌ يجمع كل الحقول قبلها.
   ========================================================================= */
/* =========================================================================
   بطاقة الحساب في الشريط العلوي
   -------------------------------------------------------------------------
   كانت عرضاً جامداً: اسم وبريد ودور بلا نقر، فمن أراد ملفّه لم يجد سبيلاً.
   تُربط هنا لا في ملفات HTML الستة عشر، فالربط واحد يكفيها كلّها.
   ========================================================================= */
window.myProfile = function () {
  const u = (STATE && STATE.user) || {};
  const uid = String(u.uid || u.id || "");
  const mail = String(u.email || "").toLowerCase();

  /* الحساب قد يُسجَّل بمعرّف Auth أو بمعرّف المستند — يُلتمس بالاثنين ثم بالبريد */
  const rec = (cur("users") || []).find(x =>
    String(x.uid || "") === uid || String(x.id) === uid ||
    (mail && String(x.email || "").toLowerCase() === mail));

  if (rec) { window.userView(rec.id); return; }

  /* لا مستند: تُعرض بيانات الجلسة بدل رسالة خطأ لا تفيد */
  /* الدور بمستواه: «مدير المسجد» لا «مدير» — الفرق بينهما صلاحيّات */
  const role = roleTitle(u) || (USER_ROLES.find(r => r.k === u.role) || {}).h || u.role || "—";
  openModal(u.name || "حسابي", role,
    `<div class="uv">
      <div class="uv-top">
        <span class="uv-avatar">${esc((u.name || "؟").trim()[0] || "؟")}</span>
        <div class="uv-id"><strong>${esc(u.name || "—")}</strong>
        <span class="pt-badge on">فعال</span></div>
      </div>
      <div class="uv-body">
        <div class="uv-row"><span>الدور</span><strong>${esc(role)}</strong></div>
        ${u.email ? `<div class="uv-row"><span>البريد</span>
          <strong dir="ltr">${esc(u.email)}</strong></div>` : ""}
      </div>
      <div class="note-card" style="margin-top:12px"><p>حسابك غير مرتبط بسجل في
      «المستخدمون والحسابات»، فلا تظهر بياناته كاملة. أبلغ الإدارة لربطه.</p></div>
    </div>`,
    '<button class="btn btn-ghost" data-action="close-modal">إغلاق</button>');
};

/* =========================================================================
   صورة الحساب في الشريط العلوي
   -------------------------------------------------------------------------
   applyUserToTopbar في auth.js تضع الحرف الأول من الاسم فقط:
     avEl.textContent = initials(ctx.name);
   ولا تقرأ حقل photo أصلاً، فالصورة تُحفظ ولا تظهر. وهي تعمل قبل تحميل
   المستخدمين من قاعدة البيانات، فلا سبيل لها إلى الصورة وقتها.

   تُقرأ هنا بعد اكتمال التحميل، وتُعاد عند كل رسم لأن مغادرة الصفحة
   قد تُعيد بناء الشريط.
   ========================================================================= */
window.refreshTopbarPhoto = function () {
  const av = document.querySelector(".user-chip .avatar");
  if (!av) return;

  const u = (STATE && STATE.user) || {};
  const uid = String(u.uid || u.id || "");
  const mail = String(u.email || "").toLowerCase();

  const rec = (cur("users") || []).find(x =>
    String(x.uid || "") === uid || String(x.id) === uid ||
    (mail && String(x.email || "").toLowerCase() === mail));

  const photo = (rec && rec.photo) || u.photo || "";

  if (!photo) {
    /* لا صورة: يبقى الحرف الأول كما وضعته auth.js */
    if (av.querySelector("img")) {
      av.innerHTML = "";
      av.textContent = (typeof initials === "function")
        ? initials(u.name || "") : String(u.name || "؟").trim()[0] || "؟";
    }
    return;
  }

  const img = av.querySelector("img");
  if (img) { if (img.getAttribute("src") !== photo) img.setAttribute("src", photo); return; }

  av.textContent = "";
  const el = document.createElement("img");
  el.src = photo;
  el.alt = "";
  /* صورة تالفة أو رابط منقطع: يعود الحرف الأول بدل مربّع فارغ */
  el.onerror = function () {
    av.innerHTML = "";
    av.textContent = (typeof initials === "function")
      ? initials(u.name || "") : String(u.name || "؟").trim()[0] || "؟";
  };
  av.appendChild(el);
};

/* بطاقة الشريط تُرسم في HTML قبل تحميل الحساب، فتُربط بعد الإقلاع */
(function bindUserChip() {
  const tries = { n: 0 };
  const t = setInterval(function () {
    const chip = document.querySelector(".user-chip");
    if (chip && !chip.dataset.bound) {
      chip.dataset.bound = "1";
      chip.setAttribute("role", "button");
      chip.setAttribute("tabindex", "0");
      chip.setAttribute("title", "ملفي الشخصي");
      chip.addEventListener("click", function () { window.myProfile(); });
      window.refreshTopbarPhoto();
      chip.addEventListener("keydown", function (e) {
        if (e.key === "Enter" || e.key === " ") { e.preventDefault(); window.myProfile(); }
      });
      clearInterval(t);
      return;
    }
    if (++tries.n > 60) clearInterval(t);   /* ثلاثون ثانية ثم يتوقف */
  }, 500);
})();

/* =========================================================================
   اعتماد الحساب من بطاقته
   -------------------------------------------------------------------------
   كان الاعتماد في شاشة الطلبات وحدها، وهي تشترط الحقل selfSignup:
     .filter(u => u && u.selfSignup && u.active === false)
   فالحساب الذي تُنشئه الإدارة لا يحمله، ولا يظهر في الطلبات، ولا سبيل
   لاعتماده — يبقى «بانتظار الاعتماد» أبداً ولا يستطيع صاحبه الدخول.
   ========================================================================= */
/* ترجيحُ طالبٍ لاسمٍ كتبه وليُّ الأمر: رقمُ الهوية يحسم، ثمّ المطابقةُ
   التامّة للاسم، ثمّ تطابقُ الاسم الأوّل والأخير. */
function matchKid(k) {
  if (!k || !k.name) return null;
  const list = (cur("students") || []).filter(x => x && x.status !== "متوقف");

  if (k.idNo) {
    const byId = list.find(x => String(x.idNo || "") === String(k.idNo));
    if (byId) return byId;
  }

  const norm = t => String(t || "").replace(/\s+/g, " ").trim();
  const exact = list.find(x => norm(x.name) === norm(k.name));
  if (exact) return exact;

  /* الأوّل والأخير: «محمد أحمد السالم» يطابق «محمد السالم» */
  const p = norm(k.name).split(" ").filter(Boolean);
  if (p.length >= 2) {
    const first = p[0], last = p[p.length - 1];
    const near = list.filter(x => {
      const q = norm(x.name).split(" ").filter(Boolean);
      return q.length >= 2 && q[0] === first && q[q.length - 1] === last;
    });
    /* واحدٌ فقط يُرجَّح: التعدّدُ التباسٌ تحسمه الإدارة */
    if (near.length === 1) return near[0];
  }
  return null;
}

/* =========================================================================
   منتقي أبناء وليّ الأمر
   -------------------------------------------------------------------------
   كالمنتقي في الجوائز: بحثٌ وتصفيةٌ لأن القائمة قد تبلغ مئات، والمختارُ
   يبقى ظاهراً وإن صُفّيت القائمة عنه — فمن اختار ابناً ثمّ بدّل الحلقة
   لا يفقد اختياره بلا أثر.
   ========================================================================= */
const USK = { q: "", circle: "", picked: [] };

window.usKidFilter = function (v) { USK.circle = String(v || ""); usKidRender(); };
window.usKidSearch = function (v) { USK.q = String(v || ""); usKidRender(); };

window.usKidPick = function (id, on) {
  const i = USK.picked.indexOf(String(id));
  if (on && i === -1) USK.picked.push(String(id));
  if (!on && i > -1) USK.picked.splice(i, 1);
  usKidRender();
};

function usKidList() {
  let l = (cur("students") || []).filter(x => x && x.status !== "متوقف");
  if (USK.circle) l = l.filter(x => String(x.circleId) === String(USK.circle));
  if (USK.q) l = l.filter(x => String(x.name || "").indexOf(USK.q) > -1);
  return l;
}

function usKidRender() {
  const box = document.getElementById("usKidBox");
  const cnt = document.getElementById("usKidCount");
  if (!box) return;

  const list = usKidList();
  const shown = new Set(list.map(x => String(x.id)));

  /* المختارون خارج التصفية يُلحقون آخراً موسومين */
  const extra = USK.picked
    .filter(id => !shown.has(id))
    .map(id => (cur("students") || []).find(x => String(x.id) === String(id)))
    .filter(Boolean);

  box.innerHTML = (list.concat(extra).map(st => {
    const on = USK.picked.indexOf(String(st.id)) > -1;
    const out = !shown.has(String(st.id));
    return `<label class="pick${on ? " on" : ""}${out ? " out" : ""}"
        title="${out ? "خارج التصفية الحالية" : esc(st.circle || "")}">
        <input type="checkbox"${on ? " checked" : ""}
          onchange="window.usKidPick('${jsAttr(st.id)}',this.checked)">
        <span>${esc(st.name || "—")}</span></label>`;
  }).join("")) || '<span class="muted">لا طلاب</span>';

  if (cnt) {
    cnt.textContent = USK.picked.length
      ? toArabicDigits(USK.picked.length) + " ابناً"
      : "لم يُختر أحد";
  }
}

function canApproveUsers() {
  const r = ((STATE && STATE.user) || {}).role || "";
  return r === "admin" || r === "owner" || isMgrRole(r);
}

window.userApprove = function (id) {
  if (!canApproveUsers()) { showToast("الاعتماد للإدارة", "warn"); return; }
  const u = (DB.users || []).find(x => String(x.id) === String(id));
  if (!u) { showToast("لم يُعثر على الحساب", "warn"); return; }

  const roles = assignableRoles().map(r =>
    `<option value="${esc(r.k)}"${(u.requestedRole || u.role) === r.k ? " selected" : ""}>${esc(r.h)}</option>`).join("");

  /* أبناءُ وليّ الأمر المطلوب ربطُهم: يُقترح لكلٍّ طالبٌ يطابقه، وتُراجع
     الإدارة. وبلا هذا الربط يدخل الحسابُ ولا يجد شيئاً. */
  const kidsReq = Array.isArray(u.kidsRequested) ? u.kidsRequested : [];
  const kidsBlock = kidsReq.length ? `
    <div class="field full" style="margin-top:6px">
      <div class="fld-sep">أبناؤه — اربط كلّاً بطالبه</div></div>
    ${kidsReq.map((k, i) => {
      const guess = matchKid(k);
      return `<div class="field full">
        <label>${esc(k.name)}${k.idNo ? " · " + esc(k.idNo) : ""}</label>
        <select id="ua_kid${i}">
          <option value="">— لم يُربط —</option>
          ${(cur("students") || []).filter(x => x.status !== "متوقف").map(x =>
            `<option value="${esc(x.id)}"${
              guess && String(guess.id) === String(x.id) ? " selected" : ""}>${
              esc(x.name)}${x.circle ? " · " + esc(x.circle) : ""}</option>`).join("")}
        </select>
        ${guess ? `<small style="font-size:11px;color:var(--brand-dark)">
          رُجّح: ${esc(guess.name)}${guess.circle ? " · " + esc(guess.circle) : ""}</small>`
          : `<small style="font-size:11px;color:#a8302f">
          لم يُعثر على مطابقٍ — اختر يدوياً</small>`}
      </div>`;
    }).join("")}` : "";

  openModal("اعتماد الحساب", u.name || "",
    `<div class="form-grid">
       <div class="field full"><label>الدور</label>
         <select id="ua_role">${roles}</select></div>
       ${kidsBlock}
     </div>
     ${noteCard(`بعد الاعتماد يصير الحساب فعّالاً ويستطيع
       <strong>${esc(u.name || "صاحبه")}</strong> الدخول فوراً بالدور المختار.` +
       (kidsReq.length ? `<br>ومن لم تربطه لن يراه.` : ""))}`,
    `<button class="btn btn-primary" onclick="window.userApproveDo('${jsAttr(id)}')">اعتماد</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
};

window.userApproveDo = function (id) {
  const u = (DB.users || []).find(x => String(x.id) === String(id));
  if (!u) return;

  const wanted = val("#ua_role") || u.requestedRole || u.role || "student";

  /* الحارس في الدالة لا في القائمة: ترشيح الخيارات لا يمنع نداءها،
     ومنح owner تجاوزٌ لكلّ حصرٍ في النظام. */
  if (wanted === "owner" && !isTopAdmin()) {
    showToast("دور المالك لا يمنحه إلا مالكٌ قائم", "warn"); return;
  }
  if (!canEditUser(u)) {
    showToast("حساب المالك لا يُعدَّل إلا من مالك", "warn"); return;
  }

  /* منح دور المالك حركةٌ مصيرية: تُرصد بنصٍّ صريح لا كتعديل حقلٍ عاديّ */
  if (wanted === "owner" && u.role !== "owner") {
    try {
      const me = (STATE && STATE.user) || {};
      const rec = {
        id: "lg" + Date.now() + "-own",
        ts: Date.now(), act: "update", coll: "users", collAr: "المستخدمون",
        docId: String(u.id), subject: u.name || "",
        by: me.name || me.email || "—", role: logRoleAr(me.role),
        changes: [{ k: "role", h: "الدور", from: u.role || "—", to: "مالك النظام" }],
        text: "منح " + (logRoleAr(me.role) || "") + " (" + (me.name || "—") +
              ") دورَ مالك النظام لـ(" + (u.name || "") + ")"
      };
      if (!Array.isArray(DB.auditLog)) DB.auditLog = [];
      DB.auditLog.push(rec);
      const db = typeof FDB === "function" ? FDB() : null;
      if (db) db.collection("auditLog").doc(rec.id).set(rec).catch(() => {});
    } catch (e) {}
  }

  /* ربطُ الأبناء عند الاعتماد: بدونه يدخل وليُّ الأمر ولا يجد شيئاً */
  if (Array.isArray(u.kidsRequested) && u.kidsRequested.length) {
    const picked = [];
    u.kidsRequested.forEach((k, i) => {
      const sel = val("#ua_kid" + i);
      if (sel) picked.push(String(sel));
    });
    u.studentIds = picked;
    if (picked.length === 1) u.studentId = picked[0];
    u.kidsLinkedAt = Date.now();

    if (!picked.length) {
      showToast("لم تُربط أبناؤه — سيدخل ولا يجد شيئاً", "warn");
    }
  }

  u.role = wanted;
  u.active = true;
  u.pending = false;
  u.approvedAt = Date.now();
  u.approvedBy = ((STATE && STATE.user) || {}).email || "";
  delete u.selfSignup;          /* يخرج من قائمة الطلبات بعد البتّ */
  delete u.requestedRole;
  persistSet("users", u);

  /* سجلّا المعلّم والطالب يُنشآن هنا كما في مسار الطلبات، وإلا صار
     الحساب فعّالاً بلا سجلٍّ يربطه بحلقة أو خطة. */
  try { if (typeof syncTeacherRecord === "function") syncTeacherRecord(u); } catch (e) {}
  try { if (typeof syncStudentRecord === "function") syncStudentRecord(u); } catch (e) {}

  closeModal();
  showToast("اعتُمد حساب " + (u.name || "") + " — يستطيع الدخول الآن", "success");
  mount();
};

window.userReject = function (id) {
  if (!canApproveUsers()) return;
  const u = (DB.users || []).find(x => String(x.id) === String(id));
  if (!u) return;

  openModal("رفض الحساب", u.name || "",
    noteCard(`سيبقى حساب <strong>${esc(u.name || "")}</strong> موقوفاً فلا يستطيع الدخول.
      لا يُحذف، ويمكن اعتماده لاحقاً.`),
    `<button class="btn btn-danger" onclick="window.userRejectDo('${jsAttr(id)}')">رفض</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
};

window.userRejectDo = function (id) {
  const u = (DB.users || []).find(x => String(x.id) === String(id));
  if (!u) return;
  u.active = false;
  u.pending = false;
  u.rejectedAt = Date.now();
  delete u.selfSignup;
  persistSet("users", u);
  closeModal();
  showToast("رُفض الحساب", "info");
  mount();
};

window.userView = function (id) {
  const u = (cur("users") || []).find(x => String(x.id) === String(id));
  if (!u) { showToast("لم يُعثر على المستخدم", "warn"); return; }

  /* الدور بمستواه: «مدير المسجد» لا «مدير» — الفرق بينهما صلاحيّات */
  const role = roleTitle(u) || (USER_ROLES.find(r => r.k === u.role) || {}).h || u.role || "—";
  const login = u.email || u.loginEmail ||
    (u.username ? u.username + "@mirath.id" : "");

  /* أسماء المنشآت من معرّفاتها — المعرّف وحده لا يقول شيئاً للقارئ */
  const facName = fid => {
    const f = cur("complexes").concat(cur("mosques"))
      .find(x => String(x.id) === String(fid));
    return f ? (f.name || "") : "";
  };

  const row = (label, val, dir) => val
    ? `<div class="uv-row"><span>${esc(label)}</span>
       <strong${dir ? ' dir="ltr"' : ""}>${esc(val)}</strong></div>`
    : "";

  const pending = u.pending || (u.active === false && !u.approvedAt);
  const active = u.active !== false;

  openModal(u.name || "المستخدم", role,
    `<div class="uv">
      <div class="uv-top">
        <span class="uv-avatar">${personAvatar(u)}</span>
        <div class="uv-id">
          <strong>${esc(u.name || "—")}</strong>
          <span class="pt-badge ${pending ? "off" : active ? "on" : "off"}">
            ${pending ? "بانتظار الاعتماد" : active ? "فعال" : "متوقف"}</span>
        </div>
      </div>

      <div class="uv-body">
        ${row("الدور", role)}
        ${row("بريد الدخول", login, 1)}
        ${row("رقم الهوية", u.username, 1)}
        ${row("الجوال", u.phone, 1)}
        ${row("الجنس", u.gender)}
        ${row("المجمع", facName(u.complexId))}
        ${row("المسجد", facName(u.mosqueId))}
        ${row("التصنيف", u.category)}
        ${row("تاريخ الإنشاء", u.createdAt
            ? new Date(u.createdAt).toLocaleDateString("ar-EG") : "")}
        ${row("اعتمده", u.approvedBy)}
        ${row("ملاحظات", u.note)}
      </div>

      ${login ? "" : `<div class="note-card" style="margin-top:12px">
        <p>لا بريد دخول لهذا الحساب، فلا يستطيع تسجيل الدخول. 
        أضِف بريداً أو رقم هوية من التعديل.</p></div>`}
    </div>`,

    `${pending && canApproveUsers() ? `<button class="btn btn-primary"
        onclick="window.userApprove('${jsAttr(u.id)}')">اعتماد الحساب</button>
       <button class="btn btn-danger" onclick="window.userReject('${jsAttr(u.id)}')">رفض</button>` : ""}
     <button class="btn btn-${pending ? 'ghost' : 'primary'}" onclick="window.userForm('${jsAttr(u.id)}')">
       تعديل البيانات</button>
     <button class="btn btn-ghost" data-action="close-modal">إغلاق</button>`);
};

function adminUsers() {
  const list = cur("users");

  const roleName = u => (USER_ROLES.find(r => r.k === u.role) || {}).h || (u.role || "—");

  /* بريد الدخول: الحقيقي إن وُجد، وإلا الاصطناعي من رقم الهوية */
  const loginOf = u => u.email || u.loginEmail ||
    (u.username ? u.username + "@mirath.id" : "");

  return personTable({
    list, title: "المستخدمون والحسابات", showCount: true,
    toolbar: "add", addLabel: "إضافة مستخدم", addAction: "modal-user",
    searchHint: "إبحث بالاسم أو البريد", actionsPanel: true,
    empty: "لا حسابات بعد. أضِف مستخدماً ليُنشأ له حساب دخول.",
    cols: [
      colPhoto(),
      /* الاسم زرّ يفتح البطاقة — أقرب ما تصل إليه يد القارئ */
      { h: "الاسم", cell: u => `<td class="pt-name"><button class="uv-link"
          onclick="window.userView('${jsAttr(u.id)}')">${esc(u.name || "—")}</button></td>` },
      colState(),
      { h: "الدور", cell: u => `<td>${esc(roleName(u))}</td>` },
      { h: "بريد الدخول", cell: u => {
          const m = loginOf(u);
          return `<td dir="ltr" style="font-size:12px">${m ? esc(m)
            : '<span class="muted">بلا حساب دخول</span>'}</td>`;
        } },
      { h: "رقم الهوية", cell: u => `<td dir="ltr" class="pt-num">${esc(u.username || "—")}</td>` },
      { h: "الحالة", cell: u => {
          /* الحساب المعلّق ينتظر اعتماد الإدارة، ولا يستطيع الدخول */
          if (u.pending || (u.active === false && !u.approvedAt))
            return '<td><span class="pt-badge off">بانتظار الاعتماد</span></td>';
          return `<td><span class="pt-badge on">معتمد</span></td>`;
        } },
      colPhone(),
      { h: "", cell: u => `<td class="pt-actions">
          <button class="row-btn" onclick="window.userView('${jsAttr(u.id)}')"
            title="عرض البيانات">${ic("eye", 15)}</button>
          <button class="row-btn" onclick="window.userForm('${jsAttr(u.id)}')"
            title="تعديل">${ic("pen", 15)}</button>
          ${(u.pending || (u.active === false && !u.approvedAt)) && canApproveUsers()
            ? `<button class="row-btn ok" onclick="window.userApprove('${jsAttr(u.id)}')"
                title="اعتماد الحساب">${ic("check", 15)}</button>` : ""}</td>` }
    ]
  });
}

function adminSupervisors() {
  const list = cur("users").filter(u => isMgrRole(u.role));
  return personTable({
    list, title: "المشرفين / ات", showCount: true,
    toolbar: "add", addLabel: "إضافة مشرف", addAction: "modal-user",
    searchHint: "إبحث عن مشرف", actionsPanel: true,
    empty: "المشرف هو مستخدم دوره «مشرف». أضِفه من صفحة المستخدمون والحسابات.",
    cols: [ colPhoto(), colName(), colState(),
      { h: "عدد الطلاب/ات", cell: p2 => `<td class="pt-num">${cur("students").filter(st => String(st.supervisorId) === String(p2.id)).length}</td>` },
      { h: "عدد الحلقات",  cell: p2 => `<td class="pt-num">${cur("circles").filter(c => String(c.supervisorId) === String(p2.id)).length}</td>` },
      { h: "الجنس", cell: p2 => `<td>${esc(p2.gender || "ذكر")}</td>` },
      colPhone()
    ]
  });
}

