const XS_PATH_COLS = [
  { k: "name",   h: "اسم المسار" },
  { k: "status", h: "الحالة" },
  { k: "owner",  h: "مالك الاختبار" },
  { k: "count",  h: "عدد الاختبارات" },
  { k: "num",    h: "عدد" }
];

const xsPaths = () => (cur("examPaths") || []);

window.xsSec = function (k) { XS_STATE.sec = k; XS_STATE.sel = {}; XCM.rows = null; XAU.rows = null; mount(); };
window.xsToggle = function (btn, id) {
  btn.classList.toggle("on");
  const on = btn.classList.contains("on");
  if (on) XS_STATE.sel[id] = true; else delete XS_STATE.sel[id];
  const tr = btn.closest("tr"); if (tr) tr.classList.toggle("sel", on);
};
window.xsToggleAll = function (btn) {
  const on = btn.classList.toggle("on");
  XS_STATE.sel = {};
  document.querySelectorAll("#xsBody tr[data-id]").forEach(tr => {
    const b = tr.querySelector(".pt-box");
    if (b) { b.classList.toggle("on", on); tr.classList.toggle("sel", on); }
    if (on) XS_STATE.sel[tr.dataset.id] = true;
  });
};
const xsSel = () => Object.keys(XS_STATE.sel);

/* ---- إضافة / تعديل مسار ---- */
window.xsPathForm = function (id) {
  const facs = cur("complexes").concat(cur("mosques"));
  const r = id ? xsPaths().find(x => String(x.id) === String(id)) : null;
  openModal(r ? "تعديل المسار" : "إضافة مسار", "",
    `<input type="hidden" id="xpId" value="${r ? esc(r.id) : ""}">
     <div class="form-grid">
      <div class="field full"><label>اسم المسار <span class="req">*</span></label>
        <input id="xpName" value="${r ? esc(r.name || "") : ""}" placeholder="مثال: الطلاب"></div>
      <div class="field"><label>مالك الاختبار</label>
        <select id="xpOwner">${facs.map(f => `<option value="${esc(f.name)}"${r && r.owner === f.name ? " selected" : ""}>${esc(f.name)}</option>`).join("")}</select></div>
      <div class="field"><label>عدد الاختبارات</label>
        <input type="number" id="xpCount" min="0" value="${r ? Number(r.count) || 0 : 1}"></div>
      <div class="field full"><label>الحالة</label>
        <select id="xpStatus">
          <option value="فعال"${!r || r.status === "فعال" ? " selected" : ""}>فعال</option>
          <option value="متوقف"${r && r.status === "متوقف" ? " selected" : ""}>متوقف</option>
        </select></div>
     </div>`,
    `<button class="btn btn-primary" data-action="xs-path-save">${r ? "حفظ" : "إضافة"}</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
};
window.xsPathSave = function () {
  const name = (val("#xpName") || "").trim();
  if (!name) { showToast("اسم المسار مطلوب", "warn"); return; }
  if (!Array.isArray(DB.examPaths)) DB.examPaths = [];
  const id = val("#xpId");
  const data = { name, owner: val("#xpOwner") || "—", count: Number(val("#xpCount")) || 0,
                 status: val("#xpStatus") || "فعال", num: "" };
  if (id) {
    const r = DB.examPaths.find(x => String(x.id) === String(id));
    if (r) { Object.assign(r, data); persistSet("examPaths", r); }
    showToast("حُفظ المسار", "success");
  } else {
    const r = Object.assign({ id: "xp" + Date.now() }, data);
    DB.examPaths.push(r); persistSet("examPaths", r);
    showToast("أُضيف المسار", "success");
  }
  closeModal(); mount();
};
window.xsPathEdit = function () {
  const ids = xsSel();
  if (ids.length !== 1) { showToast("حدّد مساراً واحداً للتعديل", "warn"); return; }
  window.xsPathForm(ids[0]);
};
window.xsPathDelete = function () {
  const ids = xsSel();
  if (!ids.length) { showToast("حدّد مساراً واحداً على الأقل", "warn"); return; }
  openModal("تأكيد الحذف", "",
    noteCard(`سيتم حذف <strong>${ids.length}</strong> مسار نهائياً.`),
    `<button class="btn btn-danger" data-action="xs-path-del-do">حذف نهائي</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
};
window.xsPathDeleteDo = function () {
  const ids = xsSel();
  ids.forEach(id => {
    const i = (DB.examPaths || []).findIndex(x => String(x.id) === String(id));
    if (i > -1) { DB.examPaths.splice(i, 1); persistDelete("examPaths", id); }
  });
  XS_STATE.sel = {}; closeModal();
  showToast("حُذف " + ids.length + " مسار", "success"); mount();
};
window.xsPathStatus = function (to) {
  const ids = xsSel();
  if (!ids.length) { showToast("حدّد مساراً واحداً على الأقل", "warn"); return; }
  ids.forEach(id => {
    const r = (DB.examPaths || []).find(x => String(x.id) === String(id));
    if (r) { r.status = to; persistSet("examPaths", r); }
  });
  XS_STATE.sel = {};
  showToast((to === "فعال" ? "فُعِّل " : "أُوقف ") + ids.length + " مسار", "success"); mount();
};

/* ---- حفظ إعداد عام ---- */
window.xsSaveOpt = function (key, v) {
  if (!DB.settings) DB.settings = {};
  DB.settings[key] = v;
  persistSet("settings", { id: "exams", ...DB.settings });
  showToast("حُفظ الإعداد", "success");
};

