  const D='<svg viewBox="0 0 24 24" width="19" height="19" fill="currentColor"><path d="M9.4 3h5.2c.5 0 .9.4.9.9V5h4.1c.5 0 .9.4.9.9s-.4.9-.9.9h-.9v12.4c0 1-.8 1.8-1.8 1.8H7.1c-1 0-1.8-.8-1.8-1.8V6.8h-.9c-.5 0-.9-.4-.9-.9S3.9 5 4.4 5h4.1V3.9c0-.5.4-.9.9-.9z"/></svg>';
