  const R='<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="12" cy="12" r="9"/><path d="M10.2 8.3l6 3.7-6 3.7z" fill="currentColor" stroke="none"/></svg>';

