/* =========================================================================
   لوحة «مشرفي الاختبارات»
   ========================================================================= */
const XSUP = { q: "", chosen: {} };

function xsupList() {
  const base = (cur("examSupervisors") || []);
  const q = XSUP.q;
  return q ? base.filter(x => String(x.name || "").indexOf(q) > -1) : base;
}
function xsupLoad() {
  const saved = ((DB.settings || {}).examSupervisorIds) || [];
  XSUP.chosen = {};
  saved.forEach(id => { XSUP.chosen[id] = true; });
}
function xsupPersist() {
  if (!DB.settings) DB.settings = {};
  DB.settings.examSupervisorIds = Object.keys(XSUP.chosen);
  persistSet("settings", Object.assign({ id: "exams" }, DB.settings));
}

window.xsupSearch = function (v) { XSUP.q = String(v || "").trim(); mount(); };
window.xsupPick = function (id) {
  if (XSUP.chosen[id]) delete XSUP.chosen[id]; else XSUP.chosen[id] = true;
  xsupPersist();
  const n = Object.keys(XSUP.chosen).length;
  showToast(XSUP.chosen[id] ? "أُضيف للمشرفين المعتمدين" : "أُلغي الاعتماد", "success");
  mount();
};

/* إضافة مشرف — إمّا من المستخدمين الموجودين أو بإدخال يدوي */
window.xsupForm = function (id) {
  const r = id ? (cur("examSupervisors") || []).find(x => String(x.id) === String(id)) : null;
  const pool = (cur("users") || []).concat(cur("teachers") || []);
  openModal(r ? "تعديل بيانات المشرف" : "إضافة مشرف جديد", "",
    `<input type="hidden" id="xsupId" value="${r ? esc(r.id) : ""}">
     ${!r && pool.length ? `<div class="field full"><label>اختر من المستخدمين</label>
       <select id="xsupPool" onchange="window.xsupFill(this.value)">
         <option value="">— إدخال يدوي —</option>
         ${pool.map(u => `<option value="${u.id}|${esc(u.name || "")}|${esc(u.username || u.email || "")}|${esc(u.phone || "")}|${esc(u.nationality || "")}">${esc(u.name || "—")}</option>`).join("")}
       </select></div>` : ""}
     <div class="form-grid">
      <div class="field full"><label>الاسم <span class="req">*</span></label>
        <input id="xsupName" value="${r ? esc(r.name || "") : ""}"></div>
      <div class="field"><label>اسم المستخدم</label>
        <input id="xsupUser" value="${r ? esc(r.username || "") : ""}" dir="ltr"></div>
      <div class="field"><label>رقم الجوال</label>
        <input id="xsupPhone" value="${r ? esc(r.phone || "") : ""}" dir="ltr"></div>
      <div class="field"><label>الجنسية</label>
        <input id="xsupNat" value="${r ? esc(r.nationality || "المملكة العربية السعودية") : "المملكة العربية السعودية"}"></div>
      <div class="field"><label>الحالة</label>
        <select id="xsupStatus">
          <option value="فعال"${!r || r.status !== "متوقف" ? " selected" : ""}>فعال</option>
          <option value="متوقف"${r && r.status === "متوقف" ? " selected" : ""}>متوقف</option>
        </select></div>
     </div>`,
    `<button class="btn btn-primary" data-action="xsup-save">${r ? "حفظ" : "إضافة"}</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
};
window.xsupFill = function (v) {
  const p2 = String(v || "").split("|");
  if (p2.length < 5) return;
  const set = (id, val2) => { const el = document.getElementById(id); if (el) el.value = val2 || ""; };
  set("xsupName", p2[1]); set("xsupUser", p2[2]); set("xsupPhone", p2[3]);
  set("xsupNat", p2[4] || "المملكة العربية السعودية");
};
window.xsupSave = function () {
  const name = (val("#xsupName") || "").trim();
  if (!name) { showToast("الاسم مطلوب", "warn"); return; }
  if (!Array.isArray(DB.examSupervisors)) DB.examSupervisors = [];
  const id = val("#xsupId");
  const data = { name, username: val("#xsupUser") || "—", phone: val("#xsupPhone") || "—",
                 nationality: val("#xsupNat") || "المملكة العربية السعودية",
                 status: val("#xsupStatus") || "فعال" };
  if (id) {
    const r = DB.examSupervisors.find(x => String(x.id) === String(id));
    if (r) { Object.assign(r, data); persistSet("examSupervisors", r); }
    showToast("حُفظت البيانات", "success");
  } else {
    const r = Object.assign({ id: "sv" + Date.now() }, data);
    DB.examSupervisors.push(r); persistSet("examSupervisors", r);
    showToast("أُضيف المشرف", "success");
  }
  closeModal(); mount();
};
window.xsupDel = function (id) {
  const i = (DB.examSupervisors || []).findIndex(x => String(x.id) === String(id));
  if (i > -1) { DB.examSupervisors.splice(i, 1); persistDelete("examSupervisors", id); }
  delete XSUP.chosen[id]; xsupPersist();
  showToast("حُذف المشرف", "success"); mount();
};

