/* =========================================================================
   نقل الحلقات — تنقل الحلقة بكامل طلابها إلى منشأة أخرى
   ========================================================================= */
const MVC = { fromFac: "", toFac: "", q: "", sel: {} };

function mvcCircles() {
  if (!MVC.fromFac) return [];
  const list = mvsCircles(MVC.fromFac);
  const q = MVC.q;
  return q ? list.filter(c => String(c.name || "").indexOf(q) > -1) : list;
}
function mvcStudentsOf(cids) {
  return cur("students").filter(x => cids.indexOf(String(x.circleId)) > -1);
}

window.mvcPick = function (k, v) {
  MVC[k] = v;
  if (k === "fromFac") { MVC.sel = {}; MVC.q = ""; }
  mount();
};
window.mvcSearch = function (v) { MVC.q = String(v || "").trim(); mount(); };
window.mvcToggle = function (id) {
  if (MVC.sel[id]) delete MVC.sel[id]; else MVC.sel[id] = true;
  mount();
};
window.mvcAll = function () {
  const list = mvcCircles();
  const on = Object.keys(MVC.sel).length < list.length;
  MVC.sel = {};
  if (on) list.forEach(c => { MVC.sel[c.id] = true; });
  mount();
};
const mvcSel = () => Object.keys(MVC.sel);

window.mvcBackup = function () {
  const cids = mvcSel();
  const list = cids.length ? mvcStudentsOf(cids) : mvcStudentsOf(mvcCircles().map(c => String(c.id)));
  if (!list.length) { showToast("لا يوجد طلاب في الحلقات المحددة", "warn"); return; }
  const head = ["الاسم", "الحلقة", "النقاط", "الرصيد"];
  const body = list.map(x => {
    const c = cur("circles").find(y => String(y.id) === String(x.circleId));
    return [x.name || "", c ? c.name : "", x.points == null ? 0 : x.points, x.balance == null ? 0 : x.balance];
  });
  const csv = "\uFEFF" + [head].concat(body).map(r => r.map(c => '"' + String(c).replace(/"/g, '""') + '"').join(",")).join("\n");
  const a = document.createElement("a");
  a.href = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8;" }));
  a.download = "أرصدة-حلقات-" + new Date().toISOString().slice(0, 10) + ".csv";
  document.body.appendChild(a); a.click(); a.remove();
  showToast("نُزّلت نسخة من الأرصدة", "success");
};

window.mvcRun = function () {
  const ids = mvcSel();
  if (!MVC.toFac) { showToast("اختر المنشأة التي سيتم النقل إليها", "warn"); return; }
  if (!ids.length) { showToast("حدّد حلقة واحدة على الأقل", "warn"); return; }
  if (String(MVC.fromFac) === String(MVC.toFac)) { showToast("المنشأة المصدر والوجهة متطابقتان", "warn"); return; }
  const to = mvsFacs().find(f => String(f.id) === String(MVC.toFac));
  const studs = mvcStudentsOf(ids).length;
  openModal("تأكيد نقل الحلقات", ids.length + " حلقة",
    noteCard(`ستُنقل <strong>${ids.length}</strong> حلقة بكامل طلابها (<strong>${studs}</strong> طالب)
      إلى <strong>${esc(to ? to.name : "—")}</strong>، و<strong>ستُحذف جميع النقاط والأرصدة</strong>.`),
    `<button class="btn btn-danger" data-action="mvc-run-do">تنفيذ النقل</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
};

window.mvcRunDo = function () {
  const ids = mvcSel();
  const to = mvsFacs().find(f => String(f.id) === String(MVC.toFac));
  const from = mvsFacs().find(f => String(f.id) === String(MVC.fromFac));
  const isMosque = (cur("mosques") || []).some(m => String(m.id) === String(MVC.toFac));
  let nStud = 0;

  ids.forEach(id => {
    const c = (DB.circles || []).find(x => String(x.id) === String(id));
    if (!c) return;
    if (isMosque) { c.mosqueId = MVC.toFac; c.complexId = to && to.complexId ? to.complexId : ""; }
    else { c.complexId = MVC.toFac; c.mosqueId = ""; }
    persistSet("circles", c);
    (DB.students || []).forEach(st => {
      if (String(st.circleId) !== String(id)) return;
      st.mosqueId = c.mosqueId || ""; st.complexId = c.complexId || "";
      st.points = 0; st.balance = 0;
      persistSet("students", st); nStud++;
    });
  });

  if (!Array.isArray(DB.moveLog)) DB.moveLog = [];
  const log = { id: "mvc" + Date.now(), kind: "circles", ts: Date.now(),
                from: from ? from.name : "—", to: to ? to.name : "—",
                count: ids.length, students: nStud };
  DB.moveLog.push(log); persistSet("moveLog", log);

  MVC.sel = {}; closeModal();
  showToast("نُقلت " + ids.length + " حلقة و" + nStud + " طالب", "success");
  mount();
};

