function orpStaffList() {
  let list = cur("teachers");
  if (ORP.unit) list = list.filter(t => String(t.unitId || t.mosqueId || t.complexId) === String(ORP.unit));
  return list;
}
function orpRecords() {
  if (!ORP.staff) return [];
  return (cur("attendance") || []).filter(a => String(a.staffId) === String(ORP.staff))
    .slice().sort((a, b) => String(b.date).localeCompare(String(a.date)));
}
function orpFixed(k) {
  /* أقسام «الدوام الثابت» تحسب سجلات الدوام الثابت وحده — لا المرن ولا المفتوح */
  const recs = orpRecords().filter(a => (a.kind || "fixed") === "fixed");
  return recs.filter(a => {
    if (k === "absent")  return a.status === "غائب";
    if (k === "excused") return a.status === "مستأذن" && a.excuse;
    if (k === "permit")  return a.status === "مستأذن" && !a.excuse;
    if (k === "late")    return a.status === "متأخر";
    if (k === "early")   return !!a.early;
    if (k === "noout")   return !!a.in && !a.out;
    if (k === "wait")    return !a.in && a.status !== "غائب" && a.status !== "مستأذن";
    if (k === "full")    return !!a.in && !!a.out && a.status === "حاضر" && !a.early;
    return false;
  }).length;
}
function orpMins(a) {
  if (!a.in || !a.out) return 0;
  const p = t => { const x = String(t).split(":"); return (+x[0] || 0) * 60 + (+x[1] || 0); };
  return Math.max(0, p(a.out) - p(a.in));
}
function orpFlex(k, kind) {
  const recs = orpRecords().filter(a => (a.kind || "fixed") === kind);
  const mins = recs.map(orpMins).filter(m => m > 0);
  if (k === "hours")    return Math.round(mins.reduce((x, y) => x + y, 0) / 60);
  if (k === "sess")     return recs.length;
  if (k === "longest")  return mins.length ? Math.round(Math.max.apply(null, mins) / 60 * 10) / 10 : 0;
  if (k === "shortest") return mins.length ? Math.round(Math.min.apply(null, mins) / 60 * 10) / 10 : 0;
  if (k === "left") {
    const target = Number((DB.settings || {}).monthlyHours) || 160;
    return Math.max(0, target - Math.round(mins.reduce((x, y) => x + y, 0) / 60));
  }
  return 0;
}

window.orpUnit  = function (v) { ORP.unit = v; ORP.staff = ""; mount(); };
window.orpStaff = function (v) { ORP.staff = v; mount(); };
window.orpPrint = function () {
  if (!ORP.staff) { showToast("اختر الموظف أولاً", "warn"); return; }
  window.print();
};
window.orpFilter = function () {
  const recs = orpRecords();
  if (!recs.length) { showToast("لا توجد سجلات دوام لهذا الموظف", "warn"); return; }
  showToast("عرض " + recs.length + " سجلاً", "info");
};


/* ---- قوائم السجلات خلف كل بطاقة ---- */
function orpFixedList(k) {
  const recs = orpRecords().filter(a => (a.kind || "fixed") === "fixed");
  return recs.filter(a => {
    if (k === "absent")  return a.status === "غائب";
    if (k === "excused") return a.status === "مستأذن" && a.excuse;
    if (k === "permit")  return a.status === "مستأذن" && !a.excuse;
    if (k === "late")    return a.status === "متأخر";
    if (k === "early")   return !!a.early;
    if (k === "noout")   return !!a.in && !a.out;
    if (k === "wait")    return !a.in && a.status !== "غائب" && a.status !== "مستأذن";
    if (k === "full")    return !!a.in && !!a.out && a.status === "حاضر" && !a.early;
    return false;
  });
}
function orpMinsTxt(m) {
  if (!m) return "—";
  const h = Math.floor(m / 60), mm = m % 60;
  return (h ? h + " ساعة" : "") + (h && mm ? " و" : "") + (mm ? mm + " دقيقة" : "");
}

window.orpShowFixed = function (k) {
  if (!ORP.staff) { showToast("اختر الموظف أولاً", "warn"); return; }
  const def = ORP_FIXED.find(x => x.k === k) || {};
  const list = orpFixedList(k);
  openModal(def.h || "", list.length + " يوم",
    list.length ? `<div class="pt-scroll"><table class="ptable"><thead><tr>
        <th>اليوم</th><th>حالة التحضير</th><th>الحضور</th><th>الانصراف</th><th>المدة</th>
      </tr></thead><tbody>${list.map(a => `<tr>
        <td class="pt-name">${esc(a.date || "—")}</td><td>${esc(a.status || "—")}</td>
        <td class="pt-num">${esc(a.in || "—")}</td><td class="pt-num">${esc(a.out || "—")}</td>
        <td class="pt-num">${esc(orpMinsTxt(orpMins(a)))}</td></tr>`).join("")}</tbody></table></div>`
      : `<div class="qg-empty">لا توجد أيام ضمن هذه الحالة</div>`,
    `<button class="btn btn-ghost" data-action="close-modal">إغلاق</button>`);
};

window.orpShowFlex = function (k, kind) {
  if (!ORP.staff) { showToast("اختر الموظف أولاً", "warn"); return; }
  const def = ORP_FLEX.find(x => x.k === k) || {};
  const kindAr = kind === "flex" ? "دوام مرن" : "دوام مفتوح";
  let list = orpRecords().filter(a => (a.kind || "fixed") === kind);

  if (k === "longest" || k === "shortest") {
    const mins = list.map(orpMins).filter(m => m > 0);
    if (mins.length) {
      const target = k === "longest" ? Math.max.apply(null, mins) : Math.min.apply(null, mins);
      list = list.filter(a => orpMins(a) === target);
    } else list = [];
  }
  if (k === "left") {
    const target = Number((DB.settings || {}).monthlyHours) || 160;
    const done = Math.round(list.map(orpMins).reduce((x, y) => x + y, 0) / 60);
    openModal(def.h, kindAr,
      `<div class="form-grid">
        <div class="field"><label>الساعات المطلوبة شهرياً</label><input value="${target}" readonly></div>
        <div class="field"><label>المنفَّذ</label><input value="${done}" readonly></div>
        <div class="field full"><label>المتبقي</label><input value="${Math.max(0, target - done)}" readonly></div>
      </div>`,
      `<button class="btn btn-ghost" data-action="close-modal">إغلاق</button>`);
    return;
  }

  openModal(def.h || "", kindAr + " — " + list.length + " جلسة",
    list.length ? `<div class="pt-scroll"><table class="ptable"><thead><tr>
        <th>اليوم</th><th>البداية</th><th>النهاية</th><th>المدة</th>
      </tr></thead><tbody>${list.map(a => `<tr>
        <td class="pt-name">${esc(a.date || "—")}</td>
        <td class="pt-num">${esc(a.in || "—")}</td><td class="pt-num">${esc(a.out || "—")}</td>
        <td class="pt-num">${esc(orpMinsTxt(orpMins(a)))}</td></tr>`).join("")}</tbody></table></div>`
      : `<div class="qg-empty">لا توجد جلسات ضمن هذا النوع</div>`,
    `<button class="btn btn-ghost" data-action="close-modal">إغلاق</button>`);
};

function orpCard(def, val, unitAr, onclick) {
  return `<div class="orp-card" style="--cb:${def.bg};--cc:${def.c}">
    <button type="button" class="orp-ico" onclick="${onclick}" title="عرض ${esc(def.h)}">${ORP_ICONS[def.i]}</button>
    <button type="button" class="orp-lab" onclick="${onclick}">${esc(def.h)}</button>
    <span class="orp-val"><b>${val}</b>${unitAr ? " " + unitAr : ""}</span>
  </div>`;
}

