function sysAllPillars() {
  const out = [];
  SYS_PLAN_MAP.forEach(g => {
    out.push(Object.assign({ group: g.g }, g.main));
    g.kids.forEach(k => out.push(Object.assign({ group: g.g }, k)));
  });
  return out;
}

function sysPillarCfg(pid, k) {
  const def = sysAllPillars().find(x => x.k === k) || {};
  const saved = ((sysPrgCfg(pid).pillars || {})[k]) || {};
  return {
    on:      saved.on != null ? saved.on !== false : !def.off,
    name:    saved.name || def.base || k,
    base:    def.base || k,
    qtyType: saved.qtyType || SYS_QTY_TYPES[0],
    qty:     saved.qty || "",
    qtyNum:  Number(saved.qtyNum) || 0,
    dir:     saved.dir || SYS_DIRS[0],
    dirRev:  saved.dirRev || SYS_DIRS_REV[0],
    start:   saved.start != null ? String(saved.start) : "",
    lessons: Number(saved.lessons) || 0,
    color:   saved.color || "",
    pass:    Number(saved.pass) || 0,
    onFail:  saved.onFail || "repeat"
  };
}

