/* أدوات مساعدة لأقسام المنشآت */
function facScope() {
  const cx = cur("complexes"), mq = cur("mosques"), ci = cur("circles"), st = cur("students");
  return [].concat(cx, mq).map(f => {
    const cs = ci.filter(c => String(c.mosqueId) === String(f.id) || String(c.complexId) === String(f.id));
    const ids = cs.map(c => String(c.id));
    return { f, circles: cs, ids, students: st.filter(x => ids.indexOf(String(x.circleId)) > -1) };
  });
}
function sBarsH(pairs, tone) {
  const max = Math.max(1, ...pairs.map(p => p[1]));
  if (!pairs.length) return `<div class="s-empty"><span>لا توجد بيانات</span></div>`;
  return `<div class="s-hbars">${pairs.map(([l, v]) =>
    `<div class="s-hbar"><span class="s-hbar-l">${esc(l)}</span>
      <span class="s-hbar-t"><i style="width:${Math.round(v * 100 / max)}%;background:${tone || "#50c3c7"}"></i></span>
      <span class="s-hbar-v">${v}</span></div>`).join("")}</div>`;
}

