function natFlag(name) {
  const iso = NAT_ISO[String(name).trim()];
  const body = iso && FLAGS[iso];
  return `<svg class="s-flag" viewBox="0 0 24 16" width="26" height="18">
    ${body || '<rect width="24" height="16" fill="#e4eded"/>'}
    <rect width="24" height="16" fill="none" stroke="rgba(0,0,0,.14)" stroke-width="1"/></svg>`;
}

/* الخريطة تُحمَّل مرة واحدة ثم تُلوَّن الدول التي بها طلاب */
window.__worldMap = null;
function natMap(rows, total) {
  const tones = ["#41c7cb", "#c86ee0", "#f2913f", "#f2b880", "#afdfe1"];
  const marks = rows.slice(0, 5).map(([n], i) => {
    const iso = NAT_ISO[String(n).trim()];
    return iso ? `#worldMapSvg #${iso}{fill:${tones[i]}}` : "";
  }).join("");
  const top = rows[0];
  return `<div class="s-map" id="sMap">
    <style>${marks}</style>
    ${top ? `<div class="s-map-tip">${natFlag(top[0])}<strong>${esc(top[0])}</strong><span>${top[1]} طالب</span></div>` : ""}
    <div class="s-map-holder">جارٍ تحميل الخريطة…</div>
  </div>`;
}
window.loadWorldMap = function (counts) {
  const holder = document.querySelector("#sMap .s-map-holder");
  if (!holder) return;
  if (counts) window.__natCounts = counts;
  const draw = svg => { holder.innerHTML = svg; wireMapHover(); };
  if (window.__worldMap) return draw(window.__worldMap);
  const base = location.pathname.indexOf("/admin/") > -1 ? "../" : "";
  fetch(base + "world-map.svg").then(r => r.ok ? r.text() : "").then(t => {
    if (!t) { holder.textContent = "تعذّر تحميل الخريطة"; return; }
    window.__worldMap = t; draw(t);
  }).catch(() => { holder.textContent = "تعذّر تحميل الخريطة"; });
};

/* تلميح يتبع المؤشر: علم الدولة واسمها وعدد طلابها */
function wireMapHover() {
  const box = document.getElementById("sMap");
  const svg = box && box.querySelector("#worldMapSvg");
  if (!svg || svg.dataset.hoverReady) return;
  svg.dataset.hoverReady = "1";

  let tip = box.querySelector(".s-map-hover");
  if (!tip) {
    tip = document.createElement("div");
    tip.className = "s-map-hover";
    box.appendChild(tip);
  }

  const counts = window.__natCounts || {};
  let last = null;

  svg.addEventListener("mousemove", e => {
    const path = e.target.closest("path");
    if (!path || !path.id) { hide(); return; }

    if (path.id !== last) {
      last = path.id;
      if (svg.__on) svg.__on.classList.remove("hovered");
      path.classList.add("hovered");
      svg.__on = path;

      const iso = path.id.toLowerCase();
      const name = ISO_AR[iso] || path.id.toUpperCase();
      const n = counts[iso] || 0;
      tip.innerHTML = `${natFlag(name)}<div><strong>${esc(name)}</strong>
        <span>${n ? n + " طالب" : "لا يوجد طلاب"}</span></div>`;
      tip.classList.toggle("has", n > 0);
    }

    const r = box.getBoundingClientRect();
    let x = e.clientX - r.left, y = e.clientY - r.top;
    tip.style.display = "flex";
    const tw = tip.offsetWidth, th = tip.offsetHeight;
    tip.style.left = Math.max(6, Math.min(x - tw / 2, r.width - tw - 6)) + "px";
    tip.style.top  = Math.max(6, y - th - 14) + "px";
  });

  function hide() {
    tip.style.display = "none";
    if (svg.__on) { svg.__on.classList.remove("hovered"); svg.__on = null; }
    last = null;
  }
  svg.addEventListener("mouseleave", hide);
}

/* ---- مساعدات العرض ---- */
const SC = { blue:"#498f92", indigo:"#5bc4c8", teal:"#17b3b8", cyan:"#20dae1",
             green:"#129196", orange:"#f2733f", purple:"#41c7cb", violet:"#3fc0c4",
             gold:"#e8a317", pink:"#ee5f9a", dark:"#366567", gray:"#7f9495", red:"#e04b4b" };

/* بطاقة إحصائية: أيقونة وتسمية ملوّنة يميناً، الرقم يساراً */
function sCard(label, val, colour, icon, wide) {
  return `<div class="s-card${wide ? " wide" : ""}" style="--sc:${colour}">
    <div class="s-card-top"><span class="s-val">${val}</span>
      <span class="s-lab">${esc(label)}${ic(icon || "users", 19)}</span></div></div>`;
}
function sGrid(cards, cols) { return `<div class="s-grid" style="--n:${cols || 3}">${cards.join("")}</div>`; }

/* حلقة مجوّفة */
function sDonut(parts, total, size) {
  const R = 54, C = 2 * Math.PI * R;
  let off = 0;
  const segs = parts.filter(p => p.v > 0).map(p => {
    const frac = total > 0 ? p.v / total : 0;
    const d = `<circle class="s-seg" cx="70" cy="70" r="${R}" fill="none" stroke="${p.c}" stroke-width="30"
      stroke-dasharray="${(frac * C).toFixed(2)} ${C}" stroke-dashoffset="${(-off * C).toFixed(2)}"
      transform="rotate(-90 70 70)"></circle>`;
    off += frac; return d;
  }).join("");
  const big = parts.filter(p => p.v > 0).sort((x, y) => y.v - x.v)[0];
  return `<div class="s-donut-wrap">
    <svg viewBox="0 0 140 140" width="${size || 200}" height="${size || 200}">
      <circle cx="70" cy="70" r="${R}" fill="none" stroke="#eff4f4" stroke-width="30"></circle>
      ${segs}
      <text x="70" y="76" text-anchor="middle" font-size="15" font-weight="600" fill="#385657">${total}</text>
    </svg>
    ${big ? `<div class="s-donut-pct" style="color:${big.c}">${total ? (big.v * 100 / total).toFixed(1) : "0.0"}%</div>` : ""}
    <div class="s-legend">${parts.map(p =>
      `<span><i style="background:${p.c}"></i>${esc(p.l)} : <b>${p.v}</b></span>`).join("")}</div>
  </div>`;
}

/* أعمدة رأسية */
function sBarChart(pairs, colour) {
  const max = Math.max(1, ...pairs.map(p => p[1]));
  return `<div class="s-bars"><div class="s-bars-plot">${pairs.map(([l, v]) =>
      `<div class="s-bar-col"><span class="s-bar-v">${v}</span>
        <span class="s-bar" style="height:${Math.max(4, Math.round(v * 160 / max))}px;background:${colour || SC.teal}"></span>
        <span class="s-bar-l">${esc(l)}</span></div>`).join("")}</div></div>`;
}

/* مؤشر دائري */
function sGauge(pctVal, label) {
  const R = 46, C = 2 * Math.PI * R, v = Math.max(0, Math.min(100, Number(pctVal) || 0));
  return `<div class="s-gauge"><strong>${esc(label)}</strong>
    <svg viewBox="0 0 120 120" width="130" height="130">
      <circle cx="60" cy="60" r="${R}" fill="none" stroke="#e4eded" stroke-width="9"></circle>
      <circle cx="60" cy="60" r="${R}" fill="none" stroke="${SC.green}" stroke-width="9" stroke-linecap="round"
        stroke-dasharray="${(v / 100 * C).toFixed(1)} ${C}" transform="rotate(-90 60 60)"></circle>
      <text x="60" y="66" text-anchor="middle" font-size="15" font-weight="700" fill="#385657">${v}%</text>
    </svg></div>`;
}

function sGroupRow(title, cards) {
  return `<div class="s-group"><div class="s-group-t">${esc(title)}</div>${sGrid(cards, 4)}</div>`;
}
function statGroup(items, keyFn, fallback) {
  const m = {};
  items.forEach(x => { const k = keyFn(x) || fallback; m[k] = (m[k] || 0) + 1; });
  return Object.keys(m).map(k => [k, m[k]]).sort((a, b) => b[1] - a[1]);
}
function sDailyBlock(title, total, days, top) {
  return `<div class="s-daily">
    <div class="s-daily-row"><span>${esc(title)} : <b>${total}</b></span>
      <span>الأيام الفعلية : <b>${days} يوم</b></span></div>
    <div class="s-daily-top">أعلى يوم في ${esc(title)} : ${top}</div>
    <div class="s-daily-key">
      <span><i style="background:#0f767a"></i>الأعلى</span><span><i style="background:#24a8ad"></i>وسط مرتفع</span>
      <span><i style="background:#5dd3d7"></i>وسط</span><span><i style="background:#c1eff0"></i>الأقل</span>
    </div>
    ${total === 0 ? `<div class="s-empty">
      <svg viewBox="0 0 24 24" width="46" height="46" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">
        <ellipse cx="10" cy="5.5" rx="7" ry="2.8"/><path d="M3 5.5v5c0 1.5 3.1 2.8 7 2.8s7-1.3 7-2.8v-5"/>
        <path d="M3 10.5v5c0 1.5 3.1 2.8 7 2.8 .6 0 1.2 0 1.8-.1"/>
        <circle cx="17.5" cy="17" r="4.6" fill="currentColor" stroke="none"/>
        <path d="M16 15.5l3 3M19 15.5l-3 3" stroke="#fff" stroke-width="1.7"/></svg>
      <span>لا توجد بيانات</span></div>` : ""}
  </div>`;
}

function statBody(k) {
  const st = cur("students"), ci = cur("circles"), te = cur("teachers"),
        cx = cur("complexes"), mq = cur("mosques"), pl = cur("plans"),
        att = cur("attendance") || [], pr = cur("programs");
  const facs = [].concat(cx, mq);
  const sum = (a, f) => a.reduce((x, y) => x + (Number(f(y)) || 0), 0);
  const days = [...new Set(att.map(a => a.date))].length;
  /* الحقول المحفوظة فارغةٌ دائماً — تُشتقّ من الواجبات */
  const tally = x => (Number(x.hifzDone) || Number(x.revDone) || Number(x.fixDone))
    ? x : Object.assign({}, x, planTally(x));
  const plT = (pl || []).map(tally);
  const hifzD = sum(plT, x => x.hifzDone), revD = sum(plT, x => x.revDone), fixD = sum(plT, x => x.fixDone);
  const totAll = sum(pl, x => (Number(x.hifzTotal)||0)+(Number(x.revTotal)||0)+(Number(x.fixTotal)||0));
  const ach = totAll ? Math.round((hifzD + revD + fixD) * 100 / totAll) : 0;
  const cnt = s2 => att.filter(a => a.status === s2).length;

  const SCOPE = facScope();
  switch (k) {
    case "cirGeneral":
      return `<div class="s-split">
        ${sGauge(ach, "مؤشر الإنجاز")}
        <div class="s-split-main">${sGrid([
          sCard("عدد الحلقات", ci.length, SC.blue, "grid"),
          sCard("الطلاب", st.length, SC.indigo, "users"),
          sCard("المعلمين/ات", te.length, SC.teal, "teacher"),
          sCard("أوجه الحفظ", hifzD, SC.orange, "book"),
          sCard("أوجه المراجعة", revD, SC.blue, "book"),
          sCard("الأيام الفعلية", days, SC.purple, "calendar")
        ], 2)}</div></div>`;

    case "cirAchieve": return ci.map(c => {
        const ss = st.filter(x => String(x.circleId) === String(c.id));
        const ps = pl.filter(y => ss.some(z => String(z.id) === String(y.studentId)));
        return sGroupRow(c.name || "—", [
          sCard("الطلاب", ss.length, SC.blue, "users"),
          sCard("أوجه الحفظ", sum(ps.map(y => Object.assign({}, y, planTally(y))), y => y.hifzDone), SC.blue, "book"),
          sCard("أوجه المراجعة", sum(ps, y => y.revDone), SC.blue, "book"),
          sCard("الأيام الفعلية", days, SC.blue, "calendar")]);
      }).join("");

    case "cirStudents": return sBarsH(ci.map(c =>
        [c.name || "—", st.filter(x => String(x.circleId) === String(c.id)).length]), "#129196");

    case "cirAttend": return sBarsH(ci.map(c =>
        [c.name || "—", att.filter(a => String(a.circleId) === String(c.id) && a.status === "حاضر").length]), "#17b3b8");

    case "cirPlan": return ci.map(c => {
        const ss = st.filter(x => String(x.circleId) === String(c.id));
        const ps = pl.filter(y => ss.some(z => String(z.id) === String(y.studentId)));
        const t2 = sum(ps, y => (Number(y.hifzTotal)||0)+(Number(y.revTotal)||0)+(Number(y.fixTotal)||0));
        const d2 = sum(ps.map(y => Object.assign({}, y, planTally(y))), y => (Number(y.hifzDone)||0)+(Number(y.revDone)||0)+(Number(y.fixDone)||0));
        return sGroupRow(c.name || "—", [
          sCard("مؤشر الإنجاز", (t2 ? Math.round(d2 * 100 / t2) : 0) + " %", SC.green, "graph"),
          sCard("أوجه الحفظ", sum(ps.map(y => Object.assign({}, y, planTally(y))), y => y.hifzDone), SC.orange, "book"),
          sCard("أوجه المراجعة", sum(ps, y => y.revDone), SC.blue, "book"),
          sCard("أوجه التثبيت", sum(ps, y => y.fixDone), SC.gray, "target")]);
      }).join("");

    case "facGeneral":
      return `<div class="s-split">
        ${sGauge(ach, "مؤشر الإنجاز")}
        <div class="s-split-main">${sGrid([
          sCard("عدد المنشآت", facs.length, SC.teal, "building"),
          sCard("المجمعات", cx.length, SC.indigo, "layers"),
          sCard("المساجد", mq.length, SC.green, "mosque"),
          sCard("الحلقات", ci.length, SC.blue, "grid"),
          sCard("الطلاب", st.length, SC.indigo, "users"),
          sCard("المعلمين/ات", te.length, SC.purple, "teacher")
        ], 2)}</div></div>`;

    case "facRegister": {
      const onF = facs.filter(x => x.status === "نشط").length;
      return sCard("المنشآت المسجلة حالياً", facs.length, SC.green, "building", true) +
        sGrid([ sCard("فعّالة", onF, SC.green, "check"),
                sCard("متوقفة", facs.length - onF, SC.red, "pause"),
                sCard("بلا حلقات", SCOPE.filter(x => !x.circles.length).length, SC.orange, "alert") ], 3);
    }

    case "facCircles":  return sBarsH(SCOPE.map(x => [x.f.name || "—", x.circles.length]), "#50c3c7");
    case "facStudents": return sBarsH(SCOPE.map(x => [x.f.name || "—", x.students.length]), "#129196");
    case "facTeachers": return sBarsH(facs.map(f => [f.name || "—",
        te.filter(t => String(t.mosqueId) === String(f.id) || String(t.complexId) === String(f.id)).length]), "#41c7cb");

    case "facAttend": return sBarsH(SCOPE.map(x => [x.f.name || "—",
        att.filter(a => x.ids.indexOf(String(a.circleId)) > -1 && a.status === "حاضر").length]), "#17b3b8");

    case "facPlan": return SCOPE.map(x => {
        const ps = pl.filter(p2 => x.students.some(y => String(y.id) === String(p2.studentId)));
        const t2 = sum(ps, y => (Number(y.hifzTotal)||0)+(Number(y.revTotal)||0)+(Number(y.fixTotal)||0));
        const d2 = sum(ps.map(y => Object.assign({}, y, planTally(y))), y => (Number(y.hifzDone)||0)+(Number(y.revDone)||0)+(Number(y.fixDone)||0));
        return sGroupRow(x.f.name || "—", [
          sCard("مؤشر الإنجاز", (t2 ? Math.round(d2 * 100 / t2) : 0) + " %", SC.green, "graph"),
          sCard("أوجه الحفظ", sum(ps.map(y => Object.assign({}, y, planTally(y))), y => y.hifzDone), SC.orange, "book"),
          sCard("أوجه المراجعة", sum(ps, y => y.revDone), SC.blue, "book"),
          sCard("أوجه التثبيت", sum(ps, y => y.fixDone), SC.gray, "target")]);
      }).join("");

    case "general":
      return `<div class="s-split">
        ${sGauge(ach, "مؤشر الإنجاز")}
        <div class="s-split-main">${sGrid([
          sCard("الطلاب", st.length, SC.indigo, "users"),
          sCard("المعلمين/ات", te.length, SC.teal, "teacher"),
          sCard("الحلقات", ci.length, SC.green, "grid"),
          sCard("أوجه الحفظ", hifzD, SC.orange, "book"),
          sCard("أوجه المراجعة", revD, SC.blue, "book"),
          sCard("الأيام الفعلية", days, SC.purple, "calendar"),
          sCard("عدد المنشآت", facs.length, SC.teal, "building")
        ], 2)}</div></div>`;

    case "enrolled": {
      const nw = st.filter(x => x.joined && String(x.joined).slice(0, 7) === new Date().toISOString().slice(0, 7)).length;
      return sCard("الطلاب المسجلين حالياً", st.length, SC.green, "users", true) +
        `<div class="s-sub">الطلاب المسجلين جدد (${nw})</div>` +
        sGrid([ sCard("مواطن", st.filter(x => !x.nationality || x.nationality.indexOf("السعود") > -1).length, SC.indigo, "shield"),
                sCard("مقيم", st.filter(x => x.nationality && x.nationality.indexOf("السعود") === -1).length, SC.indigo, "list") ], 2);
    }

    case "facAchieve":
      return `<div class="s-fac-title">إنجازات المنشـآت | ${facs.length} |</div>` +
        facs.map(f => {
          const cs = ci.filter(c => String(c.mosqueId) === String(f.id) || String(c.complexId) === String(f.id));
          const ids = cs.map(c => String(c.id));
          const ss = st.filter(x => ids.indexOf(String(x.circleId)) > -1);
          const ps = pl.filter(x => ss.some(y => String(y.id) === String(x.studentId)));
          return sGroupRow(f.name || "—", [
            sCard("الطلاب", ss.length, SC.blue, "users"),
            sCard("الحلقات", cs.length, SC.blue, "grid"),
            sCard("أوجه الحفظ", sum(ps, x => x.hifzDone), SC.blue, "book"),
            sCard("أوجه المراجعة", sum(ps, x => x.revDone), SC.blue, "book"),
            sCard("الأيام الفعلية", days, SC.blue, "calendar")
          ]);
        }).join("");

    case "attendance": return sGrid([
      sCard("عدد الحضور", cnt("حاضر"), SC.green, "checkCircle"),
      sCard("عدد الغياب", cnt("غائب"), SC.red, "x"),
      sCard("عدد الاستئذان", cnt("مستأذن"), SC.indigo, "list"),
      sCard("عدد التأخر", cnt("متأخر"), SC.gray, "clock")], 3);

    /* المواصفات: «الطلاب الأكثر غياباً أو تعثراً في الحفظ» — من الفترة
       المعروضة (cur يفرز الحضور بها)، وفي نطاق المستخدم. */
    case "risk": {
      const nm = sid => (st.find(x => String(x.id) === String(sid)) || {});
      const absBy = {};
      att.forEach(a => {
        if (!a || a.staffId || a.status !== "غائب") return;
        const k2 = String(a.studentId);
        absBy[k2] = absBy[k2] || { n: 0, noEx: 0, last: "" };
        absBy[k2].n++;
        if (!a.reason && !a.excuse) absBy[k2].noEx++;
        if (String(a.date) > absBy[k2].last) absBy[k2].last = String(a.date);
      });
      const topAbs = Object.keys(absBy).filter(k2 => nm(k2).id)
        .sort((x, y) => absBy[y].n - absBy[x].n).slice(0, 10);
      const tId = typeof activeTermId === "function" ? activeTermId() : "";
      const asgs = (cur("assignments") || []).filter(a => !tId || !a.termId || String(a.termId) === tId);
      const weak = {};
      asgs.forEach(a => {
        const bad = a.status === "failed" || (a.status === "missed" && !a.settled) || Number(a.shortQty) > 0;
        if (!bad) return;
        const k2 = String(a.studentId);
        weak[k2] = (weak[k2] || 0) + 1;
      });
      const topWeak = Object.keys(weak).filter(k2 => nm(k2).id)
        .sort((x, y) => weak[y] - weak[x]).slice(0, 10);
      const tbl = (head, rows) => rows.length
        ? `<div class="pt-wrap"><div class="pt-scroll"><table class="ptable"><thead><tr>${head}</tr></thead>
            <tbody>${rows.join("")}</tbody></table></div></div>`
        : `<div class="muted" style="padding:14px;text-align:center">لا بيانات في هذه الفترة.</div>`;
      return `<div class="s-sub">الأكثر غياباً</div>` +
        tbl("<th>#</th><th>الطالب</th><th>الحلقة</th><th>أيام الغياب</th><th>بلا عذر</th><th>آخر غياب</th>",
          topAbs.map((k2, i) => `<tr><td class="pt-num">${toArabicDigits(i + 1)}</td>
            <td><strong>${esc(nm(k2).name || "—")}</strong></td><td class="muted">${esc(nm(k2).circle || "—")}</td>
            <td class="pt-num pay-bad">${toArabicDigits(absBy[k2].n)}</td><td class="pt-num">${toArabicDigits(absBy[k2].noEx)}</td>
            <td class="pt-num" dir="ltr">${esc(absBy[k2].last)}</td></tr>`)) +
        `<div class="s-sub" style="margin-top:14px">الأكثر تعثراً في الحفظ</div>` +
        tbl("<th>#</th><th>الطالب</th><th>الحلقة</th><th>واجبات راسبة أو فائتة أو ناقصة</th>",
          topWeak.map((k2, i) => `<tr><td class="pt-num">${toArabicDigits(i + 1)}</td>
            <td><strong>${esc(nm(k2).name || "—")}</strong></td><td class="muted">${esc(nm(k2).circle || "—")}</td>
            <td class="pt-num pay-bad">${toArabicDigits(weak[k2])}</td></tr>`));
    }

    case "exams": return sGrid([
      sCard("عدد الاختبارات", 0, SC.dark, "list"),
      sCard("طلاب لديهم اختبارات", 0, SC.green, "users"),
      sCard("حلقات لديها اختبارات", 0, SC.dark, "grid"),
      sCard("منشآت لديها اختبارات", 0, SC.dark, "building"),
      sCard("معلمين لدى طلابهم اختبارات", 0, SC.indigo, "teacher"),
      sCard("إجمالي الأجزاء", 0, SC.orange, "book"),
      sCard("نسبة النجاح", "0 %", SC.dark, "check"),
      sCard("متوسط الدرجات", "0 %", SC.violet, "graph")], 3);

    case "points": return sGrid([
      sCard("إجمالي النقاط", 0, SC.gold, "star"),
      sCard("طلاب لديهم نقاط", 0, SC.purple, "users"),
      sCard("حلقات لدى طلابها نقاط", 0, SC.dark, "grid"),
      sCard("منشآت لدى طلابها نقاط", 0, SC.green, "building")], 3);

    case "store": return sGrid([
      sCard("إجمالي الجوائز المستبدلة", 0, SC.dark, "gift"),
      sCard("إجمالي النقاط المستبدلة", 0, SC.dark, "refresh"),
      sCard("طلاب استبدلوا من المتجر", 0, SC.purple, "users"),
      sCard("حلقات استبدلت", 0, SC.dark, "grid"),
      sCard("منشآت استبدلت", 0, SC.green, "building")], 3);

    case "byNat": {
      const g = statGroup(st, x => x.nationality, "المملكة العربية السعودية");
      const byIso = {};
      g.forEach(([n, v]) => { const iso = NAT_ISO[String(n).trim()]; if (iso) byIso[iso] = (byIso[iso] || 0) + v; });
      setTimeout(() => window.loadWorldMap(byIso), 0);
      return natMap(g, st.length) +
        `<div class="s-nat-count">عدد الجنسيات : <b>${g.length} جنسية</b></div>
        <div class="s-nat">${g.map(([n, v]) => `<div class="s-nat-item">
          <div class="s-nat-name">${natFlag(n)}<span>${esc(n)}</span></div>
          <div class="s-nat-v"><b>${v} طالب</b> | ${st.length ? (v * 100 / st.length).toFixed(1) : "0.0"} %</div>
        </div>`).join("")}</div>`;
    }

    case "byProgram": {
      const g = statGroup(st, x => { const p2 = pl.find(y => String(y.studentId) === String(x.id));
        const q = p2 && pr.find(z => String(z.id) === String(p2.programId)); return q ? q.name : null; }, "بدون برنامج");
      const cols = [SC.green, "#9eb6b6", "#a3195b", SC.orange, SC.indigo];
      return sDonut(g.map(([l, v], i) => ({ l, v, c: cols[i % cols.length] })), st.length);
    }

    case "byAge": {
      const bands = ["0-5","6-9","10-12","13-15","16-18","19-23","24-30","31-50","51 فأكثر"];
      const m = {}; bands.forEach(b => m[b] = 0);
      st.forEach(x => { if (!x.birth) return;
        const a = Math.floor((Date.now() - new Date(x.birth).getTime()) / 31557600000);
        const b = a <= 5 ? "0-5" : a <= 9 ? "6-9" : a <= 12 ? "10-12" : a <= 15 ? "13-15" :
                  a <= 18 ? "16-18" : a <= 23 ? "19-23" : a <= 30 ? "24-30" : a <= 50 ? "31-50" : "51 فأكثر";
        m[b]++; });
      return sBarChart(bands.slice().reverse().map(b => [b, m[b]]), "#38a1a5");
    }

    case "faces": {
      const parts = [{ l: "الحفظ", v: hifzD, c: SC.violet }, { l: "المراجعة", v: revD, c: SC.orange }, { l: "التثبيت", v: fixD, c: SC.gray }];
      return `<div class="s-faces"><div class="s-faces-sum"><span>المجموع</span><strong>${hifzD + revD + fixD}</strong></div>
        <div class="s-faces-key">${parts.map(p2 => `<div><span><i style="background:${p2.c}"></i>${p2.l} : <b>${p2.v}</b></span>
          <small>الاجزاء : ${Math.floor(p2.v / 20)}</small></div>`).join("")}</div></div>`;
    }

    case "byTime": {
      const g = statGroup(ci, x => x.time, "غير محدد");
      return g.map(([t]) => {
        const cs = ci.filter(c => (c.time || "غير محدد") === t);
        const ids = cs.map(c => String(c.id));
        return sGroupRow(t, [
          sCard("طالب", st.filter(x => ids.indexOf(String(x.circleId)) > -1).length, SC.teal, "users"),
          sCard("حلقات", cs.length, SC.teal, "grid")]);
      }).join("");
    }

    case "byCircle": {
      const g = statGroup(ci, x => x.type, "حلقة تحفيظ");
      const cols = [SC.green, SC.indigo, SC.orange, SC.purple];
      return sDonut(g.map(([l, v], i) => {
        const ids = ci.filter(c => (c.type || "حلقة تحفيظ") === l).map(c => String(c.id));
        return { l, v: st.filter(x => ids.indexOf(String(x.circleId)) > -1).length, c: cols[i % cols.length] };
      }), st.length);
    }

    case "byGender": {
      const m = st.filter(x => (x.gender || "ذكر") === "ذكر").length, f = st.length - m;
      return sDonut([{ l: "ذكر", v: m, c: SC.cyan }, { l: "أنثى", v: f, c: SC.pink }], st.length) +
        `<div class="s-gender">
          <span style="color:${SC.cyan}"><b>${m}</b> ذكر | ${st.length ? Math.round(m * 100 / st.length) : 0} %</span>
          <span style="color:${SC.pink}"><b>${f}</b> أنثى | ${st.length ? Math.round(f * 100 / st.length) : 0} %</span>
        </div>`;
    }

    case "byFacType": case "byFacCat": {
      const key = k === "byFacType" ? "type" : "category";
      /* كان الاحتياطيّ واحداً على جنبَي الشرط:
           k === "byFacType" ? "مدرسه قرأنية" : "مدرسه قرأنية"
         فالمنشآت التي بلا نوع ولا تصنيف تقع على الاسم نفسه، ويظهر
         القسمان مجموعةً واحدة متطابقة تبدو تكراراً. */
      const fb = k === "byFacType" ? "غير محدد النوع" : "غير محدد التصنيف";
      const g = statGroup(facs, x => x[key], fb);

      /* تجميعٌ بحقل لم يُملأ في أي منشأة لا يقول شيئاً: مجموعة واحدة
         اسمها «غير محدد» تكرّر أرقام القسم السابق. يُشرح بدل أن يُعرض. */
      const filled = facs.filter(x => String(x[key] || "").trim()).length;
      if (!filled) {
        return `<div class="s-hint">لم يُحدَّد ${key === "type" ? "نوع" : "تصنيف"} 
          لأي منشأة، فلا تجميع يُعرض. حدّده من بيانات المنشأة ليظهر هذا القسم.</div>`;
      }

      return g.map(([n]) => {
        const fs = facs.filter(x => (x[key] || fb) === n);
        const ids = fs.map(x => String(x.id));
        const cs = ci.filter(c => ids.indexOf(String(c.mosqueId)) > -1 || ids.indexOf(String(c.complexId)) > -1);
        const cids = cs.map(c => String(c.id));
        return sGroupRow(n, [
          sCard("منشاة", fs.length, SC.blue, "building"),
          sCard("حلقة", cs.length, SC.blue, "grid"),
          sCard("طالب", st.filter(x => cids.indexOf(String(x.circleId)) > -1).length, SC.blue, "users")]);
      }).join("");
    }

    case "dayRev":     return sDailyBlock("أوجه المراجعة", revD, days, 0);
    case "dayHifz":    return sDailyBlock("أوجه الحفظ", hifzD, days, 0);
    case "dayAtt":     return sDailyBlock("الحضور", cnt("حاضر"), days, 0);
    case "dayAch":     return sDailyBlock("مؤشر الإنجاز", ach, days, 0);
    case "dayFac":     return sDailyBlock("عدد المنشآت التعليمية", facs.length, days, facs.length);
    case "dayCircles": return sDailyBlock("عدد الحلقات القرآنية", ci.length, days, ci.length);

  }
  return "";
}

