/* بناء صف بيانات لكل منشأة من قاعدة البيانات */
function repFacRows() {
  const out = [];
  const push = (item, kind) => {
    const cid = kind === "mosques" ? item.complexId : item.id;
    const circles  = cur("circles").filter(c => String(kind === "mosques" ? c.mosqueId : c.complexId) === String(item.id));
    const cIds     = circles.map(c => String(c.id));
    const students = cur("students").filter(st => cIds.indexOf(String(st.circleId)) > -1);
    const teachers = cur("teachers").filter(t => String(kind === "mosques" ? t.mosqueId : t.complexId) === String(item.id));
    const plans    = cur("plans").filter(pl => students.some(st => String(st.id) === String(pl.studentId)));

    const sum = (arr, f) => arr.reduce((a, x) => a + (Number(f(x)) || 0), 0);
    const hifz = sum(plans, x => x.hifzTotal), hifzDone = sum(plans, x => x.hifzDone);
    const fix  = sum(plans, x => x.fixTotal),  fixDone  = sum(plans, x => x.fixDone);
    const rev  = sum(plans, x => x.revTotal),  revDone  = sum(plans, x => x.revDone);
    const pct  = (d, t) => t > 0 ? Math.round(d * 100 / t) : null;

    const att = cur("attendance") || [];
    const mine = att.filter(a => cIds.indexOf(String(a.circleId)) > -1);
    const present = mine.filter(a => a.status === "حاضر").length;
    const days = new Set(mine.map(a => a.date)).size;
    const perDay = {};
    mine.forEach(a => { if (a.status === "حاضر") perDay[a.date] = (perDay[a.date] || 0) + 1; });
    const vals = Object.values(perDay);

    const planAvg = pct(hifzDone + fixDone + revDone, hifz + fix + rev);

    out.push({
      _id: item.id, _kind: kind,
      name: item.name || "—",
      branch: kind === "mosques" ? (complexName(cid) || "—") : (item.name || "—"),
      type: item.type || "مدرسة قرآنية",
      category: item.category || "حلقات رجالية",
      manager: item.manager || "—",
      phone: item.phone || item.managerPhone || "—",
      circles: circles.length, teachers: teachers.length, students: students.length,
      activeStudents: students.filter(st => st.active !== false && st.status !== "متوقف").length,
      attend: present, realDays: days, attendPct: pct(present, mine.length),
      minAttend: vals.length ? Math.min.apply(null, vals) : 0,
      maxAttend: vals.length ? Math.max.apply(null, vals) : 0,
      hifz, hifzDone, fix, fixDone, rev, revDone, revTotal: fixDone + revDone,
      achieve: planAvg, planAvg,
      planHifz: pct(hifzDone, hifz), planRev: pct(revDone, rev), planFix: pct(fixDone, fix),
      pillars: circles.length * 5, pillarsDone: 0,
      quality: planAvg == null ? 0 : planAvg,
      qualityText: kpiGrade(planAvg),
      exams: 0, examStudents: 0, examCircles: 0, examParts: 0, examPass: null,
      points: 0, pointStudents: 0, pointCircles: 0, pointsUsed: 0,
      prizesWaiting: 0, prizesAvail: 0, prizeStudents: 0, prizeCircles: 0, prizesUsed: 0
    });
  };
  cur("complexes").forEach(x => push(x, "complexes"));
  cur("mosques").forEach(x => push(x, "mosques"));
  return out;
}

function repFmt(v, t) {
  if (v == null || v === "") return t === "p" ? "(-)" : "—";
  if (t === "p") return v + "%";
  return String(v);
}

/* تطبيق التصفية والفرز */
/* =========================================================================
   إخفاء الأعمدة
   -------------------------------------------------------------------------
   تقاريرُ الطلاب والمنشآت تحمل عشرين عموداً وأكثر، ولا يحتاجها أحدٌ كلَّها
   في وقتٍ واحد: من يريد الحضورَ لا يعنيه اسمُ الأب الإنجليزيّ.

   ما يُخفى يُحفظ لكلّ تقريرٍ على حدة — فالمنشآتُ لا ترث اختيارَ الطلاب.
   والعمودُ الأوّل لا يُخفى: بلا الاسم لا يُعرف السطرُ لمن.
   ========================================================================= */
const REP_HIDDEN = {};                    /* { تقرير: [مفاتيح] } */

function repKey() { return String(REP_STATE.title || "rep"); }

function repHidden() {
  const k = repKey();
  if (!REP_HIDDEN[k]) {
    try {
      const raw = localStorage.getItem("rep_hidden_" + k);
      REP_HIDDEN[k] = raw ? JSON.parse(raw) : [];
    } catch (e) { REP_HIDDEN[k] = []; }
  }
  return REP_HIDDEN[k];
}

function repSaveHidden() {
  try {
    localStorage.setItem("rep_hidden_" + repKey(), JSON.stringify(repHidden()));
  } catch (e) {}
}

window.repColToggle = function (k) {
  const h = repHidden();
  const i = h.indexOf(k);
  if (i > -1) h.splice(i, 1); else h.push(k);
  repSaveHidden();
  mount();
};

window.repColsAll = function (on) {
  const all = REP_STATE.cols || [];
  REP_HIDDEN[repKey()] = on ? [] : all.slice(1).map(c => c.k);
  repSaveHidden();
  mount();
};

/* الأعمدة المعروضة — يمرّ بها العرضُ والتصديرُ والطباعة */
function repCols() {
  const all = REP_STATE.cols || REP_FAC_COLS;
  const hid = repHidden();
  if (!hid.length) return all;
  /* الأوّل يبقى دائماً: بلا الاسم لا يُعرف السطرُ لمن */
  return all.filter((c, i) => i === 0 || hid.indexOf(c.k) === -1);
}

/* لوحة اختيار الأعمدة */
function repColsPanel() {
  const all = REP_STATE.cols || [];
  if (!all.length) return "";

  const hid = repHidden();
  const shown = all.length - hid.length;

  return `<div class="rep-cols-wrap">
    <button type="button" class="rep-cols-btn${hid.length ? " on" : ""}"
      onclick="window.repColsOpen(this)">
      ${ic("layers", 15)}
      <span>الأعمدة</span>
      <b>${toArabicDigits(shown)}/${toArabicDigits(all.length)}</b>
    </button>

    <div class="rep-cols-panel" style="display:none">
      <div class="rcp-head">
        <button type="button" onclick="window.repColsAll(true)">إظهار الكل</button>
        <button type="button" onclick="window.repColsAll(false)">إخفاء الكل</button>
      </div>
      <div class="rcp-list">
        ${all.map((c, i) => {
          const on = i === 0 || hid.indexOf(c.k) === -1;
          return `<label class="rcp-row${on ? " on" : ""}${i === 0 ? " lock" : ""}">
            <input type="checkbox"${on ? " checked" : ""}${i === 0 ? " disabled" : ""}
              onchange="window.repColToggle('${jsAttr(c.k)}')">
            <span>${esc(c.h)}</span>
            ${i === 0 ? '<small>ثابت</small>' : ""}
          </label>`;
        }).join("")}
      </div>
    </div>
  </div>`;
}

window.repColsOpen = function (btn) {
  const p = btn.parentElement.querySelector(".rep-cols-panel");
  if (!p) return;
  const open = p.style.display !== "none";
  /* لوحاتٌ أخرى مفتوحة تُغلق: لا تتراكم فوق بعضها */
  document.querySelectorAll(".rep-cols-panel, .rep-fpanel").forEach(x => {
    x.style.display = "none";
  });
  p.style.display = open ? "none" : "block";
};

function repApply(rows) {
  let r = rows.slice();
  Object.keys(REP_STATE.filters).forEach(k => {
    const v = REP_STATE.filters[k];
    if (v) r = r.filter(x => String(x[k]) === v);
  });
  if (REP_STATE.sort) {
    const col = repCols().find(c => c.k === REP_STATE.sort) || {};
    r.sort((a, b) => {
      let x = a[REP_STATE.sort], y = b[REP_STATE.sort];
      if (col.t === "n" || col.t === "p") { x = Number(x) || 0; y = Number(y) || 0; return (x - y) * REP_STATE.dir; }
      return String(x == null ? "" : x).localeCompare(String(y == null ? "" : y), "ar") * REP_STATE.dir;
    });
  }
  return r;
}

window.repSort = function (k) {
  if (REP_STATE.sort === k) REP_STATE.dir = -REP_STATE.dir;
  else { REP_STATE.sort = k; REP_STATE.dir = 1; }
  mount();
};
window.repFilterOpen = function (k, btn) {
  document.querySelectorAll(".rep-fpanel").forEach(p2 => { if (p2.dataset.k !== k) p2.style.display = "none"; });
  const pan = document.querySelector('.rep-fpanel[data-k="' + k + '"]');
  if (pan) pan.style.display = pan.style.display === "block" ? "none" : "block";
};
window.repFilterSet = function (k, v) {
  if (v === "__all__") delete REP_STATE.filters[k]; else REP_STATE.filters[k] = v;
  REP_STATE.page = 1; mount();
};
window.repSize = function (n) { REP_STATE.size = Number(n) || 10; REP_STATE.page = 1; mount(); };
window.repPage = function (n) { REP_STATE.page = n; mount(); };

/* التصدير */
window.repExport = function (kind) {
  const rows = repApply((REP_STATE.rows || repFacRows)());
  if (kind === "print") { window.print(); return; }

  if (kind === "copy") {
    const head = repCols().map(c => c.h).join("\t");
    const body = rows.map(r => repCols().map(c => r[c.k] == null ? "" : r[c.k]).join("\t")).join("\n");
    const txt = head + "\n" + body;
    const done = () => showToast("تم نسخ " + rows.length + " صفاً إلى الحافظة", "success");
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(txt).then(done).catch(() => showToast("تعذّر النسخ", "warn"));
    } else {
      const ta = document.createElement("textarea");
      ta.value = txt; document.body.appendChild(ta); ta.select();
      try { document.execCommand("copy"); done(); } catch (e) { showToast("تعذّر النسخ", "warn"); }
      ta.remove();
    }
    return;
  }
  const head = repCols().map(c => c.h);
  const body = rows.map(r => repCols().map(c => {
    const v = r[c.k];
    return v == null ? "" : String(v);
  }));
  const csv = "\uFEFF" + [head].concat(body).map(r => r.map(c => '"' + String(c).replace(/"/g, '""') + '"').join(",")).join("\n");
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = (REP_STATE.title || "تقرير") + "-" + new Date().toISOString().slice(0, 10) + ".csv";
  document.body.appendChild(a); a.click(); a.remove();
  showToast("تم تنزيل الملف", "success");
};

function repRender(cfg) {
  REP_STATE.cols = cfg.cols; REP_STATE.rows = cfg.rows; REP_STATE.title = cfg.title;

  /* المعروضةُ وحدها تُرسم — والكاملةُ باقيةٌ في REP_STATE للوحة الاختيار */
  const COLS = repCols();
  const all = cfg.rows();
  const rows = repApply(all);
  const size = REP_STATE.size;
  const pages = Math.max(1, Math.ceil(rows.length / size));
  const page = Math.min(REP_STATE.page, pages);
  const view = rows.slice((page - 1) * size, page * size);

  const SORT = '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M7 4v16M4 17l3 3 3-3M17 20V4M14 7l3-3 3 3"/></svg>';
  const FUN  = '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 5h18l-7 8v6l-4 2v-8z"/></svg>';
  const CH   = '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M6 9l6 6 6-6"/></svg>';
  const CAL  = '<svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4M16 3v4"/></svg>';

  const head = COLS.map(c => {
    let tools = "";
    if (c.s) tools += `<button class="rep-ic${REP_STATE.sort === c.k ? " on" : ""}" onclick="window.repSort('${c.k}')" title="فرز">${SORT}</button>`;
    if (c.f) {
      const vals = [...new Set(all.map(r => String(r[c.k])))].filter(v => v && v !== "null" && v !== "undefined").sort();
      tools += `<button class="rep-ic${REP_STATE.filters[c.k] ? " on" : ""}" onclick="window.repFilterOpen('${c.k}',this)" title="تصفية">${FUN}</button>
        <div class="rep-fpanel" data-k="${c.k}" style="display:none">
          <div class="tb-opt" onclick="window.repFilterSet('${c.k}','__all__')">الكل</div>
          ${vals.map(v => `<div class="tb-opt${REP_STATE.filters[c.k] === v ? " sel" : ""}" onclick="window.repFilterSet('${c.k}','${jsAttr(v)}')">${esc(v)}</div>`).join("")}
        </div>`;
    }
    let agg = "";
    if (c.t === "p") {
      const vals = all.map(r => r[c.k]).filter(v => v != null && v !== "");
      agg = `<span class="rep-agg">(${vals.length ? Math.round(vals.reduce((a, b) => a + Number(b), 0) / vals.length) + "%" : "-"})</span>`;
    }
    return `<th><span class="rep-th">${tools}<span>${esc(c.h)}${agg}</span></span></th>`;
  }).join("");

  const body = view.length
    ? view.map(r => `<tr>${COLS.map(c =>
        `<td class="${c.t === "n" || c.t === "p" ? "pt-num" : ""}">${esc(repFmt(r[c.k], c.t))}</td>`).join("")}</tr>`).join("")
    : `<tr><td colspan="${COLS.length}" class="rep-empty">
        <svg viewBox="0 0 24 24" width="54" height="54" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">
          <ellipse cx="10" cy="5.5" rx="7" ry="2.8"/>
          <path d="M3 5.5v5c0 1.5 3.1 2.8 7 2.8s7-1.3 7-2.8v-5"/>
          <path d="M3 10.5v5c0 1.5 3.1 2.8 7 2.8 .6 0 1.2 0 1.8-.1"/>
          <circle cx="17.5" cy="17" r="4.6" fill="currentColor" stroke="none"/>
          <path d="M16 15.5l3 3M19 15.5l-3 3" stroke="#fff" stroke-width="1.7"/>
        </svg>
        <span>لا توجد بيانات</span>
      </td></tr>`;

  const pager = pages > 1 ? `<div class="rep-pager">
      ${Array.from({ length: pages }, (_, i) => i + 1).map(n =>
        `<button class="rep-pg${n === page ? " on" : ""}" onclick="window.repPage(${n})">${n}</button>`).join("")}
    </div>` : "";

  const today = new Date();
  const dayName = ["الأحد","الاثنين","الثلاثاء","الأربعاء","الخميس","الجمعة","السبت"][today.getDay()];

  const picks = (cfg.picks || []).map(p2 => `<div class="rep-pick">
      <label>${esc(p2.label)} (${p2.count})</label>
      <button class="rep-pill wide"><span>${esc(p2.value)}</span>${CH}</button>
    </div>`).join("");

  return `<div class="page">
    ${pageHead(cfg.title, "", backArrow())}
    ${repTermBar()}


    ${picks ? `<div class="rep-picks">${picks}</div>` : ""}

    <div class="rep-tools">
      ${repColsPanel()}
      <button class="rep-exp e-pdf" onclick="window.repExport('print')" title="تصدير PDF / طباعة">
        <svg viewBox="0 0 32 32" width="26" height="26" fill="none">
          <path d="M7 3.6h11.4L25 10.2V27a1.4 1.4 0 01-1.4 1.4H7A1.4 1.4 0 015.6 27V5A1.4 1.4 0 017 3.6z" fill="#fff" stroke="#d64541" stroke-width="1.7"/>
          <path d="M18.4 3.6V10h6.6" stroke="#d64541" stroke-width="1.7" stroke-linejoin="round"/>
          <rect x="4" y="16.4" width="20" height="8" rx="1.6" fill="#d64541"/>
          <text x="14" y="22.6" font-size="6" font-weight="700" fill="#fff" text-anchor="middle" font-family="Arial">PDF</text>
          <circle cx="25.4" cy="6.6" r="4" fill="#d64541"/>
          <path d="M25.4 4.6v2.6M25.4 8.6h.02" stroke="#fff" stroke-width="1.4" stroke-linecap="round"/>
        </svg></button>
      <button class="rep-exp e-excel" onclick="window.repExport('csv')" title="تصدير Excel">
        <svg viewBox="0 0 32 32" width="26" height="26" fill="none">
          <path d="M9 3.6h10.4L26 10.2V27a1.4 1.4 0 01-1.4 1.4H9A1.4 1.4 0 017.6 27V5A1.4 1.4 0 019 3.6z" fill="#fff" stroke="#1c7578" stroke-width="1.7"/>
          <path d="M19.4 3.6V10H26" stroke="#1c7578" stroke-width="1.7" stroke-linejoin="round"/>
          <rect x="3" y="11" width="14" height="14" rx="2" fill="#1c7578"/>
          <path d="M7 14.6l6 6.8M13 14.6l-6 6.8" stroke="#fff" stroke-width="1.9" stroke-linecap="round"/>
        </svg></button>
      <button class="rep-exp e-copy" onclick="window.repExport('copy')" title="نسخ الجدول">
        <svg viewBox="0 0 32 32" width="26" height="26" fill="none">
          <rect x="5.4" y="4.6" width="9.6" height="22.8" rx="2.4" fill="#fff" stroke="#239fa3" stroke-width="1.8"/>
          <rect x="16.4" y="4.6" width="9.6" height="22.8" rx="2.4" fill="#e7fbfc" stroke="#239fa3" stroke-width="1.8"/>
          <path d="M25.6 15.4l4.2 4.2-6.4 6.4-4.4.4.4-4.4z" fill="#239fa3"/>
        </svg></button>
      <select class="rep-size" onchange="window.repSize(this.value)">
        ${[10, 25, 50, 100].map(n => `<option value="${n}"${n === size ? " selected" : ""}>${n}</option>`).join("")}
      </select>
      <span class="rep-count">${rows.length} ${esc(cfg.unit || "سجل")}</span>
    </div>

    <div class="pt-wrap"><div class="pt-scroll"><table class="ptable rep-table">
      <thead><tr>${head}</tr></thead><tbody>${body}</tbody>
    </table></div></div>
    ${pager}
  </div>`;
}

