function adminReports() {
  /* الفرع المطلوب من القائمة الجانبية: facilities | students | circles | recitation */
  const R = subParam("r");
  if (R === "facilities") return adminRepFacilities();
  if (R === "students")   return adminRepStudents();
  if (R === "circles")    return adminRepCircles();
  if (R === "recitation") return adminRepRecitation();
  const R_TITLE = { facilities: "تقارير المنشآت", students: "تقارير الطلاب / ات",
                    circles: "تقارير الحلقات", recitation: "سجل التسميع" };
  const R_KEEP = { facilities: ["المنشآت","المجمع","الحلقات"], students: ["الطلاب","الطالب"],
                   circles: ["الحلقات","الحلقة"], recitation: ["التسميع","الحفظ","المتأخرين"] };
  const reports = [
    { name: "تقرير الحضور اليومي", desc: "ملخص حضور وغياب الطلاب لليوم الحالي", date: "اليوم", ico: "attend", t: "t-teal" },
    { name: "تقرير تقدم الخطط", desc: "نسب إنجاز الخطط حسب البرنامج والمستوى", date: "اليوم", ico: "plan", t: "t-gold" },
    { name: "تقرير الطلاب المتأخرين", desc: "متأخرات الحفظ والتعويض المفتوحة", date: "اليوم", ico: "clock", t: "t-amber" },
    { name: "تقرير أداء المعلمين", desc: "الجلسات المعتمدة ومعدل الإنجاز", date: "هذا الأسبوع", ico: "teacher", t: "t-purple" },
    { name: "تقرير الحلقات", desc: "أداء الحلقات ونسب حضورها", date: "أمس", ico: "book", t: "t-teal" },
    { name: "تقرير الطلاب حسب البرنامج", desc: "توزيع الطلاب على البرامج القرآنية", date: "اليوم", ico: "layers", t: "t-blue" }
  ];

  const shown = R && R_KEEP[R]
    ? reports.filter(x => R_KEEP[R].some(k => (x.name + " " + x.desc).indexOf(k) > -1))
    : reports;
  const cards = shown.map(r => `<div class="card">
    <div style="display:flex;gap:11px;align-items:center;margin-bottom:11px">
      <div class="kpi-ico ${r.t}" style="margin:0">${ic(r.ico, 20)}</div>
      <div><strong style="font-size:14.5px">${esc(r.name)}</strong><div class="muted" style="font-size:11.5px">آخر إصدار: ${esc(r.date)}</div></div>
    </div>
    <p class="muted" style="font-size:13px;margin-bottom:14px">${esc(r.desc)}</p>
    <div class="row-actions">
      <button class="btn btn-soft btn-sm" data-action="modal-report" data-name="${esc(r.name)}">${ic("eye", 15)} عرض التقرير</button>
      <button class="btn btn-ghost btn-sm" data-action="export-report" data-name="${esc(r.name)}">${ic("download", 15)} تصدير</button>
    </div>
  </div>`).join("");
  return `<div class="page">
    ${pageHead(R_TITLE[R] || "التقارير والإحصائيات", "تقارير دورية وتفصيلية عن الحلقات والطلاب")}
    <div class="grid g-3 stagger">${cards}</div>
  </div>`;
}

