/* =========================================================================
   اعتماد الحلقة
   -------------------------------------------------------------------------
   يوثّق المعلّم إغلاق جلسة اليوم بعد استيفاء شروطها. السجل في مجموعة
   workflow — كانت معرَّفة في COLLECTIONS وفي القواعد بلا أي استعمال.

     workflow/<التاريخ>__<معرّف الحلقة>
     { id · type:"session" · date · circleId/circle · mosqueId · complexId
       students · present · absent · late · excused · recited
       by · byName · ts · status:"معتمدة" }

   المعرّف مركّب من التاريخ والحلقة، فالاعتماد المكرر يستبدل ولا يضاعف.
   والاعتماد يقفل التحضير: تعديل الحضور بعده يحتاج فتح الاعتماد أولاً،
   وهذا ما يمنع تغيير الحضور بأثر رجعي بلا أثر موثّق.
   ========================================================================= */

function sessionKey(dateISO, circleId) { return String(dateISO) + "__" + String(circleId); }

function sessionOf(dateISO, circleId) {
  const id = sessionKey(dateISO, circleId);
  return (Array.isArray(DB.workflow) ? DB.workflow : [])
    .find(x => x && x.type === "session" && String(x.id) === id) || null;
}

/* هل حلقة الطالب معتمدة اليوم؟ يُستعمل لقفل شاشة التحضير */
function studentSessionLocked(st, dateISO) {
  if (!st) return false;
  const cid = st.circleId || idByName("circles", st.circle || "");
  if (!cid) return false;
  return !!sessionOf(dateISO || attDate(), cid);
}

function circleStudentsOf(c) {
  return cur("students").filter(s =>
    studentCircleIds(s).indexOf(String(c.id)) > -1 ||
    String(s.circle || "") === String(c.name || ""));
}

/* حساب جاهزية الحلقة للاعتماد */
function sessionCheck(c, dateISO) {
  const studs = circleStudentsOf(c);
  /* جلسةُ هذه الحلقة وحدها: تحضيرُ الفجر لا يُكمل جلسةَ العصر، وتسميعُه
     لا يُحسب فيها — لكلّ فترةٍ شاشتُها وجلستُها */
  const att = attMap(dateISO, c.id);
  const marked = studs.filter(s => att[String(s.id)]);
  const present = marked.filter(s => {
    const st = att[String(s.id)].status;
    return st === "حاضر" || st === "متأخر";
  });

  const recs = (Array.isArray(DB.recitations) ? DB.recitations : [])
    .filter(r => String(r.date) === String(dateISO) &&
                 (!r.circleId || String(r.circleId) === String(c.id)));
  const recited = present.filter(s => recs.some(r => String(r.studentId) === String(s.id)));

  return {
    students: studs.length,
    marked: marked.length,
    present: present.length,
    absent:  studs.filter(s => (att[String(s.id)] || {}).status === "غائب").length,
    late:    studs.filter(s => (att[String(s.id)] || {}).status === "متأخر").length,
    excused: studs.filter(s => (att[String(s.id)] || {}).status === "مستأذن").length,
    recited: recited.length,
    attDone: studs.length > 0 && marked.length === studs.length,
    recDone: present.length === 0 || recited.length === present.length,
    empty: studs.length === 0
  };
}

/* =========================================================================
   الاعتماد التلقائيّ للمشرف
   -------------------------------------------------------------------------
   المشرفُ يعتمد بنفسه، فلا معنى لأن يحضّر ثمّ يضغط زرّاً ليعتمد ما حضّره.
   تُعتمد جلستُه من تلقائها متى اكتمل تحضيرُ طلابها.

   والمعلّمُ يبقى على حاله: يضغط الزرّ قصداً — لأن الاعتماد إقرارٌ منه أن
   يومه انتهى، وما بعده لا يُعدَّل إلا بفتحٍ من مشرفه.
   ========================================================================= */
window.autoApproveSet = function (on) {
  const st = DB.settings || (DB.settings = {});
  st.autoApprove = !!on;
  Promise.resolve(persistSet("settings", Object.assign({ id: "general" }, st)))
    .then(() => {
      showToast(on ? "ستُعتمد الجلسات تلقائياً عند اكتمال التحضير"
                   : "الاعتماد يدويٌّ الآن", "success");
      mount();
    });
};

function autoApproveOn() {
  const r = ((STATE && STATE.user) || {}).role || "";
  if (!isMgrRole(r) && r !== "admin" && r !== "owner") return false;
  return (DB.settings || {}).autoApprove !== false;      /* مفعّلٌ افتراضاً */
}

/* يُنادى بعد كلّ رصد حضور: إن اكتمل تحضيرُ الحلقة اعتُمدت */
function autoApproveCheck(circleId) {
  if (!autoApproveOn() || !circleId) return false;

  const day = attDate();
  if (typeof sessionOf === "function" && sessionOf(day, circleId)) return false;  /* معتمدةٌ سلفاً */

  const c = (cur("circles") || []).find(x => String(x.id) === String(circleId));
  if (!c) return false;

  let k = null;
  try { k = sessionCheck(c, day); } catch (e) { return false; }
  if (!k || k.empty || !k.attDone) return false;

  approveSession(circleId, true);
  return true;
}

function approveSession(circleId, auto) {
  const dateISO = attDate();
  const c = DB.circles.find(x => String(x.id) === String(circleId));
  if (!c) { showToast("الحلقة غير موجودة", "warn"); return; }

  const k = sessionCheck(c, dateISO);
  /* التلقائيُّ يصمت: النداءُ يجري بعد كلّ رصدٍ، فالتنبيهُ يتكرّر بلا داعٍ */
  if (k.empty)    { if (!auto) showToast("لا يوجد طلاب في هذه الحلقة", "warn"); return; }
  if (!k.attDone) { if (!auto) showToast("أكمل تحضير جميع الطلاب أولاً", "warn"); return; }

  const u = (STATE && STATE.user) || {};
  const rec = {
    id: sessionKey(dateISO, c.id),
    type: "session",
    date: dateISO,
    circleId: String(c.id), circle: c.name || "",
    mosqueId: c.mosqueId || "", complexId: c.complexId || STATE.complexId,
    students: k.students, present: k.present, absent: k.absent,
    late: k.late, excused: k.excused, recited: k.recited,
    by: u.email || "", byName: u.name || "", ts: Date.now(),
    status: "معتمدة",
    auto: !!auto                       /* يُعرف في السجلّ أنه اعتمادٌ تلقائيّ */
  };

  if (!Array.isArray(DB.workflow)) DB.workflow = [];
  const i = DB.workflow.findIndex(x => String(x.id) === rec.id);
  if (i > -1) DB.workflow[i] = rec; else DB.workflow.push(rec);
  persistSet("workflow", rec);
  mount();
  showToast(auto ? "اكتمل التحضير — اعتُمدت حلقة " + (c.name || "") + " تلقائياً"
                 : "اعتُمدت حلقة " + (c.name || ""),
            auto ? "success" : undefined);
}

/* =========================================================================
   فتح الاعتماد
   -------------------------------------------------------------------------
   كان يُفتح بنقرةٍ بلا حارس: أيّ معلّمٍ يفتح جلسةً معتمدة ويعدّلها، ولا
   يُعرف من فتحها ولا لماذا. والاعتماد الذي يُفتح بنقرة ليس اعتماداً.

   الفتح الآن للإدارة، بسببٍ يُذكر، ويُرصد في سجل العمليات. والمعلّم يطلبه
   ولا يملكه — فمن أغلق جلسته لا يفتحها ليصحّح ما بدا له بعد يوم.
   ========================================================================= */
function canReopenSession() {
  const r = ((STATE && STATE.user) || {}).role || "";
  return r === "owner" || r === "admin" || isMgrRole(r);
}

function unapproveSession(circleId) {
  if (!canReopenSession()) {
    showToast("فتح الاعتماد للإدارة — راجع مشرفك", "warn");
    return;
  }

  const c = (cur("circles") || []).find(x => String(x.id) === String(circleId));
  const sess = sessionOf(attDate(), circleId);
  if (!sess) { showToast("لا اعتماد مفتوحاً لهذه الحلقة", "warn"); return; }

  openModal("فتح اعتماد الجلسة", (c && c.name) || "",
    `<input type="hidden" id="uas_cid" value="${jsAttr(circleId)}">
     ${noteCard(`اعتُمدت هذه الجلسة بواسطة <strong>${esc(sess.byName || sess.by || "—")}</strong>.
       <br>فتحها يتيح تعديل التحضير والتسميع — ويُرصد باسمك وسببه.`)}
     <div class="form-grid">
       <div class="field full"><label>سبب الفتح <span class="req">*</span></label>
         <input id="uas_why" placeholder="مثال: خطأ في تحضير طالب"></div>
     </div>`,
    `<button class="btn btn-danger" onclick="window.unapproveSessionDo()">فتح الاعتماد</button>
     <button class="btn btn-ghost" data-action="close-modal">إلغاء</button>`);
}

window.unapproveSessionDo = function () {
  const circleId = val("#uas_cid");
  const why = (val("#uas_why") || "").trim();
  if (!why) { showToast("السبب مطلوب — يُرصد مع الفتح", "warn"); return; }

  const id = sessionKey(attDate(), circleId);
  const sess = sessionOf(attDate(), circleId);
  const c = (cur("circles") || []).find(x => String(x.id) === String(circleId));

  DB.workflow = (Array.isArray(DB.workflow) ? DB.workflow : []).filter(x => String(x.id) !== id);
  persistDelete("workflow", id);

  /* الفتح يُرصد بنصٍّ صريح: من فتح ومتى ولماذا وماذا كانت أرقامه */
  try {
    const me = (STATE && STATE.user) || {};
    const rec = {
      id: "lg" + Date.now() + "-uas",
      ts: Date.now(), act: "delete", coll: "workflow", collAr: "اعتماد الجلسات",
      docId: id, subject: (c && c.name) || "",
      by: me.name || me.email || "—",
      role: typeof logRoleAr === "function" ? logRoleAr(me.role) : "",
      changes: [{ k: "status", h: "الاعتماد", from: "معتمدة", to: "مفتوحة" }],
      text: "فتح " + ((typeof logRoleAr === "function" ? logRoleAr(me.role) : "") || "") +
            " (" + (me.name || "—") + ") اعتمادَ حلقة «" + ((c && c.name) || "") +
            "» — السبب: " + why +
            (sess ? " · كانت: حاضر " + (sess.present || 0) + " · غائب " + (sess.absent || 0) : "")
    };
    if (!Array.isArray(DB.auditLog)) DB.auditLog = [];
    DB.auditLog.push(rec);
    const db = typeof FDB === "function" ? FDB() : null;
    if (db) db.collection("auditLog").doc(rec.id).set(rec).catch(() => {});
  } catch (e) {}

  closeModal();
  showToast("فُتح الاعتماد — التعديل متاح الآن", "info");
  mount();
};

function teacherApprove() {
  const dateISO = attDate();
  const isToday = dateISO === todayISO();
  const circles = cur("circles");

  if (!circles.length) {
    return `<div class="page">
      ${pageHead("اعتماد الحلقة", "راجع قائمة التحقق قبل اعتماد جلسة اليوم")}
      <div class="card">${emptyState("لا توجد حلقات مسندة لحسابك",
        "راجع الإدارة لربط حسابك بحلقة.")}</div></div>`;
  }

  const cards = circles.map(c => {
    const k = sessionCheck(c, dateISO);
    const done = sessionOf(dateISO, c.id);

    const item = (ok, label, detail) => `<div class="apv-item ${ok ? "ok" : "no"}">
      <span class="apv-tick">${ic(ok ? "checkCircle" : "alert", 17)}</span>
      <div><strong>${esc(label)}</strong>
        <div class="muted" style="font-size:12px">${esc(detail)}</div></div>
    </div>`;

    const checks = k.empty
      ? `<div class="muted" style="padding:12px">لا يوجد طلاب في هذه الحلقة.</div>`
      : item(k.attDone, "تحضير جميع الطلاب",
             k.attDone ? "سُجّل " + k.marked + " من " + k.students
                       : "باقٍ " + (k.students - k.marked) + " طالباً بلا حالة حضور") +
        item(k.recDone, "تسميع الحاضرين",
             k.present === 0 ? "لا يوجد حاضرون اليوم"
             : k.recDone ? "سُجّل تسميع " + k.recited + " من " + k.present
                         : "باقٍ " + (k.present - k.recited) + " من الحاضرين بلا تسميع");

    const stats = k.empty ? "" : `<div class="apv-stats">
      <span class="chip t-green">حاضر: ${k.present}</span>
      <span class="chip t-amber">متأخر: ${k.late}</span>
      <span class="chip t-blue">مستأذن: ${k.excused}</span>
      <span class="chip t-red">غائب: ${k.absent}</span>
      <span class="chip">تسميع: ${k.recited}</span>
    </div>`;

    const foot = done
      ? `<div class="apv-done">
          <div>${ic("checkCircle", 18)}
            <strong>اعتُمدت</strong>
            <span class="muted">${esc(done.byName || done.by || "")} — ${new Date(done.ts).toLocaleTimeString("ar-EG", { hour: "2-digit", minute: "2-digit" })}</span>
          </div>
          <button class="btn btn-ghost btn-sm" data-action="sess-open" data-id="${esc(String(c.id))}">فتح الاعتماد</button>
        </div>`
      : `<div class="row-actions" style="justify-content:flex-end">
          ${!k.attDone && !k.empty ? `<button class="btn btn-ghost btn-sm" data-action="nav" data-page="attendance">${ic("attend", 15)} أكمل التحضير</button>` : ""}
          ${!k.recDone && k.attDone ? `<button class="btn btn-ghost btn-sm" data-action="nav" data-page="recite">${ic("pen", 15)} سجّل التسميع</button>` : ""}
          <button class="btn btn-primary btn-sm" data-action="sess-approve" data-id="${esc(String(c.id))}"
            ${k.attDone && !k.empty ? "" : "disabled"}>${ic("check", 15)} اعتماد الحلقة</button>
        </div>`;

    return `<div class="card apv-card ${done ? "approved" : ""}">
      <div class="section-head">
        <h3>${esc(c.name || "—")}</h3>
        <span class="badge ${done ? "b-green" : "b-gold"}">${done ? "معتمدة" : "بانتظار الاعتماد"}</span>
      </div>
      <div class="muted" style="font-size:12.5px;margin-bottom:12px">${esc(c.mosque || "—")} — ${k.students} طالب</div>
      ${stats}
      <div class="apv-checks">${checks}</div>
      ${foot}
    </div>`;
  }).join("");

  const nDone = circles.filter(c => sessionOf(dateISO, c.id)).length;

  return `<div class="page">
    ${pageHead("اعتماد الحلقة", "راجع قائمة التحقق قبل اعتماد جلسة اليوم")}
    <div class="section-head" style="align-items:center">
      <h3>${isToday ? "جلسة اليوم" : "جلسة " + esc(dateISO)}</h3>
      <div class="row-actions">
        <span class="badge b-gold">${nDone} من ${circles.length} معتمدة</span>
        <button class="btn btn-ghost btn-sm" data-action="att-shift" data-days="-1">اليوم السابق</button>
        <button class="btn btn-ghost btn-sm" data-action="att-shift" data-days="1" ${isToday ? "disabled" : ""}>اليوم التالي</button>
      </div>
    </div>
    <div class="grid g-2" style="align-items:start">${cards}</div>
  </div>`;
}


/* =========================================================
   STUDENT INTERFACE
   ========================================================= */
/* =========================================================================
   واجهة الطالب / ولي الأمر
   -------------------------------------------------------------------------
   كانت ست شاشات من سبع بطاقة «قريباً». هذه بنيتها حسب وثيقة المتطلبات:
   الواجب اليومي · واجب الغد · تقدم الخطة · سجل الحضور · نتائج التسميع.

   حساب ولي الأمر قد يضم أكثر من ابن، فيظهر له مبدّل بينهم في أعلى الصفحة
   (myStudents تُرجع كل من ارتبط بالحساب)، ولا يظهر المبدّل لابن واحد.
   ========================================================================= */

/* الطالب المعروض حالياً — الأول افتراضاً، ويبدّله وليّ الأمر */
function activeStudent() {
  const { ids } = myStudents();
  const list = (Array.isArray(DB.students) ? DB.students : [])
    .filter(s => ids.has(String(s.id)));
  if (!list.length) return null;
  if (STATE.kid) {
    const k = list.find(s => String(s.id) === String(STATE.kid));
    if (k) return k;
  }
  return list[0];
}

window.pickKid = function (id) { STATE.kid = String(id); mount(); };
window.resFilter = function (v) { STATE.resFilter = v || ""; mount(); };

function kidSwitcher() {
  const { ids } = myStudents();
  const list = (Array.isArray(DB.students) ? DB.students : []).filter(s => ids.has(String(s.id)));
  if (list.length < 2) return "";
  const cur2 = activeStudent();
  return `<div class="kid-bar">
    <span class="kid-lbl">الابن</span>
    ${list.map(s => `<button type="button" class="kid-chip ${cur2 && String(cur2.id) === String(s.id) ? "on" : ""}"
      onclick="window.pickKid('${esc(String(s.id))}')">
      <span class="kid-av">${initials(s.name)}</span>${esc(s.name)}</button>`).join("")}
  </div>`;
}

/* رسالة موحّدة عند غياب الربط */
function noKidPage(title, sub) {
  return `<div class="page">${pageHead(title, sub)}
    <div class="card">${emptyState("لا يوجد طالب مرتبط بحسابك",
      "لم تربط الإدارة حسابك بملف طالب بعد. راجع إدارة المجمع أو المسجد.")}</div></div>`;
}

/* خطة الطالب النشطة */
/* نسخة الطالب من البحث عن الخطة كانت مستقلة عن planOfStudent ولا تدمج
   بيانات الانتظار القديمة، فيرى المعلّم الواجب مطبَّقاً ولا يراه الطالب.
   صارت الدالتان واحدة. */
function studentPlan(st) { return planOfStudent(st); }

/* تسميعات الطالب مرتبة من الأحدث */
function studentRecs(st) {
  if (!st) return [];
  return (Array.isArray(DB.recitations) ? DB.recitations : [])
    .filter(r => String(r.studentId) === String(st.id))
    .sort((a, b) => (b.ts || 0) - (a.ts || 0));
}

/* حضور الطالب في شهر بعينه */
function studentAtt(st, ym) {
  if (!st) return [];
  return (Array.isArray(DB.attendance) ? DB.attendance : [])
    .filter(r => String(r.studentId) === String(st.id) &&
                 (!ym || String(r.date).slice(0, 7) === ym));
}

/* ==================== ١) الواجب اليومي / لوحة الطالب ==================== */

function dutyCard(kind, tint, icon, title, body, extra) {
  return `<div class="duty ${tint}">
    <div class="duty-top"><span class="duty-ico">${ic(icon, 20)}</span>
      <strong>${esc(title)}</strong></div>
    <div class="duty-body">${body}</div>
    ${extra || ""}
  </div>`;
}

/* =========================================================================
   واجبات الطالب — من المحرّك لا من حسابٍ موازٍ
   -------------------------------------------------------------------------
   كانت هذه الدالة تحسب الواجبات بمنطقها الخاص: تقرأ التسميعات وتأخذ آخر
   خمسة دروس للتثبيت، وتعدّ «أياماً حضر فيها بلا تسميع» متأخّرات.

   والمعلّم يرى assignments المولَّدة من المحرّك. فنظامان متوازيان لشيء
   واحد: الطالب يرى واجباً والمعلّم يرى آخر، وقواعد الخطة كلها — التعويض
   والإعادة والتجميد وعدد دروس التثبيت لكلّ طالب — لا تصل الطالب إطلاقاً.

   الشكل باقٍ كما هو (بطاقات duty-grid)؛ المصدر وحده تغيّر.
   ========================================================================= */
function studentDuties(st, forTomorrow) {
  const p = studentPlan(st);
  if (!p) {
    /* تشخيص صريح بدل رسالة عامة: هل المشكلة أنه لا خطة أصلاً، أم أن
       خطةً موجودة باسم قريب ولم تُربَط؟ */
    const near = (Array.isArray(DB.plans) ? DB.plans : [])
      .filter(x => x && !x.studentId && x.student);
    const hint = near.length
      ? `<div class="muted" style="font-size:12.5px;margin-top:10px">
           توجد ${toArabicDigits(near.length)} خطة غير مرتبطة بطالب — أبلغ معلمك ليعيد حفظها.
         </div>` : "";
    return `<div class="card">${emptyState("لا توجد خطة قرآنية بعد",
      "لم تُسند لك خطة حتى الآن. راجع معلمك.")}${hint}</div>`;
  }

  /* الخطة المجمَّدة لا واجب فيها — وهذا ما لم يكن الطالب يعلمه */
  if (p.frozen) {
    return `<div class="card">${emptyState("خطتك متوقّفة مؤقتاً",
      "أوقف معلمك خطتك" + (p.freezeReason ? " بسبب: " + p.freezeReason : "") +
      ". لا واجب عليك حتى تُستأنف.")}</div>`;
  }

  const today = todayISO();
  const day = forTomorrow ? nextDayISO(today) : today;

  /* واجبات اليوم من المحرّك نفسه الذي يراه المعلّم.
     لا تُحفظ من شاشة الطالب: العرض لا يكتب. */
  let list = [];
  try { list = generateAssignments(st.id, day) || []; } catch (e) { list = []; }

  const TINT = { hifz: "t-green", fix: "t-amber", rev: "t-blue", tilawah: "t-purple" };
  const ICON = { hifz: "book", fix: "refresh", rev: "list", tilawah: "book" };

  const rangeText = a => {
    if (!a.fromS) return "";
    const from = surahName(a.fromS) + " " + toArabicDigits(a.fromA);
    if (!a.toS) return from + " فما بعدها";
    return from + " — " + surahName(a.toS) + " " + toArabicDigits(a.toA);
  };

  /* القفل يُقال للطالب أيضاً — هو صاحب الدَّين */
  const stLock = hifzLocked(st.id, day);
  const stLockBox = stLock
    ? `<div class="duty late" style="margin-bottom:14px">
        <div class="duty-top"><span class="duty-ico">${ic("lock", 20)}</span>
          <strong>حفظك الجديد متوقّف</strong></div>
        <div class="duty-body"><div class="duty-sum">${esc(stLock.text)}.</div>
          <div class="duty-sum" style="margin-top:6px">
            سمّع ما فاتك ليُفتح لك الحفظ الجديد.</div></div></div>`
    : "";

  const cards = list.length ? list.map(a => {
    const base = String(a.kind).replace("_makeup", "");
    const range = rangeText(a);

    const body = range
      ? `<strong class="duty-range">${esc(range)}</strong>` +
        (a.qty ? `<div class="duty-sum">المقدار: ${toArabicDigits(a.qty)} ${esc(a.unit || "")}</div>` : "") +
        (a.note ? `<div class="duty-sum">${esc(a.note)}</div>` : "")
      : (a.note
          ? `<span class="muted">${esc(a.note)}</span>`
          : `<span class="muted">لم يُحدَّد موضعه بعد — يحدّده معلمك.</span>`);

    const extra = a.status === "done"
      ? `<span class="duty-done">${ic("checkCircle", 15)} سُمِّع${
          a.score != null ? " · " + toArabicDigits(a.score) + "٪" : ""}</span>`
      : a.status === "failed"
        ? `<span class="duty-done" style="color:#b3261e">${ic("alert", 15)} يُعاد غداً</span>`
        : "";

    return dutyCard(base, TINT[base] || "t-teal", ICON[base] || "book",
      (forTomorrow ? "غداً: " : "") + (a.kindName || base) +
      (a.isRepeat ? " — إعادة " + toArabicDigits(a.round || 1) + "/" +
                    toArabicDigits(a.ofRounds || 1) : ""),
      body, extra);
  }).join("")
    : `<div class="card" style="grid-column:1/-1">${emptyState(
        forTomorrow ? "لا واجب غداً" : "لا واجب اليوم",
        "ليس من أيام دوامك، أو لم تُجدوَل لك واجبات في هذا اليوم.")}</div>`;

  /* المتأخّرات من المحرّك: ما لم يُسمَّع ولم يُسوَّ */
  let debts = [];
  try { debts = asgDebts(st.id).filter(a => String(a.date) !== String(day)); } catch (e) {}

  const lateBox = debts.length
    ? `<div class="duty late">
        <div class="duty-top"><span class="duty-ico">${ic("alert", 20)}</span>
          <strong>مطلوب منك تعويضه</strong></div>
        <div class="duty-body">
          <div class="duty-sum">${toArabicDigits(debts.length)} ${
            debts.length === 1 ? "واجب" : "واجبات"} لم تُسمَّع بعد:</div>
          <div class="duty-list">${debts.slice(0, 6).map(a =>
            `<span class="duty-item">${esc(a.kindName || a.kind)} · ${esc(a.date)}</span>`).join("")}</div>
          ${debts.length > 6 ? `<div class="duty-sum">و${toArabicDigits(debts.length - 6)} غيرها</div>` : ""}
          <div class="duty-sum" style="margin-top:8px">لن تتقدّم خطتك حتى تُنجزها.</div>
        </div>
      </div>`
    : "";

  const noteBox = p.note
    ? `<div style="height:14px"></div>${noteCard("<strong>ملاحظة معلمك:</strong> " + esc(p.note))}` : "";

  /* ثلاثةٌ تُعرض قبل الواجبات:
       • قفل الحفظ إن كان على الطالب دَينٌ مصيريّ — وإلا حار لِمَ لا حفظ له.
       • النصاب: ما أُنجز وما بقي لكلّ نوع.
       • زرّ المقرأة إن فُعّلت لحلقته. */
  const stCircle = (cur("circles") || []).find(c =>
    String(c.id) === String(st.circleId) || String(c.name) === String(st.circle));
  const maqBox = (stCircle && typeof maqraahBtn === "function") ? maqraahBtn(stCircle) : "";

  /* خطٌّ أكبر وأزرارٌ أوسع — الصنف يُحقن على الحاوية */
  const elderCls = typeof elderClass === "function" ? elderClass(st) : "";

  return `<div class="duty-wrap${elderCls}">${stLockBox}${quotaCard(st.id, day)}${
    maqBox ? `<div style="margin-bottom:14px">${maqBox}</div>` : ""
  }<div class="duty-grid">${cards}</div>${noteBox}${
    lateBox ? `<div style="height:14px"></div>${lateBox}` : ""}</div>`;
}

/* تاريخ الغد */
function nextDayISO(dateISO) {
  const d = new Date(String(dateISO) + "T00:00:00");
  if (isNaN(d.getTime())) return dateISO;
  d.setDate(d.getDate() + 1);
  return d.toISOString().slice(0, 10);
}


function studentToday() {
  const st = activeStudent();
  if (!st) return noKidPage("واجب اليوم", "");
  return `<div class="page">${(STATE.user||{}).role === "parent" ? kidsBar() : ""}
    ${pageHead("واجب اليوم", esc(st.name) + " — " + esc(st.circle || "بلا حلقة"))}
    ${kidSwitcher()}
    ${studentDuties(st, false)}
    <div style="height:16px"></div>
    <div class="row-actions">
      <button class="btn btn-ghost btn-sm" data-action="nav" data-page="mushaf">${ic("book", 15)} افتح المصحف</button>
      <button class="btn btn-ghost btn-sm" data-action="nav" data-page="results">${ic("report", 15)} نتائج تسميعي</button>
      <button class="btn btn-ghost btn-sm" data-action="nav" data-page="tomorrow">${ic("calendar", 15)} واجب الغد</button>
    </div>
  </div>`;
}

function studentTomorrow() {
  const st = activeStudent();
  if (!st) return noKidPage("واجب الغد", "");
  return `<div class="page">
    ${pageHead("واجب الغد", "استعد لجلسة الغد")}
    ${kidSwitcher()}
    ${noteCard("واجب الغد مبنيٌّ على جدولة خطتك، وقد يتغيّر بحسب تقييم اليوم: دون حدّ الاعتماد يُعاد الواجب نفسه.")}
    <div style="height:14px"></div>
    ${studentDuties(st, true)}
    <div style="height:16px"></div>
    <div class="row-actions">
      <button class="btn btn-ghost btn-sm" data-action="nav" data-page="today">${ic("book", 15)} واجب اليوم</button>
      <button class="btn btn-ghost btn-sm" data-action="nav" data-page="progress">${ic("target", 15)} تقدم خطتي</button>
    </div>
  </div>`;
}

/* ==================== ٢) لوحة الطالب ==================== */

/* =========================================================================
   واجهة وليّ الأمر
   -------------------------------------------------------------------------
   متابعةٌ لا إدارة: يرى ابنه ولا يعدّل شيئاً من خطّته ولا حضوره.

   وشاشاتُ الطالب تُعاد هنا بمنظورٍ آخر: البياناتُ واحدةٌ والمخاطَبُ مختلف.
   فلا تُكتب مرّتين ولا تفترقان بتعديلٍ في إحداهما.
   ========================================================================= */

/* أبناء وليّ الأمر — من ربط الحساب بالطلاب */
function myKids() {
  const { ids } = myStudents();
  return (Array.isArray(DB.students) ? DB.students : [])
    .filter(s => ids.has(String(s.id)));
}

/* شريط تبديل الأبناء — kidSwitcher مبنيّةٌ من قبل، فلا تُكتب ثانيةً:
   نسختان لشيءٍ واحد تفترقان بأوّل تعديلٍ في إحداهما. */
function kidsBar() {
  return typeof kidSwitcher === "function" ? kidSwitcher() : "";
}

/* لوحة وليّ الأمر: بطاقةٌ لكلّ ابنٍ فيها حاله اليوم */
function parentDashboard() {
  const kids = myKids();

  if (!kids.length) {
    return `<div class="page">
      ${pageHead("متابعة الأبناء", "")}
      <div class="card">${emptyState("لم يُربط بك طالبٌ بعد",
        "راجع إدارة الحلقة لربط حسابك بأبنائك.")}</div>
    </div>`;
  }

  const day = todayISO();

  const cards = kids.map(k => {
    const att = (cur("attendance") || []).find(a =>
      !a.staffId && String(a.studentId) === String(k.id) && String(a.date) === day);

    const asgs = todayAssignments(k.id, day, true) || [];
    const done = asgs.filter(a => a.status === "done").length;

    const pl = (cur("plans") || []).find(p => String(p.studentId) === String(k.id));
    let prog = null;
    try { prog = pl && typeof levelProgress === "function" ? levelProgress(pl) : null; } catch (e) {}

    const debts = (typeof asgDebts === "function" ? asgDebts(k.id) : []).length;

    const TINT = { "حاضر": "b-green", "متأخر": "b-amber",
                   "غائب": "b-red", "مستأذن": "b-blue" };

    return `<div class="card kid-card">
      <div class="kid-head">
        <div class="mini-avatar lg">${initials(k.name)}</div>
        <div>
          <strong>${esc(k.name || "—")}</strong>
          <div class="muted" style="font-size:12px">
            ${esc(k.circle || "بلا حلقة")}${k.level ? " · " + esc(k.level) : ""}</div>
        </div>
        ${att ? badge(esc(att.status), TINT[att.status] || "b-gray")
              : badge("لم يُحضَّر بعد", "b-gray")}
      </div>

      <div class="kid-stats">
        <div><b>${toArabicDigits(done)} / ${toArabicDigits(asgs.length)}</b>
          <span>واجبات اليوم</span></div>
        <div><b>${prog ? toArabicDigits(prog.pct) + "٪" : "—"}</b>
          <span>تقدّم المستوى</span></div>
        <div class="${debts ? "warn" : ""}"><b>${toArabicDigits(debts)}</b>
          <span>متأخّرات</span></div>
      </div>

      ${att && att.leftAt
        ? `<div class="left-tag">غادر ${esc(att.leftAt)}${
            att.attendedPct != null ? " · حضر " + toArabicDigits(att.attendedPct) + "٪" : ""}</div>`
        : ""}

      <div class="kid-acts">
        <button class="btn btn-soft btn-sm"
          onclick="window.pickKid('${jsAttr(k.id)}');window.go('parent/today')">واجب اليوم</button>
        <button class="btn btn-ghost btn-sm"
          onclick="window.pickKid('${jsAttr(k.id)}');window.go('parent/results')">نتائجه</button>
      </div>
    </div>`;
  }).join("");

  return `<div class="page">
    ${pageHead("متابعة الأبناء",
      toArabicDigits(kids.length) + (kids.length === 1 ? " ابن" : " أبناء"))}
    <div class="grid g-2" style="align-items:start">${cards}</div>
  </div>`;
}

/* مراسلة المعلّم — قناةٌ واحدةٌ موثّقة بدل الجوّال */
function parentMessages() {
  const st = activeStudent();
  if (!st) return `<div class="page">${pageHead("مراسلة المعلّم", "")}
    <div class="card">${emptyState("لم يُربط بك طالب", "")}</div></div>`;

  const tName = st.teacher || "معلّم الحلقة";
  const list = typeof myMessages === "function" ? myMessages() : [];

  const rows = list.length ? list.slice(0, 30).map(m => `<div class="msg-row${
      m.read ? "" : " unread"}">
      <div class="msg-top">
        <strong>${esc(m.title || m.fromName || "رسالة")}</strong>
        <span class="muted">${typeof timeAgo === "function" ? timeAgo(m.ts) : ""}</span>
      </div>
      <div class="msg-body">${esc(m.text || "")}</div>
    </div>`).join("")
    : emptyState("لا رسائل بعد", "ما يصلك من معلّم ابنك أو الإدارة يظهر هنا.");

  return `<div class="page">
    ${pageHead("مراسلة المعلّم", esc(st.name || ""))}
    ${kidsBar()}

    <div class="card">
      <div class="fac-toolbar">
        <div><strong style="font-size:15px">إلى ${esc(tName)}</strong>
          <div class="muted" style="font-size:11.5px;margin-top:2px">
            رسالتك تصل معلّم الحلقة والإدارة</div></div>
      </div>
      <div class="form-grid" style="padding:0 16px 16px">
        <div class="field full"><label>الرسالة</label>
          <textarea id="pmText" rows="3"
            placeholder="استفسارٌ عن حفظه · اعتذارٌ عن يوم · طلب موعد"></textarea></div>
      </div>
      <div class="pnl-actions">
        <button class="btn btn-primary" onclick="window.parentSend()">إرسال</button>
      </div>
    </div>

    <div class="card" style="margin-top:16px">
      <div class="fac-toolbar">
        <div><strong style="font-size:15px">ما وصلك</strong></div>
      </div>
      <div style="padding:0 16px 16px">${rows}</div>
    </div>
  </div>`;
}

window.parentSend = function () {
  const st = activeStudent();
  const txt = (val("#pmText") || "").trim();
  if (!txt) { showToast("اكتب رسالتك أولاً", "warn"); return; }
  if (!st) return;

  const u = (STATE && STATE.user) || {};
  const rec = {
    id: "pm" + Date.now(),
    kind: "parent",
    fromUid: String(u.uid || u.id || ""),
    fromName: u.name || "وليّ الأمر",
    toId: String(st.teacherId || ""),
    toEmail: "",
    title: "رسالة من وليّ أمر " + (st.name || ""),
    text: txt,
    studentId: String(st.id),
    student: st.name || "",
    circleId: String(st.circleId || ""),
    ts: Date.now(), read: false
  };

  if (!Array.isArray(DB.site_messages)) DB.site_messages = [];
  DB.site_messages.push(rec);

  Promise.resolve(persistSet("site_messages", rec)).then(() => {
    /* تُرسَل للإدارة كذلك: المعلّم قد لا يفتح النظام اليوم */
    try {
      if (typeof pushNotif === "function") {
        pushNotif({
          key: "pmsg|" + rec.id,
          toRole: "supervisor",
          title: "رسالة من وليّ أمر",
          text: (u.name || "وليّ أمر") + " بشأن " + (st.name || "") + ": " +
                txt.slice(0, 60) + (txt.length > 60 ? "…" : ""),
          type: "info", label: "رسالة"
        });
      }
    } catch (e) {}

    const t = document.getElementById("pmText");
    if (t) t.value = "";
    showToast("وصلت رسالتك", "success");
    mount();
  });
};

/* =========================================================================
   الملفّ التعريفيّ للطالب
   -------------------------------------------------------------------------
   نظامُ الصور مبنيٌّ في ملفّات الإدارة، والطالبُ لا يملك رفعَ صورته: يراها
   في ملفّه وقد وضعتها الإدارة، أو لا يرى شيئاً.

   يرفعها بنفسه هنا — وصورتُه وحدها. أمّا اسمُه وحلقتُه ومستواه فعرضٌ لا
   تعديل: بياناتٌ تُسند إليه ولا يُسندها لنفسه.
   ========================================================================= */
function studentProfileCard(st) {
  if (!st) return "";

  const me = (STATE && STATE.user) || {};
  /* وليُّ الأمر يرفع لأبنائه كذلك — هو من يملك صورَهم غالباً */
  const canEdit = me.role === "student" || me.role === "parent";

  const pl = (cur("plans") || []).find(p => String(p.studentId) === String(st.id));
  const bits = [
    ["الحلقة",  st.circle  || "—"],
    ["المعلّم", st.teacher || "—"],
    ["البرنامج", (pl && pl.program) || st.program || "—"],
    ["المستوى", (pl && pl.level) || st.level || "—"]
  ];

  return `<div class="card stp-card">
    <div class="stp-top">
      <div class="stp-av" id="stp_av">${st.photo
        ? `<img src="${esc(st.photo)}" alt="">`
        : `<span>${initials(st.name)}</span>`}</div>

      <div class="stp-id">
        <strong>${esc(st.name || "—")}</strong>
        <div class="muted">${esc(st.mosque || st.circle || "")}</div>
        ${canEdit ? `<div class="stp-acts">
          <button class="btn btn-soft btn-sm"
            onclick="document.getElementById('stp_input').click()">
            ${ic("plus", 14)} ${st.photo ? "تغيير الصورة" : "إضافة صورة"}</button>
          ${st.photo ? `<button class="btn btn-ghost btn-sm"
            onclick="window.pfClear('students','${jsAttr(st.id)}')">${ic("x", 14)} إزالة</button>` : ""}
        </div>` : ""}
      </div>
    </div>

    <div class="stp-bits">
      ${bits.map(([h, v]) => `<div><span>${esc(h)}</span><b>${esc(v)}</b></div>`).join("")}
    </div>

    ${canEdit ? `<input type="file" id="stp_input" accept="image/*" style="display:none"
      onchange="window.pfPick(this, 'students', '${jsAttr(st.id)}')">` : ""}
  </div>`;
}

/* رفعُ صورة الطالب صار في pfPick المشتركة مع المعلّم: نسختان لشيءٍ
   واحد تفترقان بأوّل تعديلٍ في إحداهما. */

function studentDashboard() {
  const st = activeStudent();
  if (!st) return noKidPage("لوحة الطالب", "");

  const recs = studentRecs(st);
  const att  = studentAtt(st);
  const p    = studentPlan(st);

  const n = s => att.filter(r => r.status === s).length;
  const present = n("حاضر"), late = n("متأخر"), excused = n("مستأذن"), absent = n("غائب");
  const total = att.length;
  const pct = v => total ? Math.round(v / total * 100) : 0;

  const faces = recs.reduce((a, r) => a + (Number(r.faces) || 0), 0);
  const prog = Number(p && p.progress) || 0;

  const attRows = [
    { cls: "att-present", ico: "check", label: "الحضور", num: present, pct: pct(present), head: true },
    { cls: "att-late",    ico: "eye",   label: "التأخير", num: late,    pct: pct(late) },
    { cls: "att-excused", ico: "eye",   label: "مستأذن",  num: excused, pct: pct(excused) },
    { cls: "att-absent",  ico: "x",     label: "غياب",    num: absent,  pct: pct(absent) }
  ].map(r => `<div class="att-row ${r.cls}${r.head ? " att-row-head" : ""}">
      <div class="ar-right"><span class="ar-ico">${ic(r.ico, r.head ? 22 : 20)}</span><span class="ar-label">${r.label}</span><span class="ar-count">(${r.num})</span></div>
      <span class="ar-pct">${r.pct}%</span></div>`).join("");

  const cards = [
    { tint: "t-green",  icon: "book",   num: faces,        label: "أوجه محفوظة", page: "results" },
    { tint: "t-blue",   icon: "pen",    num: recs.length,  label: "جلسات تسميع", page: "results" },
    { tint: "t-purple", icon: "target", num: prog,         label: "% من الخطة",  page: "progress" },
    { tint: "t-amber",  icon: "star",   num: Number(st.points) || 0, label: "نقاطي", page: "progress" }
  ].map(f => `<button type="button" class="facility-card ${f.tint}" data-action="nav" data-page="${f.page}">
      <div class="fc-num">${f.num}</div>
      <div class="fc-body"><span class="fc-ico">${ic(f.icon, 22)}</span><span class="fc-label">${f.label}</span></div>
    </button>`).join("");

  const circ = 2 * Math.PI * 52;
  const donut = `<div class="donut-wrap">
    <svg class="donut" viewBox="0 0 130 130">
      <circle cx="65" cy="65" r="52" fill="none" stroke="var(--border-soft)" stroke-width="12"/>
      <circle cx="65" cy="65" r="52" fill="none" stroke="var(--brand-main)" stroke-width="12" stroke-linecap="round" stroke-dasharray="${circ.toFixed(1)}" stroke-dashoffset="${(circ * (1 - prog / 100)).toFixed(1)}" transform="rotate(-90 65 65)"/>
      <text class="donut-num" x="65" y="72" text-anchor="middle">${prog}%</text>
    </svg>
    <div class="donut-label">إنجاز الخطة</div>
  </div>`;

  const last = recs.slice(0, 5);
  const lastRows = last.length ? last.map(r => `<div class="list-row">
      <div class="mini-avatar">${ic("pen", 15)}</div>
      <div style="flex:1"><strong style="font-size:13.5px">${esc(r.kind)} — ${esc(r.fromName)} ${toArabicDigits(r.fromA)}</strong>
        <div class="muted" style="font-size:12px">${esc(r.date)}${r.faces ? " · " + r.faces + " وجه" : ""}</div></div>
      <span class="chip ${GRADE_TINT[r.grade] || ""}">${esc(r.grade || "—")}</span>
    </div>`).join("")
    : `<div class="muted" style="padding:14px;text-align:center">لا تسميعات مسجَّلة بعد.</div>`;

  return `<div class="page">
    ${pageHead("لوحة الطالب", esc(st.name) + " — " + esc(st.circle || "بلا حلقة"))}
    ${kidSwitcher()}
    ${studentProfileCard(st)}
    <div class="dash-top">
      <div class="card att-summary-wrap"><div class="att-rows">${attRows}</div></div>
      <div class="card facility-wrap"><div class="facility-grid">${cards}</div></div>
      <div class="card gauge-wrap">${donut}</div>
    </div>
    <div style="height:16px"></div>
    <div class="grid g-2" style="align-items:start">
      <div class="card">
        <div class="section-head"><h3>واجب اليوم</h3>
          <button class="btn btn-ghost btn-sm" data-action="nav" data-page="today">التفاصيل</button></div>
        ${studentDuties(st, false)}
      </div>
      <div class="card">
        <div class="section-head"><h3>آخر التسميعات</h3>
          <span class="badge b-gold">${recs.length}</span></div>
        <div class="list-card">${lastRows}</div>
      </div>
    </div>
  </div>`;
}

/* ==================== ٣) تقدم الخطة ==================== */

function studentProgress() {
  const st = activeStudent();
  if (!st) return noKidPage("تقدم الخطة", "");

  const p = studentPlan(st);
  const recs = studentRecs(st);

  if (!p) {
    return `<div class="page">${(STATE.user||{}).role === "parent" ? kidsBar() : ""}${pageHead("تقدم الخطة", "")}${kidSwitcher()}
      <div class="card">${emptyState("لا توجد خطة بعد", "راجع معلمك لإسناد خطة قرآنية.")}</div></div>`;
  }

  const prog = Number(p.progress) || 0;
  const faces = recs.reduce((a, r) => a + (Number(r.faces) || 0), 0);

  /* منحنى التطور: أوجه كل أسبوع في آخر ثمانية أسابيع */
  const weeks = [];
  for (let i = 7; i >= 0; i--) {
    const d = new Date(); d.setDate(d.getDate() - i * 7);
    const end = new Date(d); const start = new Date(d); start.setDate(start.getDate() - 6);
    const iso = x => new Date(x.getTime() - x.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
    const a = iso(start), b = iso(end);
    weeks.push({
      label: b.slice(5),
      n: recs.filter(r => r.date >= a && r.date <= b).reduce((t, r) => t + (Number(r.faces) || 0), 0)
    });
  }
  const maxW = Math.max(1, ...weeks.map(w => w.n));

  const chart = `<div class="sp-chart">${weeks.map(w => `<div class="sp-col">
      <div class="sp-bar" style="height:${Math.round(w.n / maxW * 100)}%" title="${w.n} وجه"></div>
      <span class="sp-x">${esc(w.label)}</span>
    </div>`).join("")}</div>`;

  const byGrade = RECITE_GRADES.map(g => ({ g, n: recs.filter(r => r.grade === g).length }));

  const info = [
    ["البرنامج", p.program || "—"], ["المستوى", p.level || "—"],
    ["بداية الخطة", p.start || "—"], ["الموضع الحالي", p.current || "—"],
    ["نهاية الخطة", p.end || "—"],
    ["المقدار اليومي", (p.amount || "—") + " " + (p.unit || "")]
  ].map(r => `<div class="kv"><span>${esc(r[0])}</span><strong>${esc(String(r[1]))}</strong></div>`).join("");

  return `<div class="page">
    ${pageHead("تقدم الخطة", esc(st.name))}
    ${kidSwitcher()}
    <div class="grid g-2" style="align-items:start">
      <div class="card">
        <div class="section-head"><h3>إنجاز المستوى</h3>
          <span class="badge b-gold">${prog}%</span></div>
        ${progressRow(prog, prog >= 75 ? "green" : prog >= 40 ? "blue" : "amber")}
        <div style="height:14px"></div>
        ${info}
      </div>
      <div class="card">
        <div class="section-head"><h3>تطور الحفظ</h3>
          <div class="row-actions">
            <span class="badge b-gold">${faces} وجه</span>
            <button class="btn btn-ghost btn-sm" data-action="nav" data-page="results">${ic("report", 15)} التفاصيل</button>
          </div></div>
        ${chart}
        <div class="chip-list" style="margin-top:14px">
          ${byGrade.filter(x => x.n).map(x => `<span class="chip ${GRADE_TINT[x.g]}">${esc(x.g)}: ${x.n}</span>`).join("")
            || `<span class="muted">لا تقييمات بعد.</span>`}
        </div>
      </div>
    </div>
  </div>`;
}

/* ==================== ٤) سجل الحضور — رزنامة شهرية ==================== */

function attMonth() {
  if (!STATE.attMonth) STATE.attMonth = todayISO().slice(0, 7);
  return STATE.attMonth;
}
window.shiftMonth = function (d) {
  const [y, m] = attMonth().split("-").map(Number);
  const dt = new Date(y, m - 1 + Number(d), 1);
  STATE.attMonth = dt.getFullYear() + "-" + String(dt.getMonth() + 1).padStart(2, "0");
  mount();
};

function studentAttendance() {
  const st = activeStudent();
  if (!st) return noKidPage("سجل الحضور", "");

  const ym = attMonth();
  const [Y, M] = ym.split("-").map(Number);
  const recs = studentAtt(st, ym);
  const map = {};
  recs.forEach(r => { map[String(r.date)] = r; });

  const first = new Date(Y, M - 1, 1);
  const days = new Date(Y, M, 0).getDate();
  const lead = first.getDay();          /* الأحد = 0، وهو أول أيام الأسبوع عربياً */

  const TINT = { "حاضر": "d-green", "متأخر": "d-amber", "مستأذن": "d-blue", "غائب": "d-red" };
  const NAMES = ["أحد", "إثنين", "ثلاثاء", "أربعاء", "خميس", "جمعة", "سبت"];

  let cells = "";
  for (let i = 0; i < lead; i++) cells += `<div class="cal-cell empty"></div>`;
  for (let d = 1; d <= days; d++) {
    const iso = Y + "-" + String(M).padStart(2, "0") + "-" + String(d).padStart(2, "0");
    const r = map[iso];
    /* الأيام خارج جدول الطالب تظهر محايدة ولا تُحسب — نص الوثيقة */
    const cls = r ? TINT[r.status] || "" : (iso > todayISO() ? "future" : "none");
    cells += `<div class="cal-cell ${cls}" title="${esc(iso)}${r ? " — " + esc(r.status) : ""}">
      <span class="cal-n">${toArabicDigits(d)}</span>
      ${r && r.reason ? `<span class="cal-dot"></span>` : ""}
    </div>`;
  }

  const c = s => recs.filter(r => r.status === s).length;
  const marked = recs.length;
  const rate = marked ? Math.round((c("حاضر") + c("متأخر")) / marked * 100) : 0;

  const monthName = new Date(Y, M - 1, 1).toLocaleDateString("ar-EG", { month: "long", year: "numeric" });

  return `<div class="page">${(STATE.user||{}).role === "parent" ? kidsBar() : ""}
    ${pageHead("سجل الحضور", "انضباطك شهراً بشهر")}
    ${kidSwitcher()}
    <div class="card">
      <div class="section-head" style="align-items:center">
        <h3>${esc(monthName)}</h3>
        <div class="row-actions">
          <span class="badge b-gold">الانضباط ${rate}%</span>
          <button class="btn btn-ghost btn-sm" onclick="window.shiftMonth(-1)">الشهر السابق</button>
          <button class="btn btn-ghost btn-sm" onclick="window.shiftMonth(1)"
            ${ym >= todayISO().slice(0, 7) ? "disabled" : ""}>الشهر التالي</button>
        </div>
      </div>

      <div class="cal-head">${NAMES.map(n => `<span>${n}</span>`).join("")}</div>
      <div class="cal-grid">${cells}</div>

      <div class="chip-list" style="margin-top:16px">
        <span class="chip t-green">حاضر: ${c("حاضر")}</span>
        <span class="chip t-amber">متأخر: ${c("متأخر")}</span>
        <span class="chip t-blue">مستأذن: ${c("مستأذن")}</span>
        <span class="chip t-red">غائب: ${c("غائب")}</span>
      </div>
      <div class="muted" style="font-size:12px;margin-top:10px">
        الأيام الرمادية خارج جدولك ولا تُحسب غياباً ولا تؤثّر على نسبة الانضباط.
      </div>
    </div>
  </div>`;
}

/* ==================== ٥) نتائج التسميع ==================== */

function studentResults() {
  const st = activeStudent();
  if (!st) return noKidPage("نتائج التسميع", "");

  const recs = studentRecs(st);
  if (!recs.length) {
    return `<div class="page">${(STATE.user||{}).role === "parent" ? kidsBar() : ""}${pageHead("نتائج التسميع", esc(st.name))}${kidSwitcher()}
      <div class="card">${emptyState("لا نتائج بعد", "ستظهر هنا نتائج تسميعك فور رصد معلمك لها.")}</div></div>`;
  }

  /* فلترة بالنوع — كان الجدول يعرض كل شيء بلا وسيلة تصفية */
  const rf = STATE.resFilter || "";
  const shown = rf ? recs.filter(r => r.kind === rf) : recs;

  const filterBar = `<div class="chip-list" style="margin-bottom:12px">
    <button type="button" class="chip ${!rf ? "active t-blue" : ""}"
      onclick="window.resFilter('')" style="border:none;cursor:pointer">الكل (${toArabicDigits(recs.length)})</button>
    ${RECITE_KINDS.filter(k => recs.some(r => r.kind === k)).map(k =>
      `<button type="button" class="chip ${rf === k ? "active t-green" : ""}"
        onclick="window.resFilter('${k}')" style="border:none;cursor:pointer">${esc(k)} (${toArabicDigits(recs.filter(r => r.kind === k).length)})</button>`).join("")}
  </div>`;

  const rows = shown.map(r => `<tr>
    <td>${esc(r.date)}</td>
    <td><span class="chip">${esc(r.kind)}</span></td>
    <td>${esc(r.fromName)} ${toArabicDigits(r.fromA)} — ${esc(r.toName)} ${toArabicDigits(r.toA)}</td>
    <td class="pt-num">${r.faces || 0}</td>
    <td class="pt-num">${(r.errors || 0)} / ${(r.tajweed || 0)}</td>
    <td><span class="chip ${GRADE_TINT[r.grade] || ""}">${esc(r.grade || "—")}</span></td>
    <td class="muted" style="font-size:12px">${esc(r.note || "")}</td>
  </tr>`).join("");

  const faces = recs.reduce((a, r) => a + (Number(r.faces) || 0), 0);
  const errs  = recs.reduce((a, r) => a + (Number(r.errors) || 0), 0);
  const tajw  = recs.reduce((a, r) => a + (Number(r.tajweed) || 0), 0);

  return `<div class="page">
    ${pageHead("نتائج التسميع", esc(st.name))}
    ${kidSwitcher()}
    <div class="chip-list" style="margin-bottom:14px">
      <span class="chip t-green">${recs.length} جلسة</span>
      <span class="chip t-blue">${faces} وجه</span>
      <span class="chip t-red">أخطاء حفظ: ${errs}</span>
      <span class="chip t-amber">أخطاء تجويد: ${tajw}</span>
      ${RECITE_GRADES.filter(g => recs.some(r => r.grade === g)).map(g =>
        `<span class="chip ${GRADE_TINT[g]}">${esc(g)}: ${recs.filter(r => r.grade === g).length}</span>`).join("")}
    </div>
    ${filterBar}
    <div class="table-wrap"><div class="table-scroll"><table class="data" style="min-width:720px">
      <thead><tr><th>التاريخ</th><th>النوع</th><th>المدى</th><th>الأوجه</th>
        <th>أخطاء حفظ/تجويد</th><th>التقييم</th><th>ملاحظة المعلم</th></tr></thead>
      <tbody>${rows}</tbody>
    </table></div></div>
    ${shown.length ? "" : `<div class="muted" style="padding:20px;text-align:center">لا نتائج في هذا الفرز.</div>`}
    <div style="height:16px"></div>
    <div class="row-actions">
      <button class="btn btn-ghost btn-sm" data-action="nav" data-page="mushaf">${ic("book", 15)} مواضع أخطائي في المصحف</button>
      <button class="btn btn-ghost btn-sm" data-action="nav" data-page="progress">${ic("target", 15)} تقدم خطتي</button>
    </div>
  </div>`;
}

/* =========================================================================
   التنبيهات — كانت عرضاً جامداً بلا أي تفاعل
   -------------------------------------------------------------------------
   لا تمييز للمقروء من غيره، ولا فلترة، ولا وقت. صارت تُعلَّم مقروءة
   بالضغط، وتُفلتر بين الكل وغير المقروء، ويظهر وقت كل إشعار.
   ========================================================================= */

function notifFilter() {
  if (!STATE.notifFilter) STATE.notifFilter = "all";
  return STATE.notifFilter;
}

window.notifSetFilter = function (v) { STATE.notifFilter = v || "all"; mount(); };

function notifRead(id) {
  const n = (DB.notifications || []).find(x => String(x.id) === String(id));
  if (!n) return;
  n.read = !n.read;
  persistSet("notifications", n);
  mount();
}

function notifReadAll() {
  const mine = myNotifs().filter(n => !n.read);   /* تنبيهاتي وحدها تُعلَّم */
  if (!mine.length) { showToast("لا توجد تنبيهات غير مقروءة"); return; }
  mine.forEach(n => { n.read = true; persistSet("notifications", n); });
  mount();
  showToast("عُلّمت " + toArabicDigits(mine.length) + " تنبيهاً كمقروء");
}

function timeAgo(ts) {
  if (!ts) return "";
  const d = Math.floor((Date.now() - Number(ts)) / 1000);
  if (d < 60) return "الآن";
  if (d < 3600) return "قبل " + toArabicDigits(Math.floor(d / 60)) + " دقيقة";
  if (d < 86400) return "قبل " + toArabicDigits(Math.floor(d / 3600)) + " ساعة";
  if (d < 604800) return "قبل " + toArabicDigits(Math.floor(d / 86400)) + " يوم";
  return new Date(Number(ts)).toLocaleDateString("ar-EG");
}

/* تنبيهات المخاطَب وحده — كان يُعرض كلُّ ما في النظام، فيرى وليُّ الأمر
   تنبيهاتِ الإدارة عن طلابٍ لا يعرفهم. */
/* هل يقع التنبيهُ في نطاقي؟ يُقاس بحقوله كأيّ سجلّ. والتنبيهُ الذي لا
   نطاقَ له ليس تنبيهَ منشأةٍ بعينها، فلا يُنسب إلى مديرِ منشأة. */
function notifInMyScope(n) {
  if (!n) return false;
  if (!(n.mosqueId || n.complexId || n.circleId)) return false;
  try { return inScope(n, "circle"); } catch (e) { return false; }
}

function myNotifs() {
  const u = (STATE && STATE.user) || {};
  const role = String(u.role || "");
  const uid = String(u.uid || u.id || "");

  /* من يخصّونه: أبناؤه إن كان وليَّ أمر، أو نفسُه إن كان طالباً،
     أو طلابُ حلقاته إن كان معلّماً. */
  let mine = new Set();
  try {
    if (role === "teacher") {
      const cids = new Set((cur("circles") || [])
        .filter(c => c && (String(c.teacherId) === uid ||
          (Array.isArray(c.assistants) && c.assistants.indexOf(uid) > -1)))
        .map(c => String(c.id)));
      (cur("students") || []).forEach(st => {
        if (st && cids.has(String(st.circleId))) mine.add(String(st.id));
      });
    } else {
      mine = (myStudents() || {}).ids || new Set();
    }
  } catch (e) {}

  /* الإداريّ يقرأ ما وُجّه إلى «admin»: المشرفُ إداريٌّ في نطاقه */
  const isAdminSide = role === "admin" || role === "owner" || isMgrRole(role);

  return (cur("notifications") || []).filter(n => {
    if (!n) return false;

    /* موجَّهٌ إليه شخصياً */
    if (n.toUid && String(n.toUid) === uid) return true;
    if (n.toId && String(n.toId) === uid) return true;

    /* يخصّ من يتابعهم */
    if (n.studentId && mine.has(String(n.studentId))) return true;

    /* موجَّهٌ إلى دوره */
    if (n.toRole) {
      /* الدورُ وحده لا يكفي لمن أُسنِد إلى منشأة: تنبيهُ «admin» يُولَّد من
         أحداث النظام كلِّه، فكان مديرُ المسجد يقرأ في جرسه أخبارَ المساجد
         الأخرى. يلزمه أن يقع في نطاقه — والمالكُ والمديرُ بلا هذا القيد. */
      const wide = !userScopeOf();
      if (String(n.toRole) === role) return wide || notifInMyScope(n);
      if ((n.toRole === "admin" || n.toRole === "supervisor") && isAdminSide)
        return wide || notifInMyScope(n);
      return false;
    }

    /* بلا وجهةٍ أصلاً: يُعدّ إدارياً لا عامّاً.
       كان يُعدّ عامّاً فيصل الطالبَ ووليَّه كلُّ تنبيهٍ نُسي توجيهُه —
       ونسيانُ التوجيه أكثرُ من قصده. والعامُّ الحقيقيّ يُوسَم toAll. */
    if (n.toAll === true) return true;

    /* بلا وجهةٍ ولا نطاق: إداريٌّ عامٌّ — للمالك والمدير وحدهما */
    if (!n.toUid && !n.toId && !n.studentId)
      return isAdminSide && (!userScopeOf() || notifInMyScope(n));

    return false;
  }).slice().sort((a, b) => (b.ts || 0) - (a.ts || 0));
}

function studentNotifications() {
  const all = myNotifs();
  const f = notifFilter();
  const unread = all.filter(n => !n.read).length;
  const list = f === "unread" ? all.filter(n => !n.read) : all;

  const kb = (STATE.user || {}).role === "parent" && typeof kidsBar === "function"
    ? kidsBar() : "";

  const bar = `<div class="chip-list" style="margin-bottom:14px;align-items:center">
    <button type="button" class="chip ${f === "all" ? "active t-blue" : ""}"
      onclick="window.notifSetFilter('all')" style="border:none;cursor:pointer">الكل (${toArabicDigits(all.length)})</button>
    <button type="button" class="chip ${f === "unread" ? "active t-amber" : ""}"
      onclick="window.notifSetFilter('unread')" style="border:none;cursor:pointer">غير مقروء (${toArabicDigits(unread)})</button>
    ${unread ? `<span style="flex:1"></span>
      <button class="btn btn-ghost btn-sm" data-action="notif-read-all">${ic("check", 15)} تعليم الكل كمقروء</button>` : ""}
  </div>`;

  if (!all.length) {
    return `<div class="page">
      ${pageHead("التنبيهات", "آخر الإشعارات الخاصة بك")}
      ${kidSwitcher()}
      <div class="card">${emptyState("لا توجد تنبيهات", "ستظهر إشعاراتك هنا فور صدورها.")}</div></div>`;
  }

  const tint = { success: "t-green", warn: "t-amber", info: "t-blue" };
  const items = list.length ? list.map(n => `<button type="button"
      class="alert-item nt ${n.read ? "read" : ""}"
      data-action="notif-read" data-id="${esc(String(n.id))}"
      title="${n.read ? "تعليم كغير مقروء" : "تعليم كمقروء"}">
      <div class="alert-ico ${tint[n.type] || "t-blue"}">${ic("info", 18)}</div>
      <div class="at">
        <strong>${esc(n.title || "تنبيه")}</strong>
        <small>${esc(n.text || n.body || "")}</small>
        <span class="nt-time">${esc(timeAgo(n.ts))}</span>
      </div>
      ${!n.read ? `<span class="nt-dot"></span>` : ""}
    </button>`).join("")
    : `<div class="muted" style="padding:20px;text-align:center">لا توجد تنبيهات غير مقروءة.</div>`;

  return `<div class="page">
    ${pageHead("التنبيهات", "آخر الإشعارات الخاصة بك")}
    ${kidSwitcher()}
    ${bar}
    <div class="nt-list">${items}</div>
  </div>`;
}

