/* =========================================================
   COMPLEX SELECT (الشريط العلوي)
   ========================================================= */
function renderComplexSelect() {
  const sel = document.querySelector("#orgSelect");
  if (!sel) return;

  /* =======================================================================
     غير الإداريين: منشأة واحدة لا قائمة اختيار
     -----------------------------------------------------------------------
     كان المعلم يرى قائمة منسدلة بكل مجمعات النظام ويستطيع التنقّل بينها،
     وهذا تسريب لأسماء المنشآت الأخرى وإن حُصرت بياناتها. يعرض له الآن اسم
     مسجده — أو مجمعه إن لم يُربط بمسجد — نصاً واحداً غير قابل للتغيير.
     ======================================================================= */
  const u = (STATE && STATE.user) || {};
  const role = u.role || "";
  if (role && role !== "admin" && !isMgrRole(role)) {
    const lbl = document.querySelector(".org-label");
    let name = "—";

    /* يقرأ النطاق المشتقّ لا الحقلين المفردين، فيظهر اسم المنشأة حتى لو
       لم تُملأ في حساب المستخدم ما دام ملف الطالب أو المعلم مسنَداً. */
    const ids = userScopeIds(u);
    const mqId = (ids.filter(k => k.indexOf("mosque:")  === 0)[0] || "").split(":")[1];
    const cxId = (ids.filter(k => k.indexOf("complex:") === 0)[0] || "").split(":")[1];

    if (mqId) {
      const m = (DB.mosques || []).find(x => String(x.id) === String(mqId));
      if (m) { name = m.name || "—"; if (lbl) lbl.textContent = "المسجد"; }
    }
    if (name === "—" && cxId) {
      const c = (DB.complexes || []).find(x => String(x.id) === String(cxId));
      if (c) { name = c.name || "—"; if (lbl) lbl.textContent = "المجمع"; }
    }
    if (name === "—" && lbl) lbl.textContent = "المنشأة";
    if (name === "—") sel.title = "حسابك غير مرتبط بمنشأة — راجع الإدارة";
    if (cxId) STATE.complexId = cxId;

    sel.innerHTML = `<option>${esc(name)}</option>`;
    sel.disabled = true;
    sel.classList.add("org-fixed");
    return;
  }

  /* =======================================================================
     المجمّعات المعروضة: ما يراه صاحب الجلسة لا ما في النظام
     -----------------------------------------------------------------------
     كانت القائمة تُبنى من DB.complexes رأساً، والشرط أعلاه يستثني الإداريين
     كلَّهم — فمديرُ المسجد ومديرُ المجمّع يريان في الشريط العلويّ أسماءَ
     مجمّعات النظام كلِّها، ويبدّلان بينها بنقرة.

     وهو أظهرُ تسريبٍ في النظام: يقع في الشريط الذي لا يفارق الشاشة.
     ======================================================================= */
  const cxList = (typeof cur === "function" ? cur("complexes") : DB.complexes) || [];

  if (!cxList.length) {
    sel.innerHTML = `<option>لا توجد مجمعات — أضف مجمعاً</option>`;
    STATE.complexId = null;
    return;
  }

  /* المجمّع المحفوظ إن خرج عن النطاق لا يُبقى عليه: يُبدَّل إلى أوّل ما يُرى */
  if (!STATE.complexId || !cxList.some(x => x.id == STATE.complexId)) {
    STATE.complexId = cxList[0].id;
  }

  /* مجمّعٌ واحدٌ لا قائمةَ له: نصٌّ ثابتٌ كما لغير الإداريين */
  if (cxList.length === 1) {
    sel.innerHTML = `<option>${esc(cxList[0].name || "—")}</option>`;
    sel.disabled = true;
    sel.classList.add("org-fixed");
    return;
  }

  sel.innerHTML = cxList.map(cx =>
    `<option value="${cx.id}" ${cx.id == STATE.complexId ? "selected" : ""}>${esc(cx.name)}</option>`
  ).join("");

  if (!sel.dataset.bound) {
    sel.dataset.bound = "1";
    sel.addEventListener("change", () => {
      STATE.complexId = sel.value;
      STATE.planId = null;
      renderNav(); mount();
      showToast("تم التبديل إلى " + complexName(STATE.complexId), "info");
    });
  }
}

/* =========================================================
   NAV RENDER + ROUTER
   ========================================================= */
/* =========================================================================
   شريط التنقّل السفليّ — للجوّال
   -------------------------------------------------------------------------
   القائمةُ الجانبية على الجوّال درجٌ يُفتح بزرّ، فكلُّ تنقّلٍ ضغطتان: زرُّ
   القائمة ثمّ البند. والمعلّمُ يتنقّل بين شاشاته عشراتِ المرّات في الحلقة.

   أربعةُ بنودٍ في متناول الإبهام أسفلَ الشاشة: الأكثرُ استعمالاً لكلّ دور.
   والباقي في الدرج كما كان — لا يُفقد شيء.
   ========================================================================= */
const TABBAR = {
  teacher: [
    { id: "dashboard", label: "الرئيسية", icon: "grid" },
    { id: "today",     label: "حلقة اليوم", icon: "book" },
    { id: "attendance",label: "التحضير",  icon: "attend" },
    { id: "recite",    label: "التسميع",  icon: "pen" }
  ],
  student: [
    { id: "dashboard", label: "الرئيسية", icon: "grid" },
    { id: "today",     label: "واجب اليوم", icon: "book" },
    { id: "progress",  label: "سير الخطة", icon: "target" },
    { id: "store",     label: "المتجر",   icon: "gift" }
  ],
  parent: [
    { id: "dashboard", label: "الرئيسية", icon: "grid" },
    { id: "today",     label: "واجب اليوم", icon: "book" },
    { id: "progress",  label: "سير الخطة", icon: "target" },
    { id: "store",     label: "المتجر",   icon: "gift" }
  ]
};

function renderTabBar() {
  const el = document.getElementById("tabbar");
  if (!el) return;

  const items = TABBAR[STATE.iface];
  if (!items) { el.innerHTML = ""; el.style.display = "none"; return; }

  /* ما لا شاشةَ له يُطرح: المتجرُ مثلاً قد يكون مطفأً في الإعدادات */
  const live = items.filter(it => PAGES[STATE.iface + "/" + it.id]);
  if (!live.length) { el.innerHTML = ""; el.style.display = "none"; return; }

  el.style.display = "";
  el.innerHTML = live.map(it =>
    `<button type="button" class="tb-item${it.id === STATE.page ? " on" : ""}"
      data-action="nav" data-page="${it.id}">
      ${ic(it.icon, 21)}<span>${esc(it.label)}</span>
    </button>`).join("");
}

function renderNav() {
  const nav = $("#nav");
  if (!nav) return;
  /* البنود التي لا يُتيحها مستواه تُخفى: من رأى زرّاً ثمّ مُنع ظنّ العطل */
  const items = navFor(STATE.iface);
  try { renderTabBar(); } catch (e) {}

  nav.innerHTML = items.map(it => {
    /* العدّادُ يُنادى في حارس: دالّةٌ ترمي خطأً كانت تُسقط رسمَ القائمة
       كلِّها، فتختفي البنودُ جميعاً — والسببُ عدّادٌ في بندٍ واحد. */
    let cnt = "";
    try {
      if (it.count) cnt = `<span class="nav-count">${it.count()}</span>`;
    } catch (e) { cnt = ""; }
    return `<button class="nav-item ${it.id === STATE.page ? "active" : ""}" data-action="nav" data-page="${it.id}">${ic(it.icon, 19)}<span>${esc(it.label)}</span>${cnt}</button>`;
  }).join("");
}

/* الواجهة المسموح بها لدور الحساب — لا تُشتقّ من زر ولا من نداء يدوي */
/* =========================================================================
   فصل أدوار المجمّع عن المسجد
   -------------------------------------------------------------------------
   المواصفات تفرّق بين ستّة أدوار في مستويين:

     المجمّع: مدير — مشرف — داعم   (نطاقه: المجمّع ومساجده)
     المسجد: مدير — مشرف — داعم   (نطاقه: مسجده وحلقاته)

   وكان الدور واحداً للمستويين: admin لمدير المجمّع ومدير المسجد معاً، فمدير
   مسجدٍ يملك صلاحيات مدير المجمّع كاملة — يضيف مساجد ويعدّل حسابات غيره.

   والحلّ ليس بتغيير مفاتيح الأدوار: admin و supervisor مقروءان في سبعة عشر
   موضعاً وفي قواعد Firestore، وتغييرهما يقفل كلّ الحسابات القائمة.

   الحلّ: الدور يحدّد الوظيفة، والنطاق يحدّد المستوى. من ملفّه mosqueId فهو
   على مستوى المسجد، ومن له complexId وحده فهو على مستوى المجمّع. وهذا
   ما تقرؤه قواعد Firestore أصلاً — فيتّسق الحصر في الواجهة مع الحصر فيها.
   ========================================================================= */

/* مستوى المستخدم: system · complex · mosque */
/* =========================================================================
   نطاق المشرف — مساجدُ عدّة لا واحد
   -------------------------------------------------------------------------
   كان الحصر يقرأ mosqueId و complexId المفردين، والمشرفُ على مسجدين
   يُسجَّل على أحدهما فيرى الأوّل ولا يرى الثاني — وهو مشرفٌ عليهما.

   scopeIds[] موجودٌ في ملفّه من نموذج المستخدمين، لكنّ المرشّحات لم تكن
   تقرؤه. تُقرأ هنا مرّةً وتُشتقّ منها المساجدُ والحلقات، فيصير الحصر
   واحداً في كلّ الشاشات.
   ========================================================================= */
function myScope(u) {
  const p = u || (STATE && STATE.user) || {};
  const out = { mosques: new Set(), complexes: new Set(), circles: new Set(), open: false };

  if (isTopAdmin(p)) { out.open = true; return out; }

  /* scopeIds: "mosque:ID" أو "complex:ID" */
  (Array.isArray(p.scopeIds) ? p.scopeIds : []).forEach(k => {
    const v = String(k || "");
    if (v.indexOf("mosque:") === 0) out.mosques.add(v.slice(7));
    else if (v.indexOf("complex:") === 0) out.complexes.add(v.slice(8));
  });

  /* الحقول المفردة للتوافق مع ما سُجّل قبل التعدّد */
  if (p.mosqueId) out.mosques.add(String(p.mosqueId));
  if (p.complexId) out.complexes.add(String(p.complexId));

  /* مساجدُ المجمّعات المُسنَدة تدخل في النطاق */
  (Array.isArray(DB.mosques) ? DB.mosques : []).forEach(m => {
    if (m && out.complexes.has(String(m.complexId || ""))) out.mosques.add(String(m.id));
  });

  /* حلقاتُ ما سبق */
  (Array.isArray(DB.circles) ? DB.circles : []).forEach(c => {
    if (!c) return;
    if (out.mosques.has(String(c.mosqueId || "")) ||
        out.complexes.has(String(c.complexId || ""))) out.circles.add(String(c.id));
  });

  /* بلا إسنادٍ أصلاً: من لم يُسنَد إليه شيءٌ لا يُشرف على كلّ شيء */
  if (!out.mosques.size && !out.complexes.size) {
    out.open = (!isMgrRole(p.role) && p.role !== "donor");
  }

  return out;
}

/* هل يقع هذا السجلّ في نطاقي؟ */
function inScope(x, how) {
  const sc = myScope();
  if (sc.open) return true;
  if (!x) return false;

  if (x.mosqueId && sc.mosques.has(String(x.mosqueId))) return true;
  if (x.complexId && sc.complexes.has(String(x.complexId))) return true;
  if (how === "circle" && x.circleId && sc.circles.has(String(x.circleId))) return true;

  /* المساجدُ والمجمّعاتُ أنفسُها */
  if (x.id && sc.mosques.has(String(x.id))) return true;
  if (x.id && sc.complexes.has(String(x.id))) return true;

  /* الطالبُ بلا مسجدٍ يُنسب عبر حلقته */
  if (x.circleId && sc.circles.has(String(x.circleId))) return true;

  return false;
}

function scopeLevel(u) {
  const p = u || (STATE && STATE.user) || {};
  if (isTopAdmin(p)) return "system";           /* المالك والمدير: بلا حصر */

  /* الدورُ يحكم المستوى قبل النطاق: مديرُ المسجد الذي أُسنِد إليه
     complexId خطأً كان يُقرأ مستواه «مجمّع» فيرى مساجدَ ليست له.
     ومديرُ المجمّع لا ينزل إلى مستوى المسجد وإن حمل mosqueId. */
  if (isComplexMgr(p.role)) return "complex";
  if (p.role === "mosqueManager") return "mosque";

  if (p.mosqueId) return "mosque";
  if (p.complexId) return "complex";

  /* المشرف بلا نطاقٍ في ملفّه كان يُعدّ على مستوى النظام فيرى كلّ شيء —
     وهو عكس المقصود: من لم يُسنَد إليه شيءٌ لا يُشرف على كلّ شيء.
     يُعامَل بأضيق نطاقٍ حتى يُسنَد إليه مسجدُه أو مجمّعه. */
  if (isMgrRole(p.role) || p.role === "donor") return "mosque";

  return "system";
}





/* الاسم المعروض للدور بمستواه */
function roleTitle(u) {
  const p = u || (STATE && STATE.user) || {};
  const lvl = scopeLevel(p);
  const at = lvl === "mosque" ? "المسجد" : lvl === "complex" ? "المجمّع" : "النظام";

  const M = {
    owner: "مالك النظام",
    admin: "مدير " + at,
    complexManager: "مدير المجمّع",
    mosqueManager: "مدير المسجد",
    supervisor: "مشرف " + at,
    donor: "داعم " + at,
    teacher: "معلّم", student: "طالب", parent: "ولي أمر"
  };
  return M[p.role] || p.role || "";
}

/* =========================================================================
   ما يُتاح لكلّ مستوى
   -------------------------------------------------------------------------
   المواصفات: مدير المجمّع «يدير حسابات المشرفين والداعمين والمساجد التابعة»،
   ومدير المسجد «في نطاق مسجده وحلقاته فقط» — لا ينشئ مساجد ولا يمسّ إعدادات
   النظام.
   ========================================================================= */

/* أعمالٌ تخصّ مستوى المجمّع فما فوق.
   البرامجُ والمسيّراتُ خرجتا منها بقرار الإدارة: مديرُ المسجد يبني
   مناهجَ حلقاته ويرى مسيّرَ مسجده — ونطاقُه يحصر ما يراه في الحالين. */
const COMPLEX_ONLY = [
  "complexes",      /* إنشاء المجمّعات والمساجد */
  "mosques",
  "supervisors",    /* حسابات مدراء المساجد والداعمين */
  "users",
  "terms"           /* الفترات الدراسية للمجمّع كلّه */
];

/* أعمالٌ تخصّ مستوى النظام وحده */
const SYSTEM_ONLY = ["audit", "settings-core"];

/* =========================================================================
   ما يُمنع عن المشرف مهما اتّسع نطاقه
   -------------------------------------------------------------------------
   إدارةُ الحسابات والصلاحيات شأنُ المدير: من ملك إنشاءَ الحسابات وتعديلَ
   أدوارها ملك النظام كلَّه — يرقّي نفسه أو يفتح حساباً بصلاحيةٍ أوسع.

   وكانت "users" في COMPLEX_ONLY، فتُمنع على مستوى المسجد وحده. ومشرفُ
   المجمّع كان يراها.
   ========================================================================= */
/* ما يُمنع عن مدير المسجد والداعم مهما اتّسع نطاقهما.
   ومديرُ المجمّع أُخرج منه بقرار الإدارة: يُنشئ مدراءَ مساجده ويعدّلهم.
   وحدُّه أنه لا يُنشئ إلا في مجمّعه ولا يمنح دوراً أعلى من دوره —
   يحرسه canGrantRole أدناه، وقواعدُ Firestore تحرسه على الخادم. */
const ADMIN_ONLY = [
  "users",          /* المستخدمون والحسابات */
  "supervisors",    /* حسابات مدراء المساجد والداعمين */
  "settings-core"   /* الإعدادات الجوهرية */
];

/* =========================================================================
   من يمنح أيَّ دور
   -------------------------------------------------------------------------
   الحدُّ الذي لا يُتجاوز: لا أحدَ يمنح دوراً أعلى من دوره، ولا أحدَ يمنح
   دورَه نفسَه لغيره إن لم يكن فوقه. وإلّا فمديرُ مجمّعٍ يُنشئ مديرَ نظامٍ
   ثمّ يدخل به — فتسقط كلُّ الحدود دفعةً واحدة.
   ========================================================================= */
const GRANTABLE = {
  owner:          ["owner", "admin", "complexManager", "mosqueManager", "supervisor",
                   "teacher", "parent", "student", "donor"],
  admin:          ["admin", "complexManager", "mosqueManager", "supervisor",
                   "teacher", "parent", "student", "donor"],
  complexManager: ["mosqueManager", "supervisor", "teacher", "parent", "student", "donor"],
  /* مديرُ المسجد يعيّن مشرفَ مسجده — وهو أعرفُ بمن يشرف عنده */
  mosqueManager:  ["supervisor", "teacher", "parent", "student"],
  supervisor:     ["teacher", "parent", "student"]
};

function canGrantRole(target, actor) {
  const a = actor || (STATE && STATE.user) || {};
  const list = GRANTABLE[String(a.role || "")] || [];
  return list.indexOf(String(target || "")) > -1;
}

function canDo(area) {
  const r = ((STATE && STATE.user) || {}).role || "";

  /* «المستخدمون والحسابات» لمدير المسجد بقرار الإدارة. استثناءٌ صريحٌ
     هنا لا حذفٌ من القائمتين أدناه: حذفُ "users" من COMPLEX_ONLY يفتحها
     للداعم ولكلّ من هو على مستوى المسجد، وهو غيرُ المقصود.
     والكتابةُ تبقى للمدير وحده — قواعدُ Firestore تحرسها على الخادم. */
  if (r === "mosqueManager" && area === "users") return true;

  /* إدارةُ الحسابات: مديرُ المجمّع يملكها في مجمّعه بقرار الإدارة،
     ومديرُ المسجد والداعمُ ممنوعان منها مهما اتّسع نطاقُهما.
     والإعداداتُ الجوهريةُ تبقى ممنوعةً على الجميع دون المالك والمدير. */
  if (isComplexMgr(r)) {
    if (SYSTEM_ONLY.indexOf(area) > -1) return false;
  } else if ((isMgrRole(r) || r === "donor") && ADMIN_ONLY.indexOf(area) > -1) {
    return false;
  }

  const lvl = scopeLevel();
  if (lvl === "system") return true;
  if (SYSTEM_ONLY.indexOf(area) > -1) return false;
  if (lvl === "complex") return true;
  /* مستوى المسجد: يُمنع ما هو للمجمّع */
  return COMPLEX_ONLY.indexOf(area) === -1;
}

/* المسجد الذي يعمل فيه المستخدم — يُحصر به كلّ ما يراه ويكتبه */
function myMosqueId() {
  const u = (STATE && STATE.user) || {};
  return String(u.mosqueId || "");
}

/* ترشيح قائمةٍ بنطاق المستخدم: يُنادى قبل عرض أيّ بيانات */
function scoped(list, opts) {
  const arr = Array.isArray(list) ? list : [];
  const lvl = scopeLevel();
  if (lvl === "system" || isTopAdmin()) return arr;

  const cx = String(((STATE && STATE.user) || {}).complexId || "");
  const mq = myMosqueId();
  const o = opts || {};

  return arr.filter(x => {
    if (!x) return false;

    /* بيانات قديمة بلا نطاق: تبقى مرئيّة لئلّا تختفي عن أصحابها */
    if (cx && x.complexId && String(x.complexId) !== cx) return false;

    if (lvl === "mosque" && mq) {
      if (x.mosqueId) return String(x.mosqueId) === mq;
      /* ما لا mosqueId له: يُنسب عبر حلقته */
      if (o.viaCircle && x.circleId) {
        const c = (cur("circles") || []).find(y => String(y.id) === String(x.circleId));
        return c ? String(c.mosqueId || "") === mq : true;
      }
    }
    return true;
  });
}

/* حلقات نطاقه — أساسٌ لأكثر الشاشات */






/* =========================================================================
   إخفاء ما لا يُتاح
   -------------------------------------------------------------------------
   إخفاء البند خيرٌ من عرضه ثمّ رفضه: من رأى زرّاً ثمّ مُنع ظنّ العطل، ومن لم
   يره لم يطلبه.
   ========================================================================= */
/* =========================================================================
   ما يراه كلُّ دورٍ في القائمة
   -------------------------------------------------------------------------
   القائمةُ كانت واحدةً للجميع، والمنعُ لا يظهر إلا بعد الضغط: يرى المرءُ
   عشرين باباً ويُردّ عن نصفها. هذه أبوابُ كلٍّ بحسب دوره.

   وهي زينةٌ لا حماية: canDo يحرس الشاشة، وقواعدُ Firestore تحرس البيانات.
   ========================================================================= */
const NAV_ROLE = {
  complexManager: ["dashboard", "complexes", "supervisors", "admissions",
                   "programs", "reports", "stats", "exams", "transport",
                   "move", "worktime", "duty", "finance", "payroll", "settings"],
  mosqueManager:  ["dashboard", "students", "circles", "managers", "teachers",
                   "programs", "reports", "stats", "exams", "transport",
                   "move", "worktime", "duty", "procs", "motivation", "points",
                   "finance", "payroll", "settings"]
};

function navFor(iface) {
  const list = (NAV && NAV[iface]) || [];
  if (iface !== "admin") return list;

  const AREA = {
    complexes: "complexes", mosques: "mosques",
    supervisors: "supervisors", managers: "supervisors",
    users: "users", settings: "settings"
  };

  /* بنودٌ مالية: تُخفى عمّن لا يرى المال */
  /* المالية مفصولةٌ عن التحفيز: مجموعتان تُخفيان معاً عمّن لا يرى المال،
     ولكلٍّ بابُها في القائمة. */
  const FIN = ["payroll", "finance"];              /* مالٌ خالص */
  const MOT = ["points", "motivation"];            /* تحفيزٌ تربويّ */

  return list.filter(it => {
    if (!it) return false;
    if (FIN.indexOf(it.id) > -1 || FIN.indexOf(it.group) > -1) {
      if (!canSeeFinance()) return false;
    }
    if (MOT.indexOf(it.id) > -1 || MOT.indexOf(it.group) > -1) {
      if (!canSeeMotivation()) return false;
    }
    const area = AREA[it.id];
    if (area && !canDo(area)) return false;

    /* أبوابُ الدور: من له قائمةٌ خاصّة لا يرى غيرها */
    const allow = NAV_ROLE[((STATE && STATE.user) || {}).role || ""];
    if (allow && allow.indexOf(it.id) === -1 &&
        (!it.group || allow.indexOf(it.group) === -1)) return false;

    return true;
  });
}

function allowedIface() {
  const r = ((STATE && STATE.user) || {}).role || "";
  if (!r) return null;                                   /* لا جلسة: بلا قيد */
  if (r === "admin" || isMgrRole(r)) return "admin";
  if (r === "teacher") return "teacher";
  /* وليُّ الأمر كان يُوجَّه إلى واجهة الطالب، فيرى شاشاتٍ تخاطب ابنه لا
     تخاطبه، ولا يجد شريطَ الأبناء ولا مراسلةَ المعلّم. */
  if (r === "parent") return "parent";
  if (r === "student") return "student";
  if (r === "donor") return "donor";
  return null;
}

function setIface(iface) {
  if (!NAV[iface]) return;
  /* كان بالإمكان استدعاء setIface("admin") من وحدة التحكم فتُفتح واجهة
     الإدارة لأي حساب. الآن الدور هو الحكم، وإخفاء الأزرار لم يعد الحماية. */
  const allow = allowedIface();
  if (allow && iface !== allow) {
    if (typeof showToast === "function") showToast("لا تملك صلاحية هذه الواجهة", "warn");
    return;
  }
  STATE.iface = iface;
  STATE.page = NAV[iface][0].id;
  STATE.tab = {};
  STATE.planId = null;
  $$(".iface-btn").forEach(b => b.classList.toggle("active", b.dataset.iface === iface));
  const un = $("#userName"); if (un) un.textContent = USER_NAME[iface];
  const ur = $("#userRole"); if (ur) ur.textContent = ROLE_LABEL[iface];
  const av = $(".avatar"); if (av) av.textContent = initials(USER_NAME[iface]);
  renderNav();
  mount();
}

function go(page) {
  /* =====================================================================
     SHELL_MODE لصفحات الإدارة وحدها
     ---------------------------------------------------------------------
     admin/shell.js يفعّله في كلّ صفحةٍ يُحمَّل فيها، والمعلّمُ قد يدخل من
     إحداها فيبقى مفعّلاً في جلسته. فيُبحث لشاشاته عن ملفّ HTML مستقلّ —
     ولا ملفّ لها، فيقف الزرُّ بصمتٍ أو يقول «لم يُعثر على شاشة».

     شاشاتُ المعلّم والطالب ووليّ الأمر تُرسم في مكانها لا في ملفّات.
     ===================================================================== */
  const inShell = window.SHELL_MODE && STATE.iface === "admin";

  if (inShell && page !== STATE.page) {
    var files = window.__adminFiles || {};

    /* المفاتيح تُنادى بصيغتين: "exams-record" و "admin/exams-record"،
       والخريطة تحفظها بلا بادئة. تجربة الصيغتين أأمن من توحيد النداءات
       المتفرّقة في الملف. */
    var key = String(page || "");
    var bare = key.indexOf("/") > -1 ? key.slice(key.lastIndexOf("/") + 1) : key;
    var f = files[key] || files[bare];

    if (!f) {
      /* لا ملف ولا مفتاح: الانتقال إلى صفحة غير موجودة يقف بلا خطأ في
         الطرفية، فيبدو الزرّ معطّلاً. يُقال السبب بدل الصمت. */
      if (typeof showToast === "function") {
        showToast("لم يُعثر على شاشة «" + bare + "»", "warn");
        return;
      }
      f = bare + ".html";
    }
    /* مسارٌ مطلق: أسماءُ الملفات في الخريطة نسبيّة (complexes.html)، فإن
       نُودي go من صفحةٍ خارج مجلّد admin — كصفحة الجذر — حُلَّ الاسمُ إلى
       /complexes.html ولا ملفَّ هناك، فتظهر صفحةُ Firebase «Page Not
       Found». الصفحاتُ كلُّها في /admin/ فيُصرَّح بالمجلّد. */
    location.href = /^(\/|https?:)/.test(f) ? f : "/admin/" + f;
    return;
  }
  /* القائمةُ الجانبية ظاهرةٌ بجوار بطاقة الطالب، فالانتقالُ منها يُغلقها —
     وإلا بقيت البطاقةُ فوق صفحةٍ أخرى. */
  try { if (document.body.classList.contains("panel-open")) closePanel(); } catch (e) {}
  STATE.page = page;
  STATE.planId = null;
  STATE.facilityView = null;   /* مغادرة الصفحة تُغلق عرض التفاصيل */
  renderNav();
  mount();
  const sb = $("#sidebar"); if (sb) sb.classList.remove("open");
  const ov = $("#overlay"); if (ov) ov.classList.remove("show");
}

/* عنوان تبويب المتصفح يتبع الصفحة المعروضة */
function setDocTitle(t) {
  const base = "لوحة الإدارة | " + (complexName(STATE.complexId) || "ذات القرآنية");
  document.title = t ? t + " — " + base : base;
}

/* =========================================================================
   الفحوص الدورية — لا مع كلّ رسم
   -------------------------------------------------------------------------
   كانت سبعةُ فحوصٍ تجري في mount: مسحُ التنبيهات ونقصِ البيانات وانقطاعِ
   الحلقات وترحيلِ الواجبات ومزامنةِ النطاق. وكلٌّ منها يمرّ على آلاف
   السجلات.

   و mount تُنادى مع كلّ ضغطةِ زرّ وكلّ تبديلِ تبويب — فتُعاد الفحوص كلّها
   عشراتِ المرّات في الدقيقة، والنتيجة واحدة في كلّ مرة.

   تجري الآن كلّ دقيقتين، وعند أوّل رسمٍ بعد تحميل البيانات. والفرقُ
   محسوس: الرسم يصير عرضاً محضاً لا فحصاً.
   ========================================================================= */
let SCAN_AT = 0;
const SCAN_EVERY = 120000;          /* دقيقتان */

function runPeriodicScans(force) {
  const now = Date.now();
  if (!force && now - SCAN_AT < SCAN_EVERY) return;
  SCAN_AT = now;

  try { if (typeof scanAlerts === "function") scanAlerts(); } catch (e) {}

  try {
    if (typeof fetchPrayerTimes === "function" && prayerCfg().on && !prayerTimes()) {
      fetchPrayerTimes().then(t => { if (t) mount(); });
    }
    if (typeof autoHolidayScan === "function" && FB_LOADED) autoHolidayScan();
  } catch (e) {}

  try { if (typeof syncMyScope === "function" && FB_LOADED) syncMyScope(); } catch (e) {}
  try { if (typeof runDailyRoll === "function") runDailyRoll(); } catch (e) {}

  try {
    if (typeof scanNotifications === "function") scanNotifications();
    if (typeof scanDataGaps === "function" && FB_LOADED) scanDataGaps();
  } catch (e) {}
}

function mount() {
  /* الفحوص الثقيلة كلّ دقيقتين — والشارات مع كلّ رسم لأنها خفيفة */
  try { runPeriodicScans(); } catch (e) {}
  /* مغادرةُ المصحف تُغلق مستمعَه اللحظيّ */
  try { if (STATE.page !== "mushaf" && typeof musLiveStop === "function" && MUS_LIVE.off) musLiveStop(); } catch (e) {}

  /* قوائمُ السور في أي شاشة: الفهرسُ يُجلب من الشبكة فقد لا يكون حاضراً
     وقت الرسم، فتبقى القائمةُ فارغةً بلا سبب ظاهر. تُملأ بعد كلّ رسم —
     والدالّةُ تنصرف فوراً إن لم تجد قائمةً تنتظر. */
  try { setTimeout(function () { if (window.plFillSurahs) window.plFillSurahs(); }, 0); } catch (e) {}

  try { if (typeof offqBadge === "function") offqBadge(); } catch (e) {}

  /* منتقيات ما بعد الرسم: عناصرُها تُبنى مع الصفحة فتُملأ بعدها */
  try {
    if (document.getElementById("tmsgBox") && typeof tmsgRender === "function") tmsgRender();
    if (document.getElementById("usKidBox") && typeof usKidRender === "function") usKidRender();
  } catch (e) {}
  try { if (typeof updateNotifBadge === "function") updateNotifBadge(); } catch (e) {}

  /* صورة الشريط تُحدَّث مع كل رسم، فتظهر فور الحفظ بلا إعادة تحميل */
  try { if (window.refreshTopbarPhoto) window.refreshTopbarPhoto(); } catch (e) {}

  /* الواجهة تُصحَّح عند كل رسم، فلا يكفي تعديل STATE.iface يدوياً للتحايل */
  const allow = allowedIface();
  if (allow && STATE.iface !== allow) {
    STATE.iface = allow;
    if (!NAV[allow].some(x => x.id === STATE.page)) STATE.page = NAV[allow][0].id;
  }

  if (scopeDenied()) {
    const root0 = $("#pageContent");
    if (root0) {
      root0.innerHTML = `<div class="page">${pageHead("حسابك غير مرتبط بمنشأة", "")}
        <div class="card">${emptyState("لا توجد بيانات لعرضها",
          "حسابك لم يُربط بمسجد أو مجمع بعد، فلا يمكن عرض أي بيانات. راجع إدارة النظام لربط حسابك بالمنشأة التي تعمل بها.")}</div>
      </div>`;
      runAnimations(root0);
    }
    return;
  }

  const fn = PAGES[`${STATE.iface}/${STATE.page}`];
  const html = fn ? fn() : `<div class="page">${emptyState("الصفحة غير متاحة", "تأكد من الرابط أو ارجع للوحة التحكم.")}</div>`;
  const root = $("#pageContent");
  /* عنوان التبويب من عنوان الصفحة المعروضة */
  setTimeout(function () {
    const h = document.querySelector("#pageContent .page-head h2");
    if (h) setDocTitle(h.textContent.trim());
  }, 0);
  if (!root) return;
  root.innerHTML = (typeof trmViewBanner === "function" ? trmViewBanner() : "") +
    (typeof alertLateBanner === "function" ? alertLateBanner() : "") + html;
  root.scrollTop = 0;
  try { if (typeof window.tbPeriodSync === "function") window.tbPeriodSync(); } catch (e) {}
  runAnimations(root);
  try { fabRender(); } catch (e) { console.warn("fab:", e); }
  try { updateMsgBadge(); } catch (e) { /* الشريط غير موجود بعد */ }
}

/* =========================================================
   ANIMATIONS
   ========================================================= */
function runAnimations(root) {
  if (!root) return;
  $$("[data-count]", root).forEach(el => {
    const target = parseFloat(el.dataset.count);
    const suffix = el.dataset.suffix || "";
    if (Number.isNaN(target)) { el.textContent = "0" + suffix; return; }
    const dur = 900, start = performance.now();
    function step(now) {
      const t = Math.min((now - start) / dur, 1);
      const eased = 1 - Math.pow(1 - t, 3);
      el.textContent = Math.round(target * eased) + suffix;
      if (t < 1) requestAnimationFrame(step);
      else el.textContent = target + suffix;
    }
    requestAnimationFrame(step);
  });
  requestAnimationFrame(() => requestAnimationFrame(() => {
    $$(".progress > span[data-pct]", root).forEach(sp => { sp.style.width = sp.dataset.pct + "%"; });
  }));
}

/* =========================================================
   COMPONENTS — modals, panels, toasts
   ========================================================= */
function openModal(title, sub, body, foot) {
  const root = $("#modalRoot");
  if (!root) return;
  root.innerHTML = `<div class="modal-back" data-action="close-modal">
    <div class="modal" data-stop>
      <div class="modal-head"><div><h3>${esc(title)}</h3>${sub ? `<div class="mh-sub">${esc(sub)}</div>` : ""}</div>
        <button class="modal-close" data-action="close-modal">${ic("x", 18)}</button></div>
      <div class="modal-body">${body}</div>
      ${foot ? `<div class="modal-foot">${foot}</div>` : ""}
    </div></div>`;
}
function closeModal() { const r = $("#modalRoot"); if (r) r.innerHTML = ""; }

function openPanel(html) {
  const r = $("#panelRoot");
  if (!r) return;
  r.innerHTML = html;
  /* الصفحةُ خلف البطاقة تُقفل: كانت تُمرَّر تحتها ويظهر طرفُها من حولها،
     فتبدو البطاقةُ نافذةً على صفحةٍ لا صفحةً قائمةً بنفسها. */
  document.body.classList.add("panel-open");
  /* أشرطةُ التقدّم تُملأ بعرضٍ يُضبط بعد الرسم — كانت تُملأ في mount()
     وحدها، واللوحةُ تُفتح خارجه فيبقى الشريطُ فارغاً وإن كانت النسبةُ
     مكتوبةً بجانبه. */
  requestAnimationFrame(() => requestAnimationFrame(() => {
    r.querySelectorAll(".progress > span[data-pct]").forEach(sp => {
      sp.style.width = (sp.dataset.pct || 0) + "%";
    });
  }));
}
function closePanel() {
  const r = $("#panelRoot");
  if (r) r.innerHTML = "";
  document.body.classList.remove("panel-open");
  /* مسوّدةُ بطاقة الطالب تعيش ما دامت البطاقةُ مفتوحة */
  try { if (typeof stuDraftReset === "function") stuDraftReset(""); } catch (e) {}
}

function showToast(msg, type) {
  type = type || "success";
  const icons = { success: "checkCircle", info: "info", warn: "alert" };
  const titles = { success: "تم بنجاح", info: "معلومة", warn: "تنبيه" };
  const root = $("#toastRoot");
  if (!root) return;
  const el = document.createElement("div");
  el.className = `toast ${type}`;
  el.innerHTML = `<div class="toast-ico">${ic(icons[type] || "info", 18)}</div><div class="toast-text"><strong>${esc(titles[type] || "")}</strong><small>${esc(msg)}</small></div>`;
  root.appendChild(el);
  setTimeout(() => { el.classList.add("out"); setTimeout(() => el.remove(), 350); }, 3200);
}

function formField(label, type, opts, id) {
  const idAttr = id ? ` id="${id}"` : "";
  if (type === "select") return `<div class="field"><label>${esc(label)}</label><select${idAttr}>${opts.map(o => `<option>${esc(o)}</option>`).join("")}</select></div>`;
  if (type === "full") return `<div class="field full"><label>${esc(label)}</label><input${idAttr} placeholder="${esc(opts || "")}"></div>`;
  if (type === "tel") return `<div class="field"><label>${esc(label)}</label><input${idAttr} type="tel" inputmode="numeric" placeholder="${esc(opts || "")}" oninput="this.value=this.value.replace(/[^0-9]/g,'')"></div>`;
  if (type === "time") return `<div class="field"><label>${esc(label)}</label><input${idAttr} inputmode="numeric" maxlength="5" placeholder="${esc(opts || "")}" oninput="let v=this.value.replace(/[^0-9]/g,'').slice(0,4);this.value=v.length>2?v.slice(0,2)+':'+v.slice(2):v"></div>`;
  return `<div class="field"><label>${esc(label)}</label><input${idAttr} placeholder="${esc(opts || "")}"></div>`;
}

