/* =========================================================================
   صورة الشخص — منتقٍ مشترك للطالب والمعلم والمستخدم
   -------------------------------------------------------------------------
   Firebase Storage غير مفعّل على المشروع، والصور في هذا النظام تُخزَّن
   base64 داخل مستند Firestore (كما في شعارات المنشآت). وحدّ المستند
   ميغابايت واحد، ولأن loadAllData تنزّل المجموعات كاملة على كل جهاز فإن
   حجم الصورة يُضرب في عدد الأشخاص. لذلك تُصغَّر إلى 160 بكسل بجودة 0.72،
   فيبقى الملف نحو 6–9 كيلوبايت لا 300.
   ========================================================================= */

const PHOTO_MAX = 160;
const PHOTO_Q   = 0.72;

function photoField(id, current, label) {
  const src = current || "";
  return `<div class="field full pf-field">
    <label>${esc(label || "الصورة الشخصية")}</label>
    <div class="pf-row">
      <div class="pf-avatar" id="${id}_av">${src
        ? `<img src="${esc(src)}" alt="">`
        : `<span class="pf-ph">${ic("user", 24)}</span>`}</div>
      <div class="pf-actions">
        <button type="button" class="btn btn-ghost btn-sm"
          onclick="document.getElementById('${id}_input').click()">${ic("plus", 15)} اختر صورة</button>
        <button type="button" class="btn btn-ghost btn-sm" id="${id}_del"
          onclick="window.photoClear('${id}')" ${src ? "" : 'style="display:none"'}>${ic("x", 15)} إزالة</button>
        <div class="muted" style="font-size:11.5px">JPG أو PNG — تُصغَّر تلقائياً</div>
      </div>
    </div>
    <input type="file" id="${id}_input" accept="image/*" style="display:none"
      onchange="window.photoPick(this, '${id}')">
  </div>`;
}

/* الصور المختارة في النموذج الحالي، تُقرأ عند الحفظ */
const PHOTO_BUF = {};

window.photoPick = function (input, id) {
  const f = input.files && input.files[0];
  if (!f) return;
  if (!/^image\//.test(f.type)) { showToast("اختر ملف صورة صالحاً", "warn"); input.value = ""; return; }
  if (f.size > 6 * 1024 * 1024) { showToast("حجم الصورة كبير — أقصى 6 ميغابايت", "warn"); input.value = ""; return; }

  const reader = new FileReader();
  reader.onerror = function () { showToast("تعذّرت قراءة الصورة", "warn"); };
  reader.onload = function (e) {
    const img = new Image();
    img.onerror = function () { showToast("الملف ليس صورة صالحة", "warn"); };
    img.onload = function () {
      /* قصّ مربع من الوسط ثم تصغير — فلا تتشوّه الصور الطولية */
      const side = Math.min(img.width, img.height);
      const sx = (img.width - side) / 2, sy = (img.height - side) / 2;
      const cv = document.createElement("canvas");
      cv.width = PHOTO_MAX; cv.height = PHOTO_MAX;
      cv.getContext("2d").drawImage(img, sx, sy, side, side, 0, 0, PHOTO_MAX, PHOTO_MAX);

      const data = cv.toDataURL("image/jpeg", PHOTO_Q);
      PHOTO_BUF[id] = data;

      const av = document.getElementById(id + "_av");
      if (av) av.innerHTML = '<img src="' + data + '" alt="">';
      const del = document.getElementById(id + "_del");
      if (del) del.style.display = "";
    };
    img.src = e.target.result;
  };
  reader.readAsDataURL(f);
};

window.photoClear = function (id) {
  PHOTO_BUF[id] = "";
  const av = document.getElementById(id + "_av");
  if (av) av.innerHTML = '<span class="pf-ph">' + ic("user", 24) + '</span>';
  const del = document.getElementById(id + "_del");
  if (del) del.style.display = "none";
  const inp = document.getElementById(id + "_input");
  if (inp) inp.value = "";
};

/* قيمة الصورة عند الحفظ: المختارة إن وُجدت، وإلا القديمة */
function photoVal(id, current) {
  return PHOTO_BUF[id] !== undefined ? PHOTO_BUF[id] : (current || "");
}

function photoReset(id) { delete PHOTO_BUF[id]; }

/* =========================================================================
   حقلا المنشأة — المجمع ثم المسجد
   -------------------------------------------------------------------------
   القائمة الموحّدة السابقة كانت تخلط المستويين في خانة واحدة، فلا يظهر
   للإدارة أي مجمع ينتمي إليه الطالب إلا بالاستنتاج. صارا حقلين مرتبطين:
   اختيار المجمع يحصر المساجد المعروضة على مساجده، ويبقى خيار «بلا مسجد»
   لمن يتبع المجمع مباشرة.
   ========================================================================= */

/* المسجدُ الذي لا اختيارَ فيه: من دخل مسجداً بعينه، أو من لا مسجدَ له
   سواه لأن دورَه مديرُ مسجد. سؤالُه عن المسجد سؤالٌ عمّا يعرفه النظام. */
function facLockedMosqueId() {
  try {
    var c = facCtx();
    if (c && c.coll === "mosques" && c.id) return String(c.id);
  } catch (e) {}
  var u = (typeof STATE !== "undefined" && STATE.user) || {};
  /* المشرفُ كمدير المسجد: مسجدُه واحدٌ لا يختار غيره، فلا يُسأل عنه */
  var r = String(u.role || "");
  if ((r === "mosqueManager" || r === "supervisor") && u.mosqueId) return String(u.mosqueId);
  return "";
}

function facTwoFields(idCx, idMq, curCxId, curMqId) {
  const cx = cur("complexes"), mq = cur("mosques");

  /* المسجدُ محسومٌ: يُكتب في حقلٍ مخفيّ ويُعرض اسمُه للعلم لا للاختيار.
     الحقلُ المخفيّ ضروريٌّ لأن الحفظَ يقرأ القيمةَ بـ val("#id"). */
  const lockMq = facLockedMosqueId();
  if (lockMq) {
    const lm = mq.find(x => String(x.id) === lockMq) || {};
    return `<input type="hidden" id="${idCx}" value="${esc(String(lm.complexId || ""))}">
      <input type="hidden" id="${idMq}" value="${esc(lockMq)}">
      <div class="field" style="grid-column:1/-1"><label>المسجد</label>
        <div class="kv" style="border-bottom:0;padding:9px 0">
          <strong>${esc(lm.name || "—")}</strong>
          <span class="muted" style="font-size:12px">يُنسب تلقائياً</span>
        </div></div>`;
  }

  /* المجمع الحالي: المصرَّح به، أو المشتقّ من المسجد */
  let cxId = String(curCxId || "");
  if (!cxId && curMqId) {
    const m = mq.find(x => String(x.id) === String(curMqId));
    if (m) cxId = String(m.complexId || "");
  }

  /* والمجمّعُ كذلك: مجمّعٌ خارجَ نطاق الرؤية لا يُمحى بفتح النموذج */
  let cxList = cx.slice();
  if (cxId && !cxList.some(c => String(c.id) === cxId)) {
    const ownCx = (Array.isArray(DB.complexes) ? DB.complexes : [])
      .find(c => String(c.id) === cxId);
    if (ownCx) cxList = cxList.concat([ownCx]);
  }
  const cxOpts = `<option value="">— بلا مجمع (مستقل) —</option>` +
    cxList.map(c => `<option value="${esc(String(c.id))}" ${String(c.id) === cxId ? "selected" : ""}>${esc(c.name || "—")}</option>`).join("");

  let inCx = cxId ? mq.filter(m => String(m.complexId || "") === cxId) : mq;
  /* =======================================================================
     المسجدُ الحالي يبقى في القائمة ولو خالف مجمَّعه
     -----------------------------------------------------------------------
     القائمةُ تُحصر بمساجد المجمّع المختار. فسجلٌّ قديمٌ مسجدُه بلا مجمّع،
     أو مسجدُه في مجمّعٍ آخر، لا يجد قيمتَه في القائمة فتُقرأ فارغةً —
     ويُمحى مسجدُه بمجرّد فتح النموذج وحفظه. تُضاف قيمتُه الحالية دائماً.
     ======================================================================= */
  if (curMqId && !inCx.some(m => String(m.id) === String(curMqId))) {
    const own = mq.find(m => String(m.id) === String(curMqId));
    if (own) inCx = inCx.concat([own]);
  }
  const mqOpts = `<option value="">— بلا مسجد —</option>` +
    inCx.map(m => `<option value="${esc(String(m.id))}" ${String(m.id) === String(curMqId || "") ? "selected" : ""}>${esc(m.name || "—")}</option>`).join("");

  return `<div class="field"><label>المجمع التعليمي</label>
      <select id="${idCx}" onchange="window.facCxChange('${idCx}','${idMq}')">${cxOpts}</select></div>
    <div class="field"><label>المسجد</label>
      <select id="${idMq}">${mqOpts}</select>
      <div class="hint" id="${idMq}_hint"></div></div>`;
}

/* تغيير المجمع يعيد بناء قائمة مساجده */
window.facCxChange = function (idCx, idMq) {
  const cxSel = document.getElementById(idCx);
  const mqSel = document.getElementById(idMq);
  const hint  = document.getElementById(idMq + "_hint");
  if (!cxSel || !mqSel) return;

  const cxId = cxSel.value;
  const list = (cur("mosques") || []).filter(m => !cxId || String(m.complexId || "") === String(cxId));

  mqSel.innerHTML = `<option value="">— بلا مسجد —</option>` +
    list.map(m => `<option value="${esc(String(m.id))}">${esc(m.name || "—")}</option>`).join("");

  if (hint) {
    hint.textContent = cxId && !list.length
      ? "لا مساجد في هذا المجمع بعد — سيتبع الطالب المجمع مباشرةً."
      : "";
  }
};

/* قراءة الحقلين عند الحفظ */
function facTwoValue(idCx, idMq) {
  const cxId = val("#" + idCx) || "";
  const mqId = val("#" + idMq) || "";
  const m = mqId ? (cur("mosques") || []).find(x => String(x.id) === String(mqId)) : null;
  return {
    mosqueId: mqId,
    mosque: m ? (m.name || "—") : "—",
    /* المجمع المصرَّح به، وإلا مجمع المسجد المختار */
    complexId: cxId || (m ? (m.complexId || "") : "")
  };
}

/* =========================================================================
   مستويات البرنامج · تاريخ الميلاد · أيام الحلقة
   -------------------------------------------------------------------------
   نموذج الطالب كان يعرض أربعة نصوص ثابتة للمستوى لا صلة لها ببرنامجه،
   ويحفظ العمر رقماً جامداً يشيخ معه الطالب ولا يشيخ، وأيام الحضور نصاً
   حراً بينما الحلقة تحمل أيامها منظّمة.
   ========================================================================= */

/* مستويات برنامجٍ بالاسم — النموذج يعرف اسم البرنامج لا معرّفه */
function lvOptionsFor(programName, selId) {
  const pg = (cur("programs") || []).find(x => String(x.name) === String(programName));
  if (!pg) return [];
  return (cur("levels") || [])
    .filter(x => String(x.programId) === String(pg.id) && x.status !== "موقوف")
    .sort((a, b) => (Number(a.order) || 0) - (Number(b.order) || 0));
}

/* حقل المستوى: يتبع البرنامج المختار ويُحدَّث بتغيّره */
function levelField(id, programName, currentId, currentName) {
  const lv = lvOptionsFor(programName);
  if (!lv.length) {
    return `<div class="field"><label>المستوى</label>
      <select id="${id}"><option value="">— لا مستويات لهذا البرنامج —</option></select>
      <small style="font-size:11px;color:var(--text-faint)">عرّفها من الإعدادات ← البرامج والمستويات</small>
    </div>`;
  }
  return `<div class="field"><label>المستوى</label><select id="${id}">
    ${lv.map(x => {
      const sel = String(currentId) === String(x.id) ||
                  (!currentId && String(currentName) === String(x.name));
      return `<option value="${esc(x.id)}"${sel ? " selected" : ""}>${esc(x.name)}${
        x.qty ? " — " + toArabicDigits(x.qty) + " " + esc(x.unit || "وجه") : ""}</option>`;
    }).join("")}</select></div>`;
}

/* تبديل البرنامج يعيد بناء قائمة المستوى: مستوى من برنامج آخر ربطٌ خاطئ */
/* حقولُ الخطّة لا تُعرض لمن سُجّل للتحضير وحده: عرضُها يوهم بأنها مطلوبة. */
window.stuEnrollChanged = function () {
  var v = val("#s_enroll", "");
  var show = v === "plan";
  ["s_progWrap", "s_levelWrap"].forEach(function (id) {
    var el = document.getElementById(id);
    if (el) el.style.display = show ? "" : "none";
  });
};

window.stuProgChanged = function (progSel, lvlSel) {
  const pEl = document.getElementById(progSel), lEl = document.getElementById(lvlSel);
  if (!pEl || !lEl) return;
  const lv = lvOptionsFor(pEl.value);
  lEl.innerHTML = lv.length
    ? lv.map(x => `<option value="${esc(x.id)}">${esc(x.name)}${
        x.qty ? " — " + toArabicDigits(x.qty) + " " + esc(x.unit || "وجه") : ""}</option>`).join("")
    : '<option value="">— لا مستويات لهذا البرنامج —</option>';
};

/* الاسم من المعرّف — يُحفظ الاثنان: المعرّف للربط والاسم ليبقى مقروءاً */
function lvNameById(id) {
  const l = (cur("levels") || []).find(x => String(x.id) === String(id));
  return l ? (l.name || "") : "";
}

/* العمر من تاريخ الميلاد: القيمة المحفوظة تشيخ مع صاحبها */
function ageFromBirth(birth) {
  if (!birth) return null;
  const d = new Date(birth);
  if (isNaN(d.getTime())) return null;
  const n = Math.floor((Date.now() - d.getTime()) / 31557600000);
  return n >= 0 && n < 120 ? n : null;
}

/* أيام الحلقة — الطالب يرثها بدل كتابتها نصاً حراً */
function circleDaysOf(circleName) {
  const c = (cur("circles") || []).find(x => String(x.name) === String(circleName));
  if (!c) return "";
  const d = c.days || c.circleDays;
  return Array.isArray(d) ? d.join(" · ") : String(d || "");
}

