/* =========================================================================
   الارتباط التراتبي بين الواجبات
   -------------------------------------------------------------------------
   كان في نوع الواجب حقلٌ واحد: blocks — «يمنع الواجب التالي» أو لا. وهو
   يمنع التاليَ كائناً ما كان، فلا يُعرف أيُّ واجبٍ يسبق أيّاً، ولا يُقال
   «لا يُفتح التسميع حتى تُسمَّع التلاوة» بعينها.

   يُضاف حقلان يبنيان سلسلةً حقيقية:
     • order   — ترتيبٌ تصاعديٌّ بالألزم. الأصغرُ يُطلب أوّلاً.
     • needsId — معرّفُ الواجب الذي يشترطه هذا الواجب. فارغٌ = لا شرط.

   والفتحُ يُحسب في dutyUnlocked: يُغلق الواجبُ إن كان شرطُه غيرَ منجزٍ
   اليوم، أو إن سبقه في الترتيب واجبٌ مانعٌ (blocks) لم يُنجز بعد.
   المنطقُ في المحرّك لا في الواجهة: الواجهةُ تقرؤه ولا تقرّره.
   ========================================================================= */
function dutyTypesOrdered() {
  return (Array.isArray(DB.dutyTypes) ? DB.dutyTypes : [])
    .filter(x => x && x.active !== false)
    .slice()
    .sort((a, b) => (Number(a.order) || Number(a._o) || 0) - (Number(b.order) || Number(b._o) || 0));
}

function dutyTypeByName(name) {
  return (Array.isArray(DB.dutyTypes) ? DB.dutyTypes : [])
    .find(x => x && String(x.name) === String(name)) || null;
}

/* أُنجز واجبٌ من هذا النوع للطالب في اليوم؟ يُقرأ من الواجبات المسجّلة. */
function dutyDoneToday(studentId, typeName, dateISO) {
  const d = dateISO || todayISO();
  return (Array.isArray(DB.assignments) ? DB.assignments : []).some(a =>
    a && String(a.studentId) === String(studentId) &&
    String(a.date) === String(d) &&
    String(a.kind || a.type || "") === String(typeName) &&
    (a.done === true || a.status === "منجز" || Number(a.score) > 0));
}

/* هل هذا الواجب مفتوح اليوم؟ يعيد السبب حين يكون مغلقاً. */
function dutyUnlocked(studentId, typeName, dateISO) {
  const t = dutyTypeByName(typeName);
  if (!t) return { open: true };

  /* شرطٌ صريح: واجبٌ بعينه يسبقه */
  if (t.needsId) {
    const need = (DB.dutyTypes || []).find(x => String(x.id) === String(t.needsId));
    if (need && !dutyDoneToday(studentId, need.name, dateISO)) {
      return { open: false, why: "يسبقه: " + (need.name || "واجب آخر") };
    }
  }

  /* ترتيبٌ تصاعديّ: كلُّ مانعٍ أدنى ترتيباً يجب أن يُنجَز أوّلاً */
  const mine = Number(t.order) || Number(t._o) || 0;
  const blocker = dutyTypesOrdered().find(x => {
    if (String(x.id) === String(t.id)) return false;
    if (x.blocks !== true) return false;
    const o = Number(x.order) || Number(x._o) || 0;
    if (o >= mine) return false;
    return !dutyDoneToday(studentId, x.name, dateISO);
  });
  if (blocker) return { open: false, why: "يسبقه: " + (blocker.name || "واجب مانع") };

  return { open: true };
}
window.dutyUnlocked = dutyUnlocked;

/* كانت تحمل اسم modalDuty نفسَه، فتطغى — لأنها الأخيرة — على نافذة «واجب
   الطالب» (modalDuty(studentId)): زرُّ واجب الطالب وواجبُ الغد والزرُّ العائم
   كانت تفتح نافذةَ «إضافة نوع واجب» بدلها، فلا يصل المعلّم إلى مسار الخطة. */
